/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250310-3","meetingId":"r07-c-budget","date":"2025年3月10日","dateIso":"2025-03-10","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を163件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"私からは２６７ページ、ファミリーサポートセンター運営費、同じく２６７ページ、ヤングケアラー支援事業についてお伺いいたします。令和７年度予算では、ファミリーサポートセンター運営費なのですが、３,２０９万８,０００円が計上されていますけれども、内訳をお知らせください。","respondent":"染谷子ども家庭支援センター長","answer":"ファミリーサポートセンター事業ですが、こちら、区のエリアを大きく２つに分けて、平塚と大井に事務局を設け、それぞれ委託により運営をしています。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"アドバイザー人件費や事務費などが主なものということで、アドバイザー人件費については、後ほどお伺いさせてというか、触れします。現在の提供会員と依頼会員の登録人数、あわせて、区としてどのような課題があるとお考えでしょうか、説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"もう一方の依頼会員の登録数につきましては、４,１５６人となっております。提供会員の成り手を増やすための取組が必要であると考えているところです。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"子どもの手が離れてきた４０代から６０代のミドルシニア世代というものをターゲットに、周知を行っていただくことも必要ではないのでしょうか。ぜひ区として、ご見解を説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"こちら都の補助事業を活用しながら実施していきたいと考えております。それから普通救命講習のテキスト代、こちらにつきましても、新規、それから更新の方も含めて、無償とするよう実施していきたいと考えております。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"シッターサービスの需要も高まっていますが、今の割合をお伺いすると、ファミサポではそれほどまだ活用されていないのかなという印象も受けます。提供会員宅での預かりということも１つネックになっていると考えますが、潜在的な需要の洗い出しを行うことや、区のご見解を説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"今回拡大を予定しておりまして、これまでの提供会員宅に加えて、依頼会員宅での預かりについても実施していきたいと考えております。実施方法については様々な課題があるかと思いますけれども、そちらのほう、他区の事例など参考にしながら実施していきたいと考えております。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"一般質問でもお伺いしましたが、安心・安全な環境の、さらに整備していただけることを要望して次へ移ります。現在図書館や区立幼稚園・保育園、児童館など区有施設において、取扱いのある施設はあるのか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"』というタイトルの絵本かと思います。そのほかヤングケアラー関連の書籍が、児童図書やティーンズ向けのものも含めて、各地区館に数十点取扱いがあるという状況です。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"小学生以上になると、子どもたちによってはもう少し深い内容、濃い内容を求めるということもあるのではないかと思います。その辺を取り扱う施設の拡充と、絵本や漫画の取扱いを増やしていただくとともに、ヤングケアラーの漫画の導入について区の見解を説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーの支援の課題としまして、１つケアの状況が表面化しづらいというところがあるかと思います。そういった漫画などの活用をして、啓発用の教材として活用していくことは、非常に有効であると考えております。","id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"それとともに、より一層の理解を促すためにも、今おっしゃっていただいた漫画の導入以外にも、防災教育、中学生に向けての防災教育のように、アニメや動画の制作なども視野に入れ、アプローチしていただくことをお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"２４１ページ、中等度難聴者への補聴器購入費助成について、順不同で伺います。お伺いをいたします。","respondent":"松山障害者支援課長","answer":"中等度難聴者への補聴器購入助成ですが、委員のおっしゃるとおり、東京都の事業とは別の、区独自の事業です。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ニーズを確認しながら、１８歳以上の方にもぜひ助成の検討をと要望させていただきましたので、先ほど確認をいたしましたが。そこで、助成するに至った経緯と、この事業が今後継続をして行っていただけるのか、お伺いをいたします。","respondent":"松山障害者支援課長","answer":"検討した結果、聞こえの能力の向上や費用負担の軽減から必要であると区として強く認識し、事業化に至ったものです。全世代、中等度の難聴者のさらなる社会参加の促進を図るものと考えておりますので、継続していきたいと考えています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"所得制限なく行ってほしいと求めました。そしてまた、修理費用が対象となっていないこと、所得制限の考え方をお伺いいたします。","respondent":"松山障害者支援課長","answer":"障害者手帳を所持する難聴者の方が使用する補聴器につきましては、修理はございません。今のところ制度の変更というものは、国の制度に合わせているところなので非常に難しいところですが、国の動向を今後とも注視してまいります。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"８３０万円の予算の内容を伺います。対象者をお知らせいただくとともに、今年度行われた高齢者世帯実態調査での、区内のおひとり暮らしの高齢者と高齢者世帯の人数をお伺いいたします。","respondent":"東野福祉計画課長","answer":"こちらが大体９０名から１００名ぐらいをめどとして、そのぐらいの見込みとしての補助を用意しているものです。１万９,９０６人、こちらは７５歳以上と７０歳以上で構成される高齢者世帯員ですが、こちらが１万７,８２３人おりました。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在５０人が既に利用されていて、倍増するのではないかということの予算立てというように確認をいたしました。一方で、今高齢者のひとり暮らし、また、世帯の確認をさせていただきましたが、今いただきました数を合わせると３万７,０００人を超えている。","respondent":"東野福祉計画課長","answer":"それからデジタル関係、ＳＮＳなども使いまして、様々周知を行っていく予定です。広報紙なども活用していく予定です。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのような広報紙等々、必要だと思いますが、直接、やはり高齢の方ですので、確実に高齢者の対象の方に届くような、民生委員を通じて等々、高齢者クラブ等も含めて、大きく周知を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"２３９ページ、２６３ページの青少年育成事業について、時間が許せば２８９ページの里親養育包括支援（フォスタリング）事業について伺います。障害者支援区分の入居者数について、改めて品川区の現状を説明を求めました。","respondent":"松山障害者支援課長","answer":"障害者グループホーム運営費助成に係る品川区の現状ということでお答えします。この障害者グループホーム運営費助成の中の中重度障害者受入助成を検討するに当たりまして、区分４が８人、区分３が１２人という状況です。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"特に区分５、６というところはなかなか入居が難しいというところで、確認をさせていただきました。別途厚生委員会等でも要望しておりました、障害者区分に応じた運営費の助成、令和７年度より始まるということで大変期待をしております。","respondent":"松山障害者支援課長","answer":"有資格者配置助成につきまして検討したところ、サービスの質の確保の観点から、年数等については国からも示されており、難しいところです。その検討に至る経過の中で、今回、中重度障害者受入助成というものを初めてご提案するものです。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"では、有資格者の助成というところではなくて、中重度の受入助成のところにシフトしたというような形で認識をしてよろしいでしょうか。全体の予算、そして各区分の想定の人数はどうやって決定をしていたのか、参考にした自治体等もあれば説明を求めました。","respondent":"松山障害者支援課長","answer":"中重度受入助成については、まず有資格者助成については継続をさせていただきまして、有資格者の人を配置していただきたいというものが区の目的です。この金額につきましては、２３区調べたところ、あまり実施している区がなく、練馬区を参考にさせていただいたものです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"確認","question":"その予算の規模としては、今入っている入居者の方々に当てはめて金額を算出したというところも確認をさせていただきました。４についても一律１.５万円ずつ下げるという形を取っていると思うのですけれども、品川区はどのように検討したのかというところも説明を求めました。","respondent":"松山障害者支援課長","answer":"品川区の場合、中重度の障害者の受入助成を検討する際に、前提として、有資格者助成をまず検討したということがあります。給付費の４分の１程度ということの想定を区分５、６から割り出しまして、その同じ割合で区分３と４ということで金額を想定したものです。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"次に、青少年育成事業について伺います。もっと品川区、そして日本でも増えていかないかなと思っておりましたし、要望等でもさせていただいておりました。","respondent":"柴田子ども施策連携担当課長","answer":"その中で若者に特化した支援というものは、ほかのライフステージと比べると少ないというように認識をしています。その点から課題を把握して、どのような施策が区において必要か、そういった点について研究してまいりたいと考えています。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"要件を見てみますと１９歳までというようになっておりますが、年齢を決めたきっかけというところも聞かせていただきたいなと考えています。月１回に行われておりますしなわかカフェ、しっかりとオープンに話しやすい雰囲気というところを意識してほしいなと思うのですけれども。","respondent":"柴田子ども施策連携担当課長","answer":"こちらのご紹介をしますと、月に１回、区内の児童センターにおいて対面相談会というものをやっております。いろいろなおしゃべりをする中で、子どもたちにより知っていただいてアクセスしてもらえる、そういったしなわかカフェを目指しています。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"アクセサリーの製作、ネイルアートなど、少し年齢層高めに設定をしているというようなお話を伺っております。ぜひ２０代も、そちらについても対応をぜひ検討していただきたいなと思いますが、いかがか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"現在は中学生以上の１０代の若者というようにしているのですけれども、実績として、１５歳から１７歳が多く利用していただいている状況です。２４歳など、それから社会の動きと、研究しながら対応してまいります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"本当はすぐ定員割れ加算制度について伺いたいところなのですけれども、昨年４月、まずはここをたださなくてはいけません。それと、共働き世帯の割合の推移について、近年増えているのか、減っているのか、伺います。","respondent":"中島保育施設運営課長、芝野保育入園調整課長","answer":"保育園でも、その観点から、子どもたちの成長をしっかりと支えているところです。子どもたちの育児を専門家の方から、そのような面でも、親にとってもメリットがあると考えているところです。 今策定中の品川区総合計画実施計画の中で、これは２０４６年、令和２８年にピークを迎えるです。１０年前と比較しますと、やはり１０ポイント以上、１０％以上上がっているというような状況です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、あり方基本方針の具体化はしないよう求めますが、いかがでしょうか。それともスクラップ・アンド・ビルドの対象と考えているのか、伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"あり方検討の内容というか、そちらのほうをお答えしますが、令和４年度に待機児童ゼロを達成しています。もう１点、こちらは生活基盤を支えるものとして、しっかりと推進をしていきたいと考えております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"次に定員割れ加算について伺いたいのですが、２０２３年１月の調査時点なのですけれども、品川区含め３区だけでした。改めて、この補助をやらない理由というのですか、こういった保育士、現場の声も踏まえて、どのように考えているのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"民間の保育市場に与える影響が大きいということと、もし対象外となってしまった認可外施設の方たちの不公平感などの様々な課題があると考えて、実施のほうを検討してございません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"見直しを求める、実施を求めることがいかがでしょうかということと、これ株式会社以外でやれているところというものは何園ぐらいあるのですか。無理だったらあれですけれども、伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"しっかりと対応していきたいと思っているのですが、今年度対象経費の拡大、あと補助額の拡大というものをしています。そういったものにも活用していただけるようになってありますので、今後広く導入、参加していただきたいと考えているところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひこの事業、補助を実施してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"保育園関連についてお伺いいたしますけれども、これ私立保育園の事業者の方からご要望を受けたのですが、お話をします。そうした入園前のお子様の日本語の習得状況や能力などの状況の情報提供をぜひしていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"中島保育施設運営課長","answer":"園児、そして保護者の方の語学、言語での対応についてです。現場では保育士もしっかりと対応していますし、言語も習得をする時期ですので、ほかの園児と日々遊ぶ中で言語を覚えているところです。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"確認の際、なかなか確認し切れないパターンなどがあるかと思うのですが、よろしくお願い申し上げます。ぜひそうした感染症予防という観点で、この保育園サーベイランスについて現状どのように把握をされているのか、お考えを説明を求めました。","respondent":"中島保育施設運営課長","answer":"現場ではしっかり感染対策に努めているところで、特段の支障なく園運営はできているというようには認識しています。そのような取組など情報収集しまして、うまく活用できているかなど、導入の効果なども情報把握をしてまいりたいと考えています。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"感染症毎月確認されているということですけれども、そうした早期対応という観点から、このサーベイランスの検討をぜひ行ってほしいと求めました。令和７年度では令和６年度のような予算化はやらないという状況ですが、令和７年度ではやめられた理由は何か、お伺いをいたします。","respondent":"菅野高齢者福祉課長","answer":"有償ボランティアマッチングサービススケッターを６か月、無償トライアルの利用ということで、現在９月から２月までということで実施をしています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"令和６年度は予算化、１１事業者は継続ということで、そのほかの事業者の方が継続しなかった理由は何か把握されていますでしょうか。品川区はなぜ協定ということを結ばなかったのか、その理由も説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"その辺り、今年度委託でさせていただいたというところで、東京都のほうの４分の３の補助もいただいて実施させていただきました。様々と聞いておりますので、区としては委託事業として実施をさせていただいて、協定以上の効果を生み出して実施させていただいたと考えています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"いずれにしても、今回スケッター側の課題ということもいろいろ見えてきたかなと考えています。１つ明るい動きだと思いますので、有形の支援を行ってほしいと求めましたが、いかがお考えか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"このスケッター事業で、こちらの会社のほうが実施をした、有償ボランティアを集めた説明会や交流会等にも顔を出させていただきましたが。","id":"exchange-030"},{"speaker":"筒井委員","kind":"意見","question":"ぜひよろしくお願い申し上げます。全世代向けになるのですが、人員体制は十分なのか、それと相談場所の確保は十分なのか説明を求めました。","respondent":"東野福祉計画課長","answer":"こちらにつきましては、令和７年度、５か所で今の２名から３名に増員する予定です。場所につきましては、地域センターと場所の確保について十分話し合っているところです。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問","question":"すまいるスクール運営費からは、登録の電子化をしてほしいという思いで質問いたします。１月、２月は次年度の申込みで、電子申請など活用できませんか尋ねました。","respondent":"藤村子ども育成課長","answer":"Ａ登録からＢ登録に変えるですとか、そういった変更申請というところから、全て電子申請とするような流れで今検討を進めているところです。手続の方法につきましては、様々今後調整していく形になります。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"そちらもぜひ一緒にオンラインをしていただきたいなということで要望させてほしいと求めました。改めてこちらの事業の目的を説明を求めました。","respondent":"藤村子ども育成課長","answer":"こちら朝の居場所の実施目的というところですが、朝の小１の壁というような社会的課題がある中、こちら児童の安全確保を図っていくということが第１の目的というような形になっております。","id":"exchange-033"},{"speaker":"せらく委員","kind":"確認","question":"例えば土曜授業の日や、学校が休みだけれどもすまいるスクールが開いている夏休みなどの長期期間中は、どのように考えていらっしゃいますでしょうか。アレルギー対応が出てきたときの対応の話が出たと思いますが、朝食の内容について、アレルギー対応はしないということか確認させてください。","respondent":"藤村子ども育成課長","answer":"こちらについては、まず朝の居場所は平日、学校営業日の平日に実施するというような形で検討を進めているところです。朝食支援に当たりましては、アレルギー対応の食事を提供するということは想定しておりませんので、そういった形での運用を今検討しています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"運用のところ、月から金で勤務をしていると思いますので、そこの支援を小１の壁の解消という点では今後考えていただきたいなと考えています。昨年夏はほとんどのすまいるスクールで１０日程度注文できましたが、次年度はどれくらいを想定していますか尋ねました。","respondent":"藤村子ども育成課長","answer":"今年度ですね、昨夏に関しましては、１校が１７日、ほかがおおむね１０日程度というところで実施いたしました。個別の学校の状況等もあるのでばらつきは出てくると思うのですが、基本的には夏休み中の平日全てで実施していきたいと考えておるところです。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"個別の学校の状況によってですけれども、夏休みが入る７月の後半から８月いっぱいまで実施できるのではないかというようなことだと思います。この仕出し弁当なのですけれども、春休み、冬休みの実施の声が届いておりますが、こちらについては検討など、お考え状況いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"春休み、冬休みというようなお話です。こちら、まず夏休みをしっかりと運用した上で、その他の長期休暇についてもできるところがないかというような形で検討していきたいと思います。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"最後に、オアシスルームについて、１点だけ質問します。以前、今年の９月から保育園児も土曜日が利用できるようにしていただけるということで、こちらについても反響がありました。","respondent":"藤村子ども育成課長","answer":"今回、本件に係るものとしては約３８０万円というような形になっておりまして、こちらシステム改修の費用というようなものになってあります。令和７年９月ということで、運用を確認した後の運用開始というような形というところで、この時期になってあります。","id":"exchange-037"},{"speaker":"横山委員","kind":"提案","question":"児童相談所を中心として、性虐待、性被害の未然予防、発生予防、悪化予防を進めていただきたいと要望いたしますが、区のお考えを、説明を求めました。","respondent":"長谷川児童相談課長、金子一時保護担当課長","answer":"児童相談所は現状、子どもと家庭を支援していく機関であることから、予防に関しては全庁的に対応していく必要があるというように認識しています。その過程において、有用なチラシ等がありましたら、適宜活用していきたいと考えておりま… 大人が常に子どもに寄り添い、子どもの声を聴く体制をつくっており、日常的に暴力の未然防止に努めております。子どもを取り巻く大人、子ども自身が暴力を防止する意識やスキルを学ぶワークに取り組み始めています。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、若者の心と体の健康相談事業、孤独・孤立対策推進事業についてお伺いいたします。先ほどひがし委員の質問でもあったのですけれども、しなわかチャットについて、チャット相談と対面相談会の実施の状況を確認させてください。","respondent":"柴田子ども施策連携担当課長","answer":"チャット相談、それから対面相談会ともに、昨年１０月から１１月にかけて約１か月間の試行実施をしたのち、本年１月より本格実施をしております。試行実施期間に１回、本格実施となってからも月に１回ずつ、区内の児童センターで実施をしておりまして。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"私は性の悩みを抱えている２０代の若者にも、無料で相談できるユースヘルスケアが地域に必要だと考えています。若者の心と体の健康相談のさらなる充実と、孤独・孤立対策の推進を要望いたしますが、区のご見解をお伺いいたします。","respondent":"柴田子ども施策連携担当課長、東野福祉計画課長","answer":"委員のご質問にお答えいたします。現在実施しております若者の心と体の健康相談の事業を通じまして、対応が求められているかについて把握することに、まず努めたいと考えています。孤独・孤立の面からにつきましては、引き続き２４時間３６５日チャット相談、こちらは１９歳以上の方でもご相談ができます。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"課題や今後の対応を早くしていただくということを努めてほしいと求めましたし、２０代前半の大学生や、私は潜在的にいるかと考えています。把握ということはなかなか難しいと思いますけれども、ぜひ孤立・孤独対策とともに進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２５３ページ、高齢者活動支援事業についてお伺いします。そこでお伺いいたします。","respondent":"樫村高齢者地域支援課長","answer":"令和６年度の４月現在におきまして、１０６クラブ、それから８,４９２名の会員が入会をされている状況です。推移ですけれども、それぞれ５クラブ、８０７名減少で、３年前と比較しますと減少しています。","id":"exchange-042"},{"speaker":"えのした委員","kind":"確認","question":"この３年の間に、５クラブ、８０７名と大変減少していると確認が取れました。お伺いします。","respondent":"樫村高齢者地域支援課長","answer":"企業の定年延長や、会員が高齢化することもあり、施設への入所や死亡などによることが主な要因だというように認識をしております。併せまして、コロナ禍において一定期間活動が停止せざるを得なかったことも、大きな１つの要因だというように捉えているところです。","id":"exchange-043"},{"speaker":"えのした委員","kind":"確認","question":"地域センターには高齢者クラブの担当者がいますでしょうか。ワンストップサービスができると、会長や役員の負担軽減になると考えますが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"地域センターにおける高齢者クラブの専門事務担当者につきましては、いないものというように認識しております。引き続きご相談やお問合せのあった際には、関係課とも連携を図りながら、適切に工夫を図りながら支援してまいりたいと考えています。","id":"exchange-044"},{"speaker":"えのした委員","kind":"提案","question":"会派のまつざわ委員の代表質問からも、ご提案がありましたが、高齢者の方がもっと活躍できるような場はないのでしょうか。ご見解をお伺いしますとの意見を述べました。","respondent":"樫村高齢者地域支援課長","answer":"１例ではありますけれども、高齢者地域支援課では地域貢献ポイント事業を実施しております。今後も高齢者の増加が見込まれる中、地域における高齢者の相互支援と社会参加のさらなる促進を図っていきたいと考えております。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問・要望","question":"こちらさらに様々な高齢者福祉に寄与できるような取組を要望いたします。今後の高齢者支援における展開をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"引き続き、高齢者の方が住み慣れた地域でいつまでも安心して生活が送れるよう、高齢者クラブをはじめとした高齢者の方々のご意見を丁寧に聞き取りしながら、必要な支援を適切に行ってまいりたいと考えています。","id":"exchange-046"},{"speaker":"えのした委員","kind":"質問","question":"次に、スマホを活用した介護予防サポートについてお伺いします。こちらの新規の事業とのことですが、概要をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"具体的には、利用者が５人程度のグループを作成いたしまして、自然に交流を図ることで運動習慣の定着化を促進するアプリを導入いたします。あわせて、区が利用者へ情報発信なども可能な専用ページを開発するものです。","id":"exchange-047"},{"speaker":"えのした委員","kind":"質問","question":"こちら補助金などはあるのでしょうか。お伺いします。","respondent":"樫村高齢者地域支援課長","answer":"補助金の件ですけれども、こちらは東京都の補助金を活用する予定です。令和７年度につきましては５９６万６,０００円を予算計上しておりまして、１０分の１０の割合で東京都からの補助金が歳入の見込みです。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"２６３ページ、朝の児童の居場所確保事業、２６３ページ、こども計画推進費、２９３ページ、生活困窮者自立支援事業について伺っていきます。当初予算に入っているかどうかを説明を求めました。","respondent":"藤村子ども育成課長","answer":"緊急対応等というところになりますけれども、そちらと同様の形で安全確保を図ってまいりたいと考えています。教育委員会と連携を図っていくほか、事業実施の詳細が決まりましたら積極的に周知をして、保険のほうでもしっかり対応してまいりたいと考えています。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"３学期、４月１日以降もすまいるスクールと同じように、４月１日から朝の居場所の確保ができるような体制整備も併せて求めたいなと思います。４月１日からのそうした検証もぜひ項目に入れていただいてやっていただきたいのですけれども、これのお考え、現段階のお考えを、示すよう求めました。","respondent":"藤村子ども育成課長","answer":"２点ご質問いただきました。来年度試行実施という形ですので、４月１日から実施できるかどうかや、状況を踏まえて検討していきたいと思います。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"ですから、そのようなファイナンシャルプランナーとの連携、これは事業の中で。より１歩を踏み込んだ形での、そのような連携のありようということについて、区のお考えを説明を求めました。","respondent":"豊嶋生活福祉課長","answer":"専門の福祉的な資格を持った相談員が、その方々のご自宅にたまには出向いたり、もしくはご相談を受けて家計管理等々を今現在行っているです。福祉的な相談について現時点でご相談を受けているですので、その辺りは改善された後、検討していきたいと考えています。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問","question":"最初に第１子保育料の無償化事業についてお伺いいたします。令和４年度にゼロとなったという待機児童が、今の待機児童と、あと空いている園などの現状を説明を求めました。","respondent":"芝野保育入園調整課長","answer":"空き状況等々、こちらも、今在籍状況が区立のほうで９０％超です。そして私立のほうが８８％超ということで、十分、引き続きそれを受け入れられる体制というものは整っているというように感じております。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問・要望","question":"早い段階からそういった建設情報などは入手して、対応されているのかということをお聞きいたします。時々保育士の処遇改善を求める陳情を目にしますが、あともし分かれば、私立の保育士の収入の状況といったことも説明を求めました。","respondent":"芝野保育入園調整課長、中島保育施設運営課長、佐藤保育事業担当課長","answer":"現在策定中のこども計画におきまして、量の見込みと確保方策というものを定めております。それに対応する確保方策… 区立の保育士の給与、人件費につきまして、ちょっと手元に数字はないのですけれども、２３区、人事委員会の方で共通して設定している数字を適用しています。調査等してございませんが、役職等のない保育士の平均賃金というものは約３９０万円となってございまして、処遇改善というものが進んです。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"令和６年１０月の児童相談所開設をもって、品川区だけで行うようになって、具体的な問題などどれぐらい報告が来ているのでしょうか。先ほど横山委員からも質問のときに、予防のほうにも取り組んでいかれるということでしたが、職員数は足りているのか尋ねました。","respondent":"長谷川児童相談課長、金子一時保護担当課長","answer":"児童相談所の中で援助方針会議、また、合同判定会議というものも行ってあります。その中で、各職種からの意見に基づきまして、しっかりと所として適切な判断ができているというように認識しております。 一時保護施設の現状についてのご質問がありました。１４名という定員なのですけれども、都のケース数の年間の数が大体４か月ぐらいで、実際保護しているという状況がありますです。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから時間があれば、２３９ページの地域生活支援事業について伺いたいと思います。もっともなご意見だと思うのですけれども、事業所への支援について、まず見解を伺います。","respondent":"菅野高齢者福祉課長","answer":"この居住支援手当のほうは、その金額の１５％、社会保険料の事業主負担分も支給されるということをカバーリングはしているというところになります。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"ご見解を伺います。断られた人はどうしているのだろうという声が上がったのですけれども、多分一生懸命探して、その辺についても見解を伺います。","respondent":"菅野高齢者福祉課長","answer":"要介護１等に比べますと、若干の単価差があるということで、事業者のほうが難しいというようなお話は聞かせてはいただいております。要支援１、今回の令和６年度の介護報酬の改定に合わせまして、少しでもサービスの事業が結びつくように支援はしてまいりたいとは思います。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"かつてのホームヘルパー２級よりも短い研修時間で取れる生活援助研修や、もっと簡単な入門的研修という制度ができたと伺いました。あるとした場合、どのように制度の運用を始めるのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"身体介護、訪問ヘルパーの中で身体介護よりも生活援助ということで、恐らく食事や掃除の、そういったお手伝いをする方の研修というお話だと思います。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"底辺を広げるという意味でも、やらないそうですよという感じのお返事になって間違いないのでしょうか。伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"これまでも研修自体は、区のほうというよりも東京都でやっていたりなど、いろいろなところで研修は様々、介護職員の方の場合の研修はあると思います。","id":"exchange-058"},{"speaker":"吉田委員","kind":"提案","question":"その解消方法の１つとして、いわゆるぶら下がり許可の活用というものが、視覚障害者福祉協会の会長からご提案があったと記憶しております。","respondent":"松山障害者支援課長","answer":"まだまだこういったご提案もありますので、確かに移動支援、同行援護については、非常に区としても課題だと認識しております。移動支援や同行援護に活用できるかどうか、あるいはどういったような工夫があればできるのか、研究してまいりたいと考えております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"提案","question":"せっかく出たご提案なので、もう実現に向けた具体的な制度設計など、そのようなことに向かってほしいと求めました。ぜひそのような視点でもう１回、意気込みと申しますか、その辺についてご見解を伺いたいと思いますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"当事者の方から教えていただいた、いいご提案なので、きちんと受け止めて検討してもらいたいと思います。","id":"exchange-060"},{"speaker":"せお委員","kind":"質問","question":"２６３ページ、時間があれば２８３ページ、医療的ケア児保育支援事業について伺います。多様な交通手段というところをちょっと、そのような意味で見解を説明を求めました。","respondent":"松山障害者支援課長","answer":"区外特別支援学校への通学支援における多様な交通手段についてです。いずれにしましても、ご利用されるご本人やご家族が利用しやすいような交通手段を選んでいただき、ご相談いただければと考えています。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問・要望","question":"障害者手帳アプリ活用の導入なのですけれども、こちらも会派から要望していたので、早速取り組んでいただき大変楽しみにしております。さらに５０万円という予算額なのですけれども、その内訳、分かれば説明を求めました。","respondent":"松山障害者支援課長","answer":"そこに精算機を設置する際の工事期間を見込みまして、全てで５０万円とするものです。手帳アプリ対応の精算機器の設置工事につきましては、障害者割引を進めようという観点から、事業者負担で行っていただけることになりました。","id":"exchange-062"},{"speaker":"せお委員","kind":"提案","question":"その後ですが、ご提案をしますので、今後ご検討ほしいと求めました。そういった方たちも気軽に利用できるようなアプリ作成のご検討も今後行っていただきたいのですが、そちらの見解を説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"私からは、アンケート機能等につきましてのアプリ作成のご検討ということで質問いただいたところについて、お答えします。今後調査等を行っていく、委託する事業者等とも調整を含めまして、検討してまいりたいと思います。","id":"exchange-063"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、面談のような時間にもなり得ますし、最初の登録は足を運んでいただきたいなと、それだけ要望します。区が予算案を計上するときには新１年生がどのような状況なのか分からないと思うので、この運営委託費からなのか、その辺をまず説明を求めました。","respondent":"藤村子ども育成課長","answer":"すまいるスクールの人数というところですが、確かに入学前の段階で予算組みをするので、ちょっと先の予想が立てにくいところになっております。","id":"exchange-064"},{"speaker":"せお委員","kind":"質問","question":"入学式の前からすまいるスクールに通うわけですから、先生などの大人も何も知らないまま入って、児童にとっては不安しかないと思います。すまいるスクールを利用する子どもたちの特性を現在どのように情報収集していますか尋ねました。","respondent":"藤村子ども育成課長","answer":"特性のある児童の方への対応というところですが、また、情報共有を行うような取組を行っております。学校によっては少し対応状況にばらつきがあったというようなお話ございましたので、協力体制の徹底というものを周知していただいたところです。","id":"exchange-065"},{"speaker":"せお委員","kind":"質問","question":"医療的ケア児はちょっと時間がなくなってしまったので、違う場所でお伺いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"２５５ページの新規事業、家具転倒防止対策助成について、後半は高齢者の医療費無償化を求めて伺います。６５歳以上で要介護２以下の高齢者がいる世帯をなぜ対象から外したのか、それ以下の障害者がいる世帯をなぜ対象から外したのか、理由を伺います。","respondent":"樫村高齢者地域支援課長","answer":"事業の考え方としましては、取付けまでも行うことによりまして、要配慮者の安全・安心な生活を支えるものというように理解をしております。世帯の中で取付けが困難な方への支援という観点から、一定の線引きを行いまして、範囲を決めたというように理解をしています。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"なぜこうした線引きをするのか、なぜこうした高齢者や障害者をこの対象から外すのか、理由が分かりません。取付けが困難な方だと私は思いますが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"ですから、それぞれお一人での判断ということではなくて、世帯の中でということで判断をしているといったところです。あくまで本事業としては、先ほど申し上げた基準によりまして、本事業においての一定の線引きを行いまして、対象を設定しているものです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"この事業は年間６６万７,０００円と、決して大規模ではありません。障害者手帳保持者および６５歳以下でも介護認定を受けた方、「誰もが」を実現してほしいと求めましたが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"令和７年度につきましては、今回所得制限撤廃ということで実施をしてまいりますけれども、必要に応じて研究してまいりたいと考えています。","id":"exchange-069"},{"speaker":"中塚委員","kind":"提案","question":"ならば高齢者の医療費無償化を提案しますが、いかがでしょうか。あわせて、医療は、子どもとともに高齢者にとっても、生活の基礎となる行政サービスだと私は思いますが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"医療の制度を継続するということで行っている制度ですので、根本的なところでいろいろと企画、考えていくところだと考えています。区のほうとしましては、そちらの考えのほうを注視していくというような形を取らせていただきます。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"私、併せて伺ったことは、高齢者にとって医療とは生活の基礎となる行政サービスではないのかと。私はそう思いますがいかがかと質問しましたので、ぜひお答えほしいと求めました。","respondent":"池田国保医療年金課長","answer":"生活をする上では必要なものではありますけれども、使われる方、そしてそれを守る方の相互扶助の形でやるべきものであると考えているところです。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"今国の動きを注視というお話もありましたけれども、品川区から一石投じていくのだという話も、給食費無償化の中で示されております。ぜひ品川区独自に高齢者の医療費を無償にしていただきたい、品川区から一石投じてほしいと求めましたが、改めていかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"医療費の抜本的な制度改革につきましては、国の動きについて注視してまいります。よろしくお願いします。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"今預かり保育事業で１日４５０円、上限月１万１,３００円ですか、幼稚園施設給付型という形に移行している園が幾つかあります。預かり保育事業ということに何か違いのようなものが生じることがあるのかどうか、その点についても伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"委員おっしゃいました月額１万１,３００円、日額では４５０円なのですけれども、そこまでの助成が受けられるという仕組みになっております。もう１点、金額も同じ金額で、助成のほうさせていただいているものです。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"この定員割れ等の問題に１つの解決策というか、預かり保育事業というものを拡充してほしいと、このような声が非常に強く出ているところです。私立幼稚園の今後の事業継続、こういったことに寄与するというか、効果をどのように区としては考えているのかについてお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"預かり保育に対する効果、区の考え方ですが、私立幼稚園における預かり保育の利用状況から、まずご説明させていただきたいと思います。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問","question":"そういったことが解消していく、そのような方向にある有効な政策として見ることが評価できるのか、ここについてちょっと伺いたいです。","respondent":"芝野保育入園調整課長","answer":"区の政策として今後どのように考えていくかですが、国や都の補助金拡大の動向なども注視しながら、よりよい支援の在り方について継続的に検討してまいりたいと考えています。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"実は１８歳のこの壁の受入れの延長だけではなくて、このような、やはり現場ではその方はちょっと無理ですねと断られるパターンがあると。現行のこの法制度、体制の中ででき得る部分がきっとあるのではないかと思うのですが、そこについてのご見解を説明を求めました。","respondent":"松山障害者支援課長","answer":"例えば区外の特別支援学校もしかり、それでつくり上げる、それが政策となるです。個々の状況に合わせて、本当にその方の必要なものは何かというところを知恵を出し合いながら、お互いに支援をしていくです。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２４５ページ、２４７ページの障害者福祉について伺いたいと思います。国が制度として無償化すべきものですが、私はこの基本合意や骨格提言の考え方と同様のものであると思いますけれども、区の認識を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"就学前３歳から５歳までの利用者負担が全国的に無償化されているといったところが現状でもありますので、区においても既に開始しています。に、障害児通所支援事業の利用負担を区独自助成に無償化することで負担軽減を図る施策を打ち出したものです。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"提案","question":"放課後等デイサービスや日中一時支援に通所できない、もっと重度の障害児に対して在宅サービスを無償化してほしいという要望もいただいています。入浴サービスですとか、訪問介護だと在宅サービスの無償化もしてほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"居宅訪問型児童発達支援という、居宅を訪問して児童発達支援の療育を提供するというものも無償化にさせていただきました。こちらのほうで初めて無償化を今回実施するという形になっておりますので、今後は引き続き検討ということになります。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"幹線道路、徒歩で最大２０分程度かかるような幹線道路のスポット送迎になるという説明が、施設から利用者にあったということで伺いました。２年間で１.４倍に増えているわけなのですけれども、なぜ自宅送迎ができないのか、このことについては品川区も承知の上なのか伺います。","respondent":"松山障害者支援課長","answer":"ぐるっぽの日中一時支援の送迎についてのご質問です。自宅送迎からスポット送迎に対しての変更ですが、もう一度、再度施設側の現場のほうに確認させていただければと考えています。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"家族に大きな負担をかける幹線道路でのスポット送迎は、この目的にも合わないのではないかと思いますが、いかがでしょうか。区立の総合支援センターなので、これまで同様送迎が続けられるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"日中一時支援の送迎についてですが、区としてはまだ確認できていない状況ですので、改めまして施設側にきちんと確認を取らせていただいて、対応については検討します。","id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"以前、利用限度が月１０日しかなくて、これは要望もいただいて議会でも何回も取り上げて、月２３日まで使えるようになりました。これは増やすことが必要ではないかと思うのですが、いかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"見込み量につきましては、見込み量確保のための方策のところに、計画のほうにも記載をさせていただいているところではあります。引き続き事業所誘致に取り組むということで、そういったところを進めてまいりますというようなところで記載させていただいているところです。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これ障害児通所支援事業運営補助金交付要綱というものがありますけれども、実績は何事業所ぐらいこの補助金を受けているのか伺います。これは医療的ケア児や重度だけでなく、対象を広げて放課後等デイサービスの誘致をしてほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"今年度につきましては、放課後等デイサービスも新たに対応に加えましたので、児童発達支援２事業所、放課後等デイサービス２事業所です。今後はこれまで以上に誘致のインセンティブを強化いたしまして、２３区の中でも順位をしっかり引き上げていきたいと考えております。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"具体的にいろいろな社会福祉法人への働きかけなど、そのようなものも含めて、ぜひよろしくお願いしたいと思います。代表質問で、重度障害者や医療的ケア児者のグループホームの整備計画と具体化を求めましたけれども、その点について伺います。","respondent":"佐藤障害者施策推進課長","answer":"今委員ご指摘いただいたとおり、グループホームの整備につきましては、用地確保も大きな課題です。次期障害福祉計画等とも整合を図りながら検討を進めていくということで、その示し方、改めて検討を今進めているところです。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"提案","question":"先ほど吉田委員も質疑されていた総合事業に関して、ちょっとマニアックですが、大切な質問、提案をします。お伺いしますが、仮に悪天候、雪や台風などによって臨時で休業したときの取扱いはどうなりますか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"多分雪が積もっているかどうかということを確認する手だてが当日などもなかったりして、前日などでも、例えば台風が来るねと。ある種免罪符になると思うので、ぜひそういったことを区としてやっていただきたいのですけれども、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"そういった事情もあることから、あくまでも事業所の判断となりますので、区からそういった指針等を示すようなことは現在いたしておりません。他の事業所からの情報など、そういったことを参考になるような形でお伝えして、丁寧に事業所の方には対応したいと思ってあります。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひこれは、それほど手間のかかることではないと思うので、進めていただきたいと思うので、強くこれは要望しておきます。なってしまっているという状況、注意書きにそう書かれているのですが、それは間違いないか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"現状としては、委員ご指摘のとおりです。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そのＱ＆Ａの中に。ですから、ぜひこういったところは、区の中できちんと、何というか、柔軟な対応をしていただきたいと強く求めますが、いかがでしょう。","respondent":"樫村高齢者地域支援課長","answer":"事業所等の声も丁寧に聴きながら、今後の運用については検討してまいりたいと考えます。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"絵に描いた餅になってしまってもったいないというところで、やはりこういった厚みを増やすということを併せて行っていく必要があると思います。もう時間がないのであれですけれども、ぜひこういったところの取組もしっかりしてほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"西村委員","kind":"質問","question":"２７１ページ、２７３ページ、私立幼稚園保育料助成について伺ってまいりたいと思います。その中で実施校の検討状況と、いつ頃からの実施を予定しているかなどの協議や報告など、何か進展があったのか伺います。","respondent":"藤村子ども育成課長","answer":"その中で、実施校名とスタートの大体の期日というところをご報告というか、協議させていただいて、ご了承いただいたような形になっております。実施のタイミングとしては、５月の最終週から実施というところを目指して動きたいと考えています。","id":"exchange-089"},{"speaker":"西村委員","kind":"質問・要望","question":"この３校を選ばれた理由があればお聞かせほしいと求めました。","respondent":"藤村子ども育成課長","answer":"何か試行の際にトラブルがあった際にも対応しやすいというところがまず１つ、あと１校義務教育学校であったり、この３校を抽出したという形です。","id":"exchange-090"},{"speaker":"西村委員","kind":"質問・要望","question":"この朝食支援を始めるに至りまして、区内の現状をどのように分析しているのか伺いたいと思います。朝ご飯の提供は、実態の調査と児童の状況に合わせた、その先の支援の検討までをセットで実施することが不可欠だと思いますが、お考えを伺います。","respondent":"藤村子ども育成課長","answer":"この朝食支援の実施の経緯といたしましては、それで７％ほど朝食を食べていない児童がいるというところ、ニーズを持って事業実施を検討しています。今回朝食支援に当たっては、事業実施に当たっては、ニーズに合った支援というものをやっていきたいと考えています。","id":"exchange-091"},{"speaker":"西村委員","kind":"質問","question":"３食親と食べない子どもも出てくるかもしれません。夜も民間学童などで済ませるなど、そのような子どもへの影響をどう捉えるかお伺いいたします。","respondent":"藤村子ども育成課長","answer":"子どもへの影響というところですけれども、今回この朝食の支援というものは無償で行うという形を想定しております。この区の進める施策の方向性として、今後の調査に基づいて検討してまいりたいと思いますが、サービスの選択をしていただければと考えております。","id":"exchange-092"},{"speaker":"西村委員","kind":"質問・要望","question":"提供内容がどのような食べ物を用意するか伺いたいのですけれども、調理不要なおにぎりやパン、大変重要なことだと考えています。そして、栄養面にも気をつけてあげられたらいいなと要望いたしますが、お考えを伺います。","respondent":"藤村子ども育成課長","answer":"提供する朝食のところですけれども、おにぎりやパンなど、そういったものを含め現在検討中というような形です。ご利用される児童や保護者に喜んでいただけるというものを届けるような形で検討していきたいと考えております。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問・要望","question":"次に私立幼稚園ですけれども、保護者の皆さんや幼稚園側からの長年の要望をいただいております。私どもも要望させていただきまして、今回、私立幼稚園保護者補助金の助成内容の拡充がされました。","respondent":"佐藤保育事業担当課長","answer":"区といたしましては、品川区の幼児教育を長きにわたりリードしていただいている、大切な施設であるというように認識しております。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"学習食の支援事業のほうでは温かいお弁当を提供するというように伺っております。今既に始まっている事業を広げるというように認識しておりますが、配布はどの時間帯で、どのようなものを配布しておられるのか伺います。","respondent":"飛田子育て応援課長","answer":"子ども食堂での朝食支援のご質問です。朝食の大切さ、また、自分で準備して朝食を食べる習慣をつけることを目的としております。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひともそちらもご検討を続けていただきたい、学校との連携を続けていただきたいなと、これは要望します。今年度、２１１万円余の予算が新規計上されておりまして、コロナ後の参加者の推移と、子育てメッセ、今後どうしていくのか伺います。","respondent":"藤村子ども育成課長","answer":"令和５年と今年度、令和６年、ともに２,０００人ほどが来場しているような形になっております。１１課になりますけれども、ＰＲの場として活用しているところありますので、しっかり連携して取り組んでまいりたいと考えています。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"ただ、この実行委員として、私としても何とか続けられないかと要望させていただいたことがあります。今回支援が広がり、喜びの声が届いておりますけれども、実際にどのような企業がこの子育てメッセに参画をされているか伺います。","respondent":"藤村子ども育成課長","answer":"そういった企業のほうにもご協力いただいて、何か試供品をいただいたりなど、様々な形でご協力いただいている形になっております。","id":"exchange-097"},{"speaker":"西村委員","kind":"意見","question":"この実行委員のお母さんたちが協賛を募りながら、そういった企業に向けて苦労して続けてこられた、もう１７回目になるイベントですので、ぜひとも引き続きご支援をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問","question":"２３９ページ、５５９ページ、要支援者夜間対応サービス特別給付費と通院等外出介助サービス特別給付費からお聞きしたいと思います。お聞きしますが、いわゆる人材確保、この課題について改めてご見解をお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"委員がおっしゃられるとおり、そのために養成講座を心身障害者福祉会館のほうで１回から２回に増やしまして、養成講座を行ったです。定員については１５名で、そこのハードルが高くて、実際の従事する方々がほとんど少数であるというような課題を持っております。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、いわゆる１時間弱でも１時間とするというような費用の見直しをというお声がありますけれども、こうしたことについて伺いたいと思います。片道報酬、今までしていたといった、この区の考え方について、また課題についても併せてお答えほしいと求めました。","respondent":"松山障害者支援課長","answer":"現在事業所からは、特に通学、３０分以内等あった場合の短時間支援した場合の片道の算定の見直しについてご意見を伺っております。今後他区の事例を参考にしまして、引き続き通学等の移動支援の充実に努めてまいりたいと考えています。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"改めて区のご見解を伺いたいと思います。来年度の事業はどのようになってしまうのでしょうか、お知らせください。","respondent":"菅野高齢者福祉課長","answer":"現在全世代型対応型の社会保障制度を見直す中で、いろいろと検討されている中でありますので、国の制度の中で。引き続きニーズの捉え方については検討していきたいと考えています。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、事業に対しては継続という形で確認をさせていただきました。そのように動向を見ていただきながら、考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは２４５ページ、障害者就労支援事業、２６７ページ、ひとり親家庭支援事業についての、就労支援についてお伺いします。それと２７７ページ、時間があれば２７３ページ、いわゆる償還払いについてお伺いをしていきます。","respondent":"松山障害者支援課長、飛田子育て応援課長","answer":"就労支援につきましては、区内で就労支援センターを設置いたしまして、就労につなげているところです。そのほかは、障害者総合支援法にのっとりました就労継続支援Ａ型、Ｂ型の福祉的な就労等があります。 こちらのほうでは、ひとり親家庭相談の中に就労支援ということも行っております。一緒にどのようなところで働くか、また生活リズム、そのようなところも兼ねて一緒に支援をしているところです。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"提案","question":"障害者の方たちの就労支援も、今提案をしますけれども、いわゆるＡＩを活用した仕事に就いてもらうと。その学校には幼稚園が含まれているのか尋ねました。","respondent":"松山障害者支援課長、飛田子育て応援課長、中島保育施設運営課長","answer":"委員ご提案の、ＡＩを活用した学習支援によるスキルの向上や、新たな働き方のご提案です。可能性を広げていただいて… そのようなところで就労プログラム、そのようなものを策定して、その方の自立に向けてやっています。そのＡＩの提案ですが、そのようなよりよいものがあれ… 保育園につきましては、就労支援もありますので、給食無償で提供しています。","id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ですから、学校給食費というのであれば、ここは幼稚園も入れてしっかりと対応していく必要があるのではないかなと思います。北区では、令和５年からですか、幼稚園や保育園の、いわゆる給食無償化というものにも踏み込んで、今実施されていると思います。","respondent":"中島保育施設運営課長","answer":"まだ無償化等の対応はしておりませんが、今後社会情勢等を見極めつつ、判断すべき課題と認識しております。","id":"exchange-105"},{"speaker":"石田（し）委員","kind":"意見","question":"それを義務教育ではないからやらないということは、私はそれはお答えにならないと思いますけれども、もう一度ご答弁ほしいと求めました。実は私も当事者として強く思っている課題の１つが、必要ではないかなと、もう一度その部分に関して答弁ほしいと求めました。","respondent":"中島保育施設運営課長、芝野保育入園調整課長","answer":"幼稚園での給食につきましては、現状、区立、私立ともに形態様々ですので、社会情勢等見極めつつ、判断すべき課題と認識してまいりたいと考えています。 私立幼稚園の償還払いの件です。システム改修も必要ですので、そちらのほうを進めまして、年度中頃には体制が整いました園から開始していきたいと考えております。","id":"exchange-106"},{"speaker":"松永委員","kind":"質問","question":"２３３ページの孤独・孤立対策推進事業について伺います。２０代から３０代の孤独・孤立に係る当事者へのヒアリングも行っているかと思いますが、どういった対策、また調査を行われているのか尋ねました。","respondent":"東野福祉計画課長","answer":"大まかに説明いたしますと、分析結果といたしましては、１２５件の相談がございまして、土日夜間の相談が多かった。５１２人の方からご回答いただきまして、傾向といたしまして、それからライフイベント発生時に孤独を感じるというような結果が出ているものです。","id":"exchange-107"},{"speaker":"松永委員","kind":"質問","question":"そこで、２５３ページの高齢者クラブ支援事業、先ほども質問がございましたけれども、そのことについてかぶらないように質問いたします。事業評価シートではＣ評価ですので、この事業実施方法を検討するとありますが、今後の進め方についても併せて伺います。","respondent":"樫村高齢者地域支援課長","answer":"今後の区の取組の方針なのですけれども、何か変わったことはないか等、地域で見守り活動を行っていくことは大変重要なことであると考えています。来年度以降、そこに当たっても積極的に高齢者クラブの活動を支援していく必要があると考えています。","id":"exchange-108"},{"speaker":"松永委員","kind":"提案","question":"その中で、何か情報や、そうした調査というものが行われているのかどうかということを伺いたいと思います。最後はちょっと提案になるのですけれども、まずはこの高齢者クラブという考えから、ネーミングを変えていただけないか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"現在実施していないところにありますけれども、理事会をそれぞれ月に１回開催しておりまして、ご意見等を頂戴しています。こういった形でクラブの方針によって名称を決めることができますので、こういった形で運用できるように、引き続き支援していきたいと考えています。","id":"exchange-109"},{"speaker":"松永委員","kind":"提案","question":"次に、２５１ページの福祉人材確保・定着事業の、この外国人介護職員などなどの支援について伺いたいと思います。その中で外国人への家賃助成を確認させていただいたところ、１６件と、介護職についてどのくらいの人数の方が働かれているのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"住居の確保等の事業で、実際にご入居いただいている外国人の数ということで把握させていただいているものが、現在は１６人です。ただ、有料老人ホーム等を含め、多くの外国人の方が区内の事業所で勤務していると推測しております。","id":"exchange-110"},{"speaker":"松永委員","kind":"質問・要望","question":"そうした中で、なぜかといいますと、やはり労働環境に合わないと。取組をしっかりと取っていただきたいと思うのですが、何かそのようなものがあればいいなと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"セミナー等につきましては、例えば今年度ですと、ある事業者が外国人の方を集めて、そこで交流会などをさせていただいたり、そのようなことも努めしていますので、引き続き区も支援してまいります。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"要望事項は２つありまして、入園料の助成を求めるものと、これを求めるものであります。認識をお伺いします。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園の魅力発信に向けた取組など、公益性のある活動、そこに対して支援をしているという認識です。これは私立幼稚園協会の中の１つの連合会というように聞いておりまして、特に問題がないものであるというように認識しております。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"それで保護者の立場からその会に出たら、なぜあなたはこの会に来ているのですかと思われるぐらいのような対応だったそうです。このような視点を財政課長、補助金担当の企画部門としてはどのように判断されますか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"一部繰り返しの答弁となってしまい大変申し訳ございませんが、私立幼稚園協会に対する補助に関しましては、品川区全体の幼児教育の向上を図るための取組の経費を、一部を補助しているというものです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"あるいはその補助金を求める活動というものは、ここに書いてある、私はそれに公金を入れるということは問題があると思っています。ですから、ぜひ考えていただきたいのですけれども、そのことが私は影響しているのではないかという思いもしてなりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２４５ページ、旗の台リボン跡地障害者就労支援事業、２４３ページ、心身障害者福祉会館運営費についてお伺いをします。初めに、２４５ページの旗の台リボン跡地障害者就労支援事業についてお伺いをいたします。","respondent":"松山障害者支援課長","answer":"旧リボンの跡地に建つ就労支援施設と会館との連携についてです。例えば会館の地域活動支援センター逢のところで通っていただいた方が、一緒に何かイベントをするといったような連携も考えられるかなと考えています。","id":"exchange-115"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今の質問の１点目で、中央区にはそこのホームページがあって、ネット上でも何かやり取りができるということがあります。受注に関してもホームページ上でやり取りができるような仕組みをつくってほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"障害者の就労体験メニューの１つとして、そういったことも目指しまして、就労の部分から考えております。制服につきましては、教育委員会と今後連携をしまして、具体的には検討していきたいと思います。","id":"exchange-116"},{"speaker":"高橋（伸）委員","kind":"質問","question":"すみません。もう１点目が、具体的に、具体的に地域のインクルーシブな交流の促進ということはどのようなことを取り組むのか説明を求めました。","respondent":"松山障害者支援課長","answer":"そこで地域交流を促進していきたいと考えています。もちろん地元の町会の方々も含めまして、例えばイベントを一緒にやるなど、そういったようなこともできるのではと想定しております。","id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２４３ページ、心身障害者福祉会館運営費についてお尋ねをします。何というのか、活発にやっておられると思いますけれども、数字が現時点でお分かりになれば教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"地域活動支援センター逢の数字ですが、手元にはちょっと障害種別ごとのものはございません。障害のない方もかなり多くいらしていただいております。","id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"意見","question":"先日、品川区のホームページ上で、令和７年度の失語症者向けの意思疎通支援事業の養成講習会があるということが公開をされておりました。いずれ、今後区としてお考えになられているのかどうか、お尋ねをしますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"区としても東京都の養成研修を応援して、品川区民の意思疎通支援者を少しでも増やそうということで掲載をしているものです。実際の事業の内容につきまして、今学ばせていただきまして、今後各区にも足を運んで研究をしてまいります。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"２５６ページの子ども育成費全般で、関連して朝の児童の居場所確保、それから病児保育、仕出し弁当という関係で、それぞれ関連してお聞きします。区はどこまでやって、この子育て支援をどう考えていろいろ施策をやろうとしているか、説明を求めました。","respondent":"藤村子ども育成課長","answer":"親育ち支援事業ということで実施しておりまして、親育ちの支援ということで、総合的に支援しています。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"子育て支援というものをどのように捉えてやっているのですかという話なのです。子育ては負担か尋ねました。","respondent":"藤村子ども育成課長","answer":"今区のほうで展開しているサービスというところが、複数あるサービスの中から何かを選択してもらうというような考え方に立っておるものです。こういった状況下で、今の子育て支援という形で主に展開している施策かと思います。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"これは教育法ですから、教育についてと書いてありますが、第一義的責任を取りましょうと言っているのです。ですから、親の仕事、親の役割とは何でしょう。","respondent":"藤村子ども育成課長","answer":"区としては、子育ての社会化というところを進めておりまして、社会全体での子育てというところを進めているものです。あくまでサービスの１つとして選択肢を提供しているという形になりますので、何かこう１つ、何か家庭の中でご選択いただければと考えております。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"そうなると、いいですか。朝は学校で食べさせてもらい、日中は給食が出て、仕出し弁当、夏休み仕出し弁当、夜はテイクアウト、子どもに対して親は何をやるのか尋ねました。","respondent":"藤村子ども育成課長","answer":"食に対しての考え方というところですけれども、仕出し弁当で何を食べなかったかとか、そういったお話をする機会はきっと増えてくると思います。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"子どもの気持ちを考えたら、朝ご飯ぐらいきちんと食べさせてほしいということを教育の一環も含めて、行政はやらなければいけないと私は思います。子どもの利益とは何なのかということをしっかり考えた上で、子育て支援というものをやらなければいけないと思いますが、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"ですから、今子どもたち、目の前にいる子どもたちのためにどういった施策ができるかというところを考えて、このような施策の展開をしています。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"今春、または来春卒業するお子さんを持つ保護者の方々から、情報提供なり、直接お話を伺うことができました。２０２７年度に移転し、今のうちから早期の延長受入れを要望いたしますが、区の取組を確認します。","respondent":"松山障害者支援課長","answer":"やはり特別支援学校卒業後、生活介護の施設で利用時間の延長の実施をお願いするということが１点、延長時の送迎の実施ということの。それから３点目、これまで延長対応はしていなかったのですが、来年度から延長対応する方向で調整に入っております。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"ピッコロを含め、延長を確実に実施できるための一重の行政からの支援のお考えを、いま一度最後に確認します。一応、これはちょっと日中一時支援事業の活用も検討いただきたいという要望もさせていただこうと思っておりましたが、ここについてもちょっと。","respondent":"松山障害者支援課長","answer":"区民の方のお困りの声に対応しようと、相談支援事業所側も一緒になって検討をして、何とか工夫しながらやっているところです。重要な課題と認識しておりますので、引き続き実現できるよう取り組んでまいります。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"４月の１日以降、ぬか喜びにならないように、しっかり前に進めてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"提案","question":"そのような関係から、東京都に、令和８年度に大田区に移転する、その後の活用方針について情報提供があったのでしょうか。この都と区の関係においては、当然あったと思われますが、お伺いしますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"東京都品川児童相談所の目黒区、大田区、こういったやり取りの中につきましては、情報共有を行ってきたところです。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、東京都はどのように考えているのか、そのようなことについてのお話はあったのでしょうか。この後も区が使っていいのかどうか、そういったことに関してあったのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"東京都品川児童相談所のその後の活用についてですけれども、今区のほうで聞いておりますものは、令和８年度以降の活用方針、現状未定というように聞いているところです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和８年度以降が未定ということであれば、品川のほうから働きかけるべきではないでしょうか。令和８年度に移転するわけですから、そのための令和７年度に検討して東京都に要望する必要があると思いますが、見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"都有地でありながらも、非常に貴重な公有地です。引き続き東京都のほうは情報連携を密に行いながら、庁内においてもどのような活用ができるかというところの検討を進めているです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"検討を進めているというレベルですが、それよりも、もはや土地を含めて取得するぐらいの強い姿勢、そして区のほうから具体的にこのような形で使っていきたいということを示すべきだと思いますが、改めていかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"繰り返しになりますけれども、貴重な土地、財産であるというところは認識をしています。活用方法、しっかりと検討して、東京都のほうと協議をしていきたいと考えております。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"要望していかないと、何ですか、事業はたくさんあります。その点についてはいかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"おっしゃるとおり、こういった跡地活用、そういった部分は非常に今行政需要も様々ありますので、多角的な視点から判断をしていきたいと考えております。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"このように２３区の対応、特別区長会の一員である区長は、２３区がまとまって区立児童相談所を進めてきたわけです。このようなバラバラの状況をどのように捉えているかお伺いします。","respondent":"森澤区長","answer":"それぞれの各自治体の事情があるということは認識しておりますが、設置をいたしましたので、今回財調の協議もありました。しっかりと品川区の児童相談所を確立していくべく取り組んでまいりたいと考えています。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１２になるともっと増やさなければいけないというところであります。そのような形で、区立児童相談所を持っている区がまとまって財調を求めていくということをお願いしますが、いかがか尋ねました。","respondent":"加島財政課長","answer":"将来設置予定の児童相談所も含んだ配分割合の変更となっておりますことから、協議を継続してきた児童相談所の設置に伴う配分割合の変更については。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは、２５５ページ、家具転倒防止対策助成、２６７ページ、体験格差改善事業について伺います。その理由についてお伺いいたします。","respondent":"樫村高齢者地域支援課長","answer":"今でいう障害者支援課、それから高齢者地域支援課、高齢者地域支援課で本事業を開始したものというように理解をしております。実施事業の所管課についての考えですけれども、平時、平時の業務との密接性で事務を行っているものというように認識をしています。","id":"exchange-135"},{"speaker":"松本委員","kind":"質問","question":"そうすると、多分この転倒ということで被害を受ける方というところに視点が行かれているのだと思います。それが比較的多いというようなデータが、なかなか私も調べて見当たらなかったのですが、ここは何かデータというものはあるのか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"国や都の資料によりますと、災害時にやはり高齢者や障害者などの要配慮者が被災を受けやすいという実態が示されているところです。現在個別避難計画の作成を進めておりまして、要配慮者への支援が行き届くよう、日頃から準備を進めているものというように理解をしています。","id":"exchange-136"},{"speaker":"松本委員","kind":"質問","question":"平時を含めて家具転倒の被害に遭っている人というものは多分いて、それが１つには、やはり乳幼児だと思うのです。これは誰が傷つきやすいかということを考えると、子どもたちも支援の対象に含めていくべきではないかと思うのですが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"この家具転倒防止器具取付助成を実施していたところですが、実績がほとんどないことから令和５年度末に廃止した経過があります。そういったことも踏まえまして、対象者の拡大につきましては、関係課とも検討しながら検討してまいりたいと考えています。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問・要望","question":"あくまで要望というところでとどめたいと思うのですけれども、後々の原状回復を考えるとなかなかやりにくいのだというようなお話も聞くところです。ここの点についてご見解を伺います。","respondent":"飛田子育て応援課長","answer":"例えば育児や家事、食事の準備などは、全て責任が１人で負わなくてはならないということがあります。そのようなところで様々な課題に直面していても頑張って子育てを応援したいというところで、このようにしました。","id":"exchange-138"},{"speaker":"藤原委員","kind":"質問・要望","question":"伺いますが、どうなっているか、正直に話してください。それと２５５ページ、この花づくり助成金、これはどのような施策で、なおかつどのような投資対効果があるのか説明を求めました。","respondent":"豊嶋生活福祉課長、東野福祉計画課長、樫村高齢者地域支援課長","answer":"そういった場合は複数の職員で対応するようにして、それでもという場合は警察に連絡をして対応することも、あるような状況です。職員の身の安全も考えなが… 任意後見人です。判断能力の低下を機に保護をしていく、それから後見活動が始まっていく、そういった制度です。そちらの中に小菊等も入っておりまして、秋には小菊の作品展等、また、表彰式のほうも展開しています。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問・要望","question":"全然ＡＩもＤＸも進んでいないではないですか。この花の効果というものは、安否確認もあるかもしれないけれども、お花の効果というものがすばらしいと私は思うのです。","respondent":"樫村高齢者地域支援課長、東野福祉計画課長","answer":"そうですね。何ですか、力など、そういったものも込めているというように理解をしています。 任意後見人の制度についてもう少し説明をしたいと思います。ここで先ほど委員がおっしゃっていたような、銀行での受理など、そういったものができるような制度となっております。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問・要望","question":"高齢者福祉課長、私に言われたってと課長は言うかもしれないけれども、介護保険得意の答弁、介護保険制度ですからと。高齢者福祉課長、その辺いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"訪問介護は本当に在宅介護の要ということで、すごく大事な事業だということは重々認識しております。介護人材定着支援担当、そして区の実情を踏まえて、どのような人材確保をしていったらいいかということをしっかりと検証していきたいと考えています。","id":"exchange-141"},{"speaker":"藤原委員","kind":"質問・要望","question":"それまでの答弁は、区長、副区長がいらっしゃる前は、全部介護保険制度だから駄目ですと言われていたのですから。やはり求めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２５３ページの補聴器購入費助成事業と、２４９ページ、いわゆる小規模デイサービスについて伺いたいと思います。これによって区の負担は減るということでいいのか伺いたいということと、あと、この直近数年間の利用実績も伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"昨年度から、令和５年度から開始をしたところでございまして、令和５年度は７月からの開始だったのですけれども。所得制限を撤廃しまして、対象者を拡大してきたところですが、２月末現在で３８５名の方の利用実績があります。","id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たち区民の皆さんの求めにも応じて、港区並みにということをちょっと求めて、増額を求め続けてきておりまして。ですから、これは東京都の補聴器購入費への助成の上限が上がったからということでいいのか伺いたいということと、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"来年度につきましては、こちらを、対象者を変えずに上限を一律で７万２,４５０円という形で実施しています。これまで、迅速かつ的確に対応できたと考えていますので、令和７年度については今申し上げたような内容で実施をしていく考えです。","id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、それをちょっと確認させていただきたいということと、中程度のものでも１０万円を超えるという状況です。ですから、やはりそこを広げていくというところでは検討いただきたいのですが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"東京都から２分の１が、上限額は１４万４,９００円ですけれども、その２分の１が歳入されるような形になります。先ほど申し上げたとおりの経過がありますので、来年度につきましては一度この形でやらせていただきたいと考えています。","id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、これガソリン代が大きな負担になっているという声をいただいています。ぜひここ、助成支給をしていただきたいなと思うのですけれども、もしそのされていない理由だったり、できない理由等があるのがあれば説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"東京都の指定ではないということで、東京都の補助金からの対象外ということになっているのかなというようには認識しております。今年度も物価高騰の光熱水費やガソリン代というところの補助金を出しているというようには認識しておりまして、そのようなお話もあります。","id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、この区内には２７か所あります。通所も在宅も、介護現場は本当に大変ですので、ぜひ支援をしていただきたい、検討をお願いしたいと思いますけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"他団体や他区の動向や事業者の声などを聴きながら、前向きに検討していきたいと思います。","id":"exchange-147"},{"speaker":"大倉委員","kind":"質問・要望","question":"５月から３校のところと、秋から全校展開というところで、予算がどのようになっているでしょうかというところを教えてください。どこに載っているのかということを教えていただきたいということと、これについての補助金のことを教えてほしいと求めました。","respondent":"中島保育施設運営課長、藤村子ども育成課長、佐藤保育事業担当課長","answer":"令和５年度の数字がありますが、２００園の中で８６園、学校と連携した事業を行っているところです。コロナ前が９０園超えていますので… こちら保護者と、あくまでお弁当の業者が契約するという形になっておりますので、少し形態が違うかなというような形で考えております。… 私からはベビーセンサーに対するお尋ねにお答えいたします。","id":"exchange-148"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺についてはどのようにお考えでしょうかということと、どのように提供していくのかちょっと分からなかったので教えてほしいと求めました。誰でも保育ですからいろいろな方が来るかと思うのですが、安全対策が必要かなと思いますが、いかがか尋ねました。","respondent":"中島保育施設運営課長、藤村子ども育成課長、佐藤保育事業担当課長","answer":"やはり区立との連携は今まであったのですけれども、１対１でやると結構大変なので、いろいろと働きかけにも連携していきたいなと考えています。… 今現在、そういった教育委員会と連携して、安全確保のほう図ってまいりたいと考えています。委託業者、３校試行実施する対象の業者の係の方というか… 区のほうで実施しているものでございまして、通常の運営費、様々な加算をして運営費をお支払いしています。","id":"exchange-149"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺は基本的にはすまいるスクールの仕出し弁当と同じで、保護者の責任でしっかりと対応するということでいいのかなというように伺いました。特に、受け入れる側が安心して受け入れられるような体制づくりを進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この間ずっと求めてきたので、システム改修には予算が必要なのですけれども、新年度予算には計上していなかったと理解をしております。これは流用でスピード感を持って行っていただけるということなのか、それとも補正予算を組むということなのか、答えるよう求めました。","respondent":"芝野保育入園調整課長","answer":"件数が約１,６００件から１,８００件ですので、当面は準備が整った園から進めていくということで、手作業でさせていただきたいと思います。年度途中にシステム改修終了すると思いますので、それ以降はシステムのほうで対応させていただきたいと考えております。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平成２９年第１回定例会代表質問におきまして、公明党から高校生の奨学金制度の見直しを求め、実現をいたしました。ここで伺いたいのですけれども、返済免除型奨学金制度がスタートをして、返済をされている方がいらっしゃるのかということを確認させてください。","respondent":"飛田子育て応援課長","answer":"現在の高校生の返済免除型の支援ですが、今まで返済免除にならなかった人数ですけれども、一部免除の方は２名いましたが、全く免除にならなかったという方はいらっしゃっておりません。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"質問・要望","question":"施しと思っているかどうかは分かりませんけれども、いいことですよ、ディーセント・ミニマムの考え方に沿うということではないでしょうか。大学と高校の奨学金との整合性を図るためにも、貸付けから給付型への転換を図ってほしいと求めましたが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"高校生の在学資金のことですが、現在大学生の給付型奨学金を創設したことを前提としまして、またベーシックサービスの考え方も踏まえながら、改めて制度の在り方の検討をしていきたいと考えております。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点目の要望は、周知というものを求めてまいりました。ご家庭へ、誰１人取り残さずお知らせをしていただきたいと求めましたが、今回この体制についてどのように取られているのか確認させてください。","respondent":"飛田子育て応援課長","answer":"昨年度の実績を基にしまして、約４５％が申請する見込みとしまして、約１万６,４２５人を対象としております。基本的には一般入札となるとは認識しておりますけれども、また昨年同様に、坂井市や高知県等も視野に入れて検討していきたいと考えております。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"提案","question":"３つ目として、またその前提として、医療的ケア患者にご参加いただいての実証実験、訓練を行ってはいかがでしょうか。４つ目は、委員ご提案のものについて検討していく、その後の検討状況をお伺いしますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"その活用を予定しています。充電できる場所、訓練、マップにつきましても、引き続き防災課と連携して検討してまいります。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"この、いわゆる医療的ケア児の人工呼吸器のバッテリー充電ということに関しての新たな協定を結ぶと、このような認識でよろしいのか尋ねました。","respondent":"松山障害者支援課長","answer":"防災課と自動車会社が協定を結ぶということで、実際に訪問をさせていただいて、この電気自動車からの電源確保についての、いわゆる関わる協定について今進めているところです。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"実際やはりそのような方のご意見を聞いていただいて、ぜひ速やかに進めていってほしいと求めました。協定が進みませんということではなくて、なるべく速やかに、これは災害がいつ起きるか分からないので、ぜひ速やかにお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、２５９ページ、児童センター運営費、時間があれば、２５３ページの認知症高齢者支援事業についてお聞きします。子どもたちがより快適に利用できる環境を整備していく、そのような考えが必要だと思いますが、まずご見解を説明を求めました。","respondent":"藤村子ども育成課長","answer":"部活があるなど、中・高生の居場所としても認識してもらえるように、そういったもので利用したくなるような機能を充実させたいと思います。一方で、南品川児童センターのような単独館のほうは、個別に改築を進めているような形になっているところです。","id":"exchange-158"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"何というのですか、やみくもに指定管理にしていくということもいろいろ考えものですので、その辺はしっかりと話し合っていただきたいと考えています。去年久しぶりに１人入って、何というのですか、私の感覚ではそう思っているのです。","respondent":"藤村子ども育成課長","answer":"館長のほうでどういった意向があるのかというところを聞きつつ、どういった方法がよいかということは今後検討してまいりたいと考えています。区全体の動向というものを踏まえて検討していくことになるかと思いますが、事業の充実を図っていければいいと考えています。","id":"exchange-159"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"人数も今のところ大丈夫だという確認が取れました。何というのですか、いろいろスムーズに立ち上げがうまくいくのかなと思いますが、その辺についてご見解を説明を求めました。","respondent":"藤村子ども育成課長","answer":"新規事業の実施や、そういったものを導入することで、デジタル化で事務負担の軽減や効率化のほうも図っているところです。館長向けに進めるように話はしておりまして、やめた分始めた形になるのですけれども、やらせていただくような形で予算計上しています。","id":"exchange-160"},{"speaker":"まつざわ委員","kind":"意見","question":"保護者、これもまた子どもたちが共に調理して一緒にご飯を食べる、そして一緒に勉強すると。児童センターというものが、まさしくここに当てはまると思いますが、ご見解を聞かせてくださいとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"各児童センターで食育事業というものも実施しておりまして、児童センターがあって取れた野菜というもの、そういったお話をいただいたこともあります。","id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"何というのですか、すぐに不審者情報というものがいっぱい鳴ってくる中で、先ほど課長が言っていました。先ほど新規予算の中で入退館管理システムですか、というものが、これも補正予算でも見つけたのです。","respondent":"藤村子ども育成課長","answer":"まず入館の際には、ほとんどの館に防犯カメラのほう設置しておりますので、そういった面で安全管理もできているかなというところです。","id":"exchange-162"},{"speaker":"まつざわ委員","kind":"質問","question":"今、何かＱＲコードでメールが飛ぶというと、何ですか、すまいるスクールの、名前が、すみません、忘れました。児童センターは中学生、あと保護者も一々メールが来てしんどいなという方もいらっしゃると思うので、その辺の対応がどうなのかと教えてほしいです。","respondent":"藤村子ども育成課長","answer":"中学生については、現在小学生と同じ運用なのですが、どういった形にしていくかは今後の検討課題かなと考えています。改築を検討しておるところですので、来年度実施設計なのですけれども、子ども・若者を主役とした施設として運用してまいりたいと考えています。","id":"exchange-163"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/552633?Template=document&Id=7007#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":131415,"voices":390}},{"id":"r07-20250311-3","meetingId":"r07-c-budget","date":"2025年3月11日","dateIso":"2025-03-11","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３０９ページ、保健予防費、それと時間があれば、２９９ページ、受動喫煙防止対策費についてお伺いいたします。初めに３０９ページ、予防接種費の中から任意予防接種に関連しまして、百日ぜきの流行と３種混合ワクチン（ＤＰＴ）についてお尋ねしてまいります。","respondent":"五十嵐保健予防課長","answer":"インフルエンザやコロナのようにひどく流行しているというところまでは至っていない状況ですけれども、少しずつ報告が増えてきております。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"どうもありがとうあります。そうしますと、小学校では流行がこれから広まる可能性があるという認識でよろしいか尋ねました。","respondent":"五十嵐保健予防課長","answer":"３種混合の予防接種を計４回受けていらっしゃる方がほぼいらっしゃいますので、予防接種を４回受けている方でも罹患している方がいらっしゃいますので、少しずつ増えてくる可能性としてはあるかなと思っているところです。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、分かりませんけれども、今後、小学校で流行が広がってきた場合、百日ぜきが流行すると何が問題なのでしょうか。説明を求めました。","respondent":"五十嵐保健予防課長","answer":"その子たちにうつしてしまいますと、かなり重症になる方も出てきていらっしゃいますので、それが一番気になっているところではあります。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"百日ぜきワクチンを含む５種混合ワクチンを接種する前の、脳症を起こし、窒息して死亡するケースもあるようです。極めて恐ろしい百日ぜきの流行から小さな赤ちゃんを守るために、区はどのような対策を行っているか、ご説明をお願いします。","respondent":"五十嵐保健予防課長","answer":"お薬をある程度飲めば、うつす危険性もかなり減りますので、そういうことができればと思ってホームページに上げさせていただいているところです。２か月から接種できるということになりましたので、打てる時期になったら早めに打っていただきたいと考えているところです。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１１歳の２種混合ワクチン（ＤＴ）追加接種にも、なぜか百日ぜきが入っておりません。１１歳のときの２種混合ワクチン（ＤＴ）を、百日ぜきから小学生を守るＤＰＴ接種費用助成の施策を強く求めますが、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"以前、厚生労働省の実施している審議会でそのような議論があったということは私も認識しているところです。区が任意予防接種を実施するにしても、なかなか打つことができませんので、現在は区での助成などは考えていないところです。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ本区もいろいろ検討していただいて、百日ぜきの流行・感染を抑えるために取り組んでほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"令和８年度の本格実施について、３１７ページ、これは確認です。最初に、３０３ページの出産についてですけれども、この品川区で母子ともに安心して出産ができるような整備を求めて質問をしたいと思います。","respondent":"石橋品川保健センター所長","answer":"窓口や健診時には、１３言語のタブレットを活用して、言語による不利益等が生じないように丁寧に対応しております。その他、区以外で実施している研修や情報交換会などに参加し、文化や習慣の異なる家庭に対するアプローチなどの知識の習得に努めております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、今も伺ったとおり、１.２％上昇しているということで、外国人の出産が品川区内でもあるわけであります。しっかりと丁寧な対応を進めていただきたいと思うのですが、外国人向けの出産に関する情報発信を行ってほしいと求めましたが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"視覚的に情報を得るということは、いつでも情報の確認ができるということで、とても重要なことだと考えています。こちらからも戦略広報課と連携を図ってまいりまして、そのようなことを進めていけるように尽力してまいります。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"会派からもこの検診を求めてまいりました。２か所で行われました出張型の国保基本健診の利用状況と、また、想定の人数にそこに集っていただいたのかという振り返りをお聞きしたいと思います。","respondent":"若生健康課長","answer":"国保医療年金課で実施しました国民健康保険の出張型の健診の実績につきましてですが、２回実施しておりまして、２回目につきましては２１名。目標数に達したかどうかというところまでは確認が取れていないのですけれども、相当数の人数にご参加いただいたと認識しております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"３３名ご利用いただいたということが確認できました。いらっしゃいますので、男性も対象としてほしいと求めましたが、現在の検討状況をお伺いいたします。","respondent":"若生健康課長","answer":"各医療機関で実施できるように、令和７年度の健診を実施した実績というか実施状況のことも踏まえまして、令和８年度の医療機関での実施に向けて。現状、５歳刻みでというところになってありますので、まずは対象年齢と性別に対して実施していくということを考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"しっかりと検証を行っていただいた上で、より多くの方が受診できる体制をお願いしたいと思います。最後のリユース事業につきましては、区のお考えをお聞きしたいのですが、委託費に対する収入に対しての区のお考えをお聞きしたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"リユース事業につきましては、委託料が１,０００万円ほどかかっているのに対して、歳入が３０万円程度ですので、一定の課題があるものと認識しております。","id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、３０３ページ、産後ケア事業、３１１ページ、こころの健康づくり事業について伺います。その点についても変化があれば説明を求めました。","respondent":"石橋品川保健センター所長","answer":"今年度は、かなり多くの方に利用していただきまして、日帰り型・訪問型については５回までの利用ができるようになりました。かなり継続利用もしていただいているので、大幅な拡充が好評な結果を招いているかなと感じております。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"来年度の予算については、１億５,７００万円余と、また費用についても拡大しております。事業が拡大する中で、次は需要に対する供給、支援の体制というところが必要になりますが、どのように担保しているのか説明を求めました。","respondent":"石橋品川保健センター所長","answer":"日帰り型と訪問型につきましては、今、助産師の方に対応していただいておりますが、そちらについての数の増加などといったご提案を頂いております。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１点、利用者目線の改善ということで、昨年の一般質問でも、予約のオンライン化というところをずっと要望しております。協議していくというようなお話がありましたので、そちらの進捗について、また検討状況についてもお伺いいたします。","respondent":"石橋品川保健センター所長","answer":"その後、受託者と調整と協議を重ねさせていただきまして、４月より電子申請ができる形で今進んでおります。より多くの方に、利便性を上げた形で利用していただけるということで、次年度もしっかりと対応してまいります。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区内の自殺者、事務事業評価シートを確認させていただきました。活動していく中で、このような結果になっていることを、区としてどのように取られていますか尋ねました。","respondent":"五十嵐保健予防課長","answer":"一定、コロナが落ち着いてきたということも影響しているのではないかとは思っておりますが、なかなか分析が難しいと考えているところです。何かこれがということであれば、それは追加しながらやらせていただくということで考えてやらせていただいているところになります。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"特に２０代から３０代の若い世代の自殺率が増加しているということで、インターネット・ゲートキーパーの活用が今進んでおります。品川区としても今行っておりまして、こちらの成果についてもお聞かせほしいと求めました。","respondent":"五十嵐保健予防課長","answer":"品川区では、令和３年１２月１日からインターネット・ゲートキーパー事業を開始しているところです。そのうち、クリック率としましては約７％になっておりまして、新規で相談にまで至った方につきましては７４件という状況になってあります。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"特にご家庭の問題だと「離婚」、「失業」などのワードも、このような自殺のところに引っかかってくるのかなと考えています。インターネット・ゲートキーパーの活用というところをどんどん進めていただきたいと考えていますので、その点を最後に一言お願いいたします。","respondent":"五十嵐保健予防課長","answer":"検索ワードにつきましては、１つのワードだけではなく、いろいろなワードを組み合わせて使っているところです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"３１３ページ、環境調査測定費、大気汚染調査、３２３ページ、産業情報・景況調査等経費に関連して、インボイスの区内影響調査について伺います。伺いますけれども、大気汚染や電波障害の被害の声が寄せられたのですから、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"羽田新飛行ルートに関する区民アンケートの実施についてですが、特に自由記述におきましては、２万７,９２２件の様々なご意見を頂いたところです。２度にわたり、区民の声を届けるとともに、要望書を提出したという対応を取ったところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"環境影響調査測定が必要ではないかと伺いますと、伺いますけれども、新ルート直下にある測定局というのはあるのでしょうか。伺います。","respondent":"中西環境課長","answer":"区に設置されております測定局です。新ルートの直下という意味でいきますと、八潮局がそこに該当するかと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"環境課長に見せてあげてもらっていいですか。伺いますけれども、大気汚染の測定局を設置して測定するよう提案いたしますけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"直下にないというご指摘を頂いたところですが、近いところに八潮局というものもあります。今、現状としては新しく設置するといったことは考えているところではございませんが、環境測定は行ってまいりたいと考えています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"次に、２５日の区民委員会で、そして中小企業の景況でインボイス制度に係る影響調査を要望する陳情が賛成多数で可決されました。伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"昨年１１月の時点で国が実施を予定していた調査につきましては、実際にアンケートを行うというようなことでございました。こういったものについては、法人のデータベースが自治体にないということと、課税情報がないという中で、どのような対応ができるか。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"現時点でそういう立場なので、ぜひ来る本会議でこの陳情を採択して、区議会として品川区に調査の実施を促していく必要があると私は思います。そのことを委員の皆さんに呼びかけて、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"３０５ページ、そして３２９ページ、デジタル商品券発行事業についてお伺いいたします。今その料金をどうしていくのか、現状、今どうなっておりますか尋ねました。","respondent":"若生健康課長","answer":"こういったところを指定管理者も危惧しているところでありますので、慎重に検討を進める必要があるとは考えております。健康に関する講座や、栄養士によるカウンセリング、そういったものも含めて検討を進めているところです。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"納税者の品川区民としては、そうした別の形のサービスの提供ということをぜひお願いしたいのと、ぜひ進めていっていただきたいと考えています。フリーですと年間１万人増やす、教室ですと年間４,０００人増やすという、そもそも品川健康センターはもう既に築何年たっているのか尋ねました。","respondent":"若生健康課長","answer":"修繕との関係ですけれども、品川健康センターも２５年以上経過しているところでございまして、大規模修繕のタイミングがそろそろ来るです。現在のところ、いずれにしても修繕を確実に行っていって、かつ利用者数の増加というところもそれぞれ進めていきたいと考えております。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"いわゆる地域猫活動についてお伺いいたしますけれども、暴言を吐かれたなどで、警察が出動する事態になった。近隣住民とのコミュニケーション、しっかりその辺りの徹底をお願いしたいのですけれども、区としてはいかがお考えなのか尋ねました。","respondent":"赤木生活衛生課長","answer":"要綱にも定めているところではありますけれども、地域猫活動における活動方針といたしまして、徹底することというところで定めているところです。なおかつ、そういった個々の事例につきまして、適正に活動していただくようにお声がけをさせていただきたいと思っているところです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"マップやホームページなどでご案内されていないようですけれども、一方でモデル地区とされているところが１７か所あると。どこがやっている場所なのかということは非常に必要な情報だと思いますので、その辺り、いかがお考えなのか尋ねました。","respondent":"赤木生活衛生課長","answer":"もしくは、あってはならないことですけれども、何かよからぬことを考えてしまうというところの部分にもつながってくる。そういったことにもつながる懸念というのも区としては考えておりまして、今現在としては公表するというところでは考えてはおりません。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり、一方でご迷惑を被っている方もいらっしゃいますので、代替手段の検討やゾーニングの徹底ということをぜひ行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"せらく委員","kind":"確認","question":"２９７ページから公衆浴場について、３０３ページの産後ケア事業、３１７ページのリサイクル活動支援事業について質問します。事項別説明書を確認すると、公衆浴場物価高騰支援金が２１施設に毎月１０万円、どの浴場においても規模感などは近いものなのか尋ねました。","respondent":"若生健康課長","answer":"物価高騰対策支援金につきましては、営業を続けているという前提ですけれども、一律どの浴場も固定の金額ということで支給する予定の支援金です。","id":"exchange-028"},{"speaker":"せらく委員","kind":"確認","question":"要綱も確認いたしまして、営業している月を申告することになっているかと思います。品川区民にとって公衆浴場とはどのような意義があると考えますか。","respondent":"若生健康課長","answer":"公衆浴場の意義です。区民の方の公衆衛生といったところでの利益になるというところで、区としても改修の支援や物価高騰の支援等を行っているところです。","id":"exchange-029"},{"speaker":"せらく委員","kind":"確認","question":"続きまして、産後ケアについては、次年度の方向性も、先日お話があったとおりに確認しています。令和６年度、結構高い目標だったと思うのですけれども、しっかり利用者が増えたことを確認させていただきました。","respondent":"石橋品川保健センター所長","answer":"利用者が大幅に増えているということについてになります。こちらにつきましては、やはり大幅に拡充したこと、あとは利用しやすく、利便性の向上等に努めたことが一因と考えております。","id":"exchange-030"},{"speaker":"せらく委員","kind":"質問","question":"４年ぶりに大きなお風呂に入った、自分だけの時間を過ごすことができたなど、利用者の声が寄せられたそうです。その維持にも力を入れている品川区ならではの産後ケア施策に期待したいのですが、藤沢市の取組について、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"特に実施場所につきましては、利用者の方の安全ということを第一に考えております。産後ケアの実施の場所につきましては、いろいろ検討を重ねさせていただいて、利用者の要望を伺いながら考えていきたいと考えています。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問・要望","question":"やはり安全というところは大事だと思いますので、今後いろいろ利用者の声などをお聞きして考えていただけるということを確認いたしました。こちらはオンラインで画像と情報を併せて確認できます。","respondent":"篠田品川区清掃事務所長","answer":"今年度につきましては、現時点で出品数が２,１０９点で、引渡し件数が２,０４５点となっています。こちらは昨年度が、掲載件数が１３９件で成立件数が１３件、今年度、令和６年度が、掲載件数が１０７件で成立件数が１３件となっています。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"どのようなものが出品されているのか分かりにくいのかと思いまして数字を確認させていただきましたが、あまり交渉が成立していないのかと思います。どのようにリサイクル・リユースの皆様への情報提供ができたらいいのかというところを今後考えさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"１点目に、健康教育事業についてお伺いいたします。紹介、活用してほしいと考えますが、区のお考えをお願いいたします。","respondent":"三ツ橋荏原保健センター所長","answer":"様々な個別支援を行うとともに、講演会など各種、こころの健康づくり事業を実施しています。熟達した専門家が必要となる当事者研究の手法などを、ポピュレーションアプローチに対しまして取り入れることというのは難しいと考えております。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"そういったところをぜひ取り入れていただきたいということで、ぜひ広めていただきたい、伝えていただきたいということを要望します。２点目に、不妊治療等支援事業についてお伺いいたします。","respondent":"若生健康課長、福地大井保健センター所長","answer":"私どもが実施している不妊治療等支援事業の関連で申し上げますと、現在実施しております不妊不育等の相談事業といったところで、そのような男性不妊の悩みにもきめ細かく対応しています。保健センターでは、依存症の相談がありましたら、保健師や精神保健相談員等が区民の相談に応じ、必要に応じて医師による精神保健相談につなぎます。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"どういった形で相談にしっかりとつなげて、相談から治療や、考え続けていただきたいと考えています。依存の部分なのですけれども、ぜひそういった知識や海外の事例といったところを引き続き高めていってほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"こしば委員","kind":"質問・要望","question":"３０９ページ、また、３２９ページのデジタル商品券発行事業についてお伺いいたします。デジタル商品券導入の目的や、期待される効果についてお伺いいたします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それから３点目については、区民の皆様、利用者にとっての利便性の向上を図ることを考えております。２点目の効果につきましては、新しくデジタルというところで、若年層の利用の拡大を図っていきたいと考えているところです。","id":"exchange-037"},{"speaker":"こしば委員","kind":"質問","question":"確かに統計を見ましたら、昨年の紙の共通商品券を購入した世代を割合で見ますと、２０代の方は大変少なく４％と伺っております。このデジタル商品券の導入に至ったものとも考えておりますが、改めて、若年者の割合４％というものをどのように分析されたのか説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"あくまでサンプルではあるのですけれども、その中の回答で、やはり商品券の取扱い店舗数が少ないといったお声もございました。そういったところで、デジタルの商品券の導入に当たっては、対象店舗の拡大も図ってまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"こしば委員","kind":"質問","question":"利便性というのももちろんですが、まずもって消費の喚起を明確にすることが重要だと考えております。その点について、消費の喚起に向けた取組についてどのように検討されているのか、説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"来年度は、紙の商品券も実施しながらデジタルの商品券も実施するというような、両方で実施していくところです。大手の店舗でもご利用いただけるようなことも考えておりますので、利便性の向上を図って消費の喚起につなげていきたいと考えているところです。","id":"exchange-039"},{"speaker":"こしば委員","kind":"質問・要望","question":"どうしても、時代の流れに追いつくことが大変難しいお店もあります。デジタルだからこそ、スピードを持って振り込まれるよう検討ほしいと求めましたが、併せてお考えを教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"確かに、中小の支援という観点に立ちますと、お店側の負担や換金へのサイクルをいかに短くするかということは重要な観点と認識しています。そして区民の利便性を向上していくか、今、委員がおっしゃったような観点もきちんと踏まえて決定してまいりたいと考えているところです。","id":"exchange-040"},{"speaker":"こしば委員","kind":"質問・要望","question":"続きまして、予防接種に関連して、ＲＳウイルス母子免疫ワクチン、アブリスボについて、再度お尋ねいたします。昨年の決算特別委員会で私から、ＲＳウイルス母子免疫ワクチンの接種費用の助成について要望を行わせていただきました。","respondent":"五十嵐保健予防課長","answer":"ＲＳウイルスの感染症につきましては、最近になりまして、夏や春などに少しずつはやってきたりしているような状況です。少し増えたりしていましたが、横ばいのような状況になってございまして、全国的には少し増加傾向が見られているような状況になってあります。","id":"exchange-041"},{"speaker":"こしば委員","kind":"質問・要望","question":"昨年の決算特別委員会では、接種費用の助成について要望を行いましたが、残念ながら実現には至りませんでした。予算でアブリスボに対する接種費用助成がなぜ見送られたのか、ご説明をお願いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"ＲＳウイルス母子免疫ワクチンについてですが、現在、国の厚生審議会で定期接種に向けて検討されていると認識しております。区としましては、区だけで実施するというところは難しいかと考えておりますので、国の状況を見守っているところです。","id":"exchange-042"},{"speaker":"こしば委員","kind":"確認","question":"このＡＣＩＰの研究報告でも、ＲＳウイルス母子免疫ワクチンを接種しても、早産・低体重のリスクは増加しないことが確認されたわけです。この現状を区はどのようにお考えか尋ねました。","respondent":"五十嵐保健予防課長","answer":"接種費用が高くて見合わせているという方もたくさんいらっしゃると考えておりますが、やはり妊婦ということで、体感では感じているところです。妊婦の方たちにも安心して打っていただけるように、国の指針を待ちながら様子を見させていただきたいと考えているところです。","id":"exchange-043"},{"speaker":"こしば委員","kind":"質問・要望","question":"だからこそ、啓発というのもまた大きなものであると思います。ＲＳウイルス母子免疫ワクチンの接種費用の補助を、また本予算特別委員会でも要望いたしまして、私からの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろなところで当事者意識の拡充・必要性というのは繰り返し求めてきて、少しずつだと思うのですけれども、品川区で取り入れていただいている。今、どういう体制になっているのか、まず説明を求めました。","respondent":"遠藤健康推進部次長","answer":"保健師の人材育成という部分になろうかと考えていますけれども、あるいは中堅期の保健研修などで、それぞれテーマを持ってやっているところです。傾聴や、区民の方に対して寄り添うというのは非常に大事な観点と考えておりますので、いろいろ講義などを受けているところです。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"学校の養護の先生とも相談して、スクールカウンセラーの先生にもいろいろお話を伺って、いろいろなアドバイスを頂いて、今やっている。区民がそういったときに相談できる場が、今、品川区はどういう状況なのかというのを説明を求めました。","respondent":"森澤区長","answer":"心の部門だけではなくて、そういった研修も含めて、今後しっかりと取り組んでまいりたいと考えています。いつそういった悲しみを抱えても、少しでも寄り添える区にしていけるのかということを、今後考えていきたいと考えています。","id":"exchange-046"},{"speaker":"つる委員","kind":"意見","question":"そうした課題も、当事者になって初めて、そうなのだと。まさに人に寄らず、そのテーマに沿って頑張っていくという精神なので、これからも全力で頑張りますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"おぎの委員","kind":"提案","question":"１０年以上かけてしっかりと安全性を確認して使用されるべきものですが、今回のｍＲＮＡワクチンは、誰も接種後１０年の経過を見たことがありません。紙に比べて保管しやすくなりますので、品川区でも保管期間の延長を提案しますが、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"紙のものにつきましては５年で廃棄しているような状況ですが、そちらについては今の時点で保管の年数は考えていないところですが、ほかの予防接種と同様に記録として残しています。","id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問・要望","question":"新規事業の５歳児健康診査事業についてお伺いします。はこの事業の狙いと、５歳児に設定した理由を説明を求めました。","respondent":"石橋品川保健センター所長","answer":"５歳児健康診査につきましては、適した支援につなげる機会が重要であり、こちらを重要として５歳児健診を今回実施したいと考えております。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"５歳のこの時期に発育状況や社会性の発達などの確認をするということですので、必要に応じて早めにサービスや支援につなげてほしいと求めました。５歳児健康診査に付随して、子どもの発達障害についてお聞きします。","respondent":"石橋品川保健センター所長","answer":"保健センターでも、乳幼児経過観察や心理相談などを、未就学児を対象に実施しております。５歳児健康診査も実施することも踏まえまして、５歳児健康診査の事後フォローというところで、しっかりと対応していきたいと考えております。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"状況を見ながら、ぜひ子どもの成長に寄り添った支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから３０７ページ、それから３１５・３１７ページで、環境啓発・推進事業と資源物再商品化経費について伺います。逆にどこに相談していいか分からないのではないかという懸念もあったのですけれども、その相談窓口の成果について、まず伺います。","respondent":"五十嵐保健予防課長","answer":"少し相談してみようかと思っていただけると考えていますので、効果というよりは、そういうときの助けになればという思いで置かせていただいているという部分が大きいかと考えているところです。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"ひがし委員の質問内容と併せて、電話相談されたものと、そういうものを結びつけるような仕組みはできないものでしょうか。自殺に限らずいろいろな事前の悩みの相談に結びつけられるような仕組みができたらいいと思うのですけれども、何かお考えがあれば伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"こちらがやはり、そういう相談ができるところに飛べるようなものを出していただいているところですが、そちらから相談に至っているケースもあります。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"とても残念だと思って、対象を広げていただけないだろうかということを再三質問してきたのですけれども、その点についていかがでしょうか。本当にかつては低かったのですけれども、その辺の増減といいますか、その点についても伺いたいと思います。","respondent":"若生健康課長","answer":"検討会も、障害者支援課にも入っていただいて行って、検討を進めてきたところです。今年度で言いますと１月末現在で２９名ということで、まだまだというところではありますので、引き続き周知・啓発に努めていきたいと考えております。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺の協力体制はどうなのでしょうかということと、再三、環境のところで申し上げております。砂ぼこり対策の代わりに、その辺について伺います。","respondent":"中西環境課長","answer":"何か区でできるかといったことは検討していますので、引き続き、様々な形で取り組んでまいりたいと考えています。２０２０年でしたか、国内水域のマイクロプラスチックのうち２０％が人工芝だというような報告書が上がっているということは認識しています。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"その状況を放置し、かつ推進してしまうような政策はいかがなものかということで、しつこくしつこく伺っております。日本容器包装リサイクル協会に依頼してというところまではご答弁を伺っているのですけれども、その後の何か進展があったら伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"令和４年に、全国の自治体を見ても、やっているところは非常に少ないという状況があります。区独自の再商品化をしようとしても、難しいという状況があって、なかなかほかの自治体を含めてできない状況があるものと認識しています。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"それも確認させてください。ぜひ広げていただきたいと思うのですが、先日の参加者の方からのご反応なども含めて、今後の方向性やお考えがあれば伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"シニアの今後の多様な働き方ということを１つ、前提にしたような働き方が中心となっていたと認識しておりますが、１つ出資もしながら。今後も、こういった啓発といいますか、こういうことを知っていただく取組を引き続き続けてまいりたいと考えております。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望でとどめます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３２０ページから始まる産業経済費に関わって、中小・零細企業支援を求めて伺います。現在の中小・零細企業の状況がよくなっているのか、悪くなっているのか、区の認識を伺います。","respondent":"小林地域産業振興課長","answer":"ＤＩ値で、悪いと答えている経営者の方の差を見たときに、これはやはり厳しいとお考えになっている経営者の方が多いと考えております。今後、令和７年度の予算案も含めまして、行政の支援というのは引き続き必要であろうと考えているところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"代表質問で実施を求めたところ、今後の政府の取組などを注視しつつ、引き続き必要な事業者支援策を検討するとの答弁でした。この状況を見ると、喜ばれていた省エネルギー対策・業務改善設備更新助成金を復活させるべきではないかと思いますが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"これについては、過去、区で補正予算を組む中で、いわゆる燃料費補助というものを実施した例があります。いろいろ補助が復活する時期、区内事業者の方にとって支援が必要というタイミングが来れば、そういうことも考えてまいりたいと思います。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"政府の電気・ガス代支援が終わっているという状況を見れば、実施するときではないかと思うのですけれども、いかがでしょうか。業種を限定せずに、固定費である家賃や水道光熱費の補助をぜひしてほしいと求めましたが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"直接的な支援といいますか、そういうものを継続する場合に、こういった支援をどこまで続けるかという点も。我々もこの状況で、タイミングを見誤らずに、きちんと支援ができるようにということでは考えていきたいと考えています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実施していただきたいと思うのですが、やはり１つ、ハードルがあると思います。ぜひ、そうしたことも踏まえて実施してほしいと求めましたけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"過去に家賃支援の助成ということでございましたけれども、コロナのときに実施していた、家賃支援給付です。継続的にどこまで支援するべきか、それに対する支援をやることによって、事業者の方の自助努力といいますか。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"今は支援するべきときではないかと思いますので、あと省エネルギー対策・業務改善設備更新助成も、ぜひ実施してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"３０４ページ、災害時の食事の質の確保やキッチンカーの活用について、保健所の役割を発揮させるための計画策定と訓練を求めて質問したいと思います。そして、講演会を受けて、今後、保健所として防災計画・防災対策に反映させたいもの、今後充実させたいものは何か、お考えを伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"１点目につきましてですけれども、１月２１日、全体を通しての意見やご感想として頂いている内容についてお答えします。大変興味の高いテーマだったというところで保健所としても認識しておりますので、保健所として普及啓発に取り組んでまいりたいと考えております。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて、保健所としてはどういった計画や訓練が必要だと思っているのか伺いたいと思います。災害時の食事の提供へ、保健所としての力を発揮してほしいと求めましたが、併せていかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"全体との整合性を図りつつ、さらに効率化していけるよう、今後検討を進めていきたいと考えているところです。防災計画の中で定めていくものと考えておりますので、その辺りは防災課と連携しながら、今後も我々としても協力していきたいと考えています。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"防災課も動いておりますけれども、強調したいことは、保健所ならではの専門性を防災対策に反映していただきたいということです。改めて、今後の取組や具体化についてお考えを伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"今後の保健所としての取組についてのご質問にお答えします。食の安全という部分につきまして努めていきたいと思っているところと、様々な機会を捉えて普及啓発に取り組んでまいりたいと考えています。","id":"exchange-066"},{"speaker":"澤田委員","kind":"質問","question":"本日は、３１９ページ、収集運搬作業費、３２３ページ、中小企業事業資金融資あっせん、時間があればチャレンジ支援資金もお願いしたいと思います。車両雇上げ費が１２億５,７５６万８,０００円と一番大きな金額でありますが、内容をご説明いただけますか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"そこに区の職員が乗って収集作業をするという、私どもでは雇上と言っているのですけれども、雇上げにかかる経費です。予算書に載っているのは、そちらの一般のごみの分と粗大ごみの分の両方を合わせた経費となっています。","id":"exchange-067"},{"speaker":"澤田委員","kind":"質問","question":"すぐに離職してしまう方も多く、ドライバーについては２０２４年問題もありますし、人材確保が大変厳しいとお聞きしています。ごみ収集のサポートシステム、アプリの導入について、区としての考え方を説明を求めました。","respondent":"篠田品川区清掃事務所長","answer":"ただ、やはり効率化というのが非常に重要であるのは間違いないということも認識していますので、我々も非常に関心を寄せているところです。ですので、できるだけそういった部分を、取り入れられるものについては取り入れていくという形で考えてまいりたいと思っているところです。","id":"exchange-068"},{"speaker":"澤田委員","kind":"質問・要望","question":"関連して資源ごみについてお聞きします。他課と連携して、ごみの分別についての周知啓発の強化を進めていただきたいと考えますが、ご見解を説明を求めました。","respondent":"篠田品川区清掃事務所長、中西環境課長","answer":"来年度は新たに、関心のない方に対しても届くような形で、何とか周知を進めていきたいという思いもあるところです。そういったときというのは、そういった機会をどう活かせるか、関係の各課とは連携してまいりたいと考えているところで… なかなかすぐにというわけにはまいりませんが、リニューアルする際には、頂いたご意見を含めながら検討してまいりたいと思ってあります。","id":"exchange-069"},{"speaker":"澤田委員","kind":"質問","question":"続きましては、３２３ページ、中小企業事業資金融資あっせん、チャレンジ支援資金についてご質問いたします。具体的にどのような取組を進めてきたのか、改めて説明を求めました。","respondent":"小林地域産業振興課長","answer":"ただいまご質問いただいた部分で申し上げますと、コロナのときに我々が一番重視しましたのは、事業継続をどう図っていくかという点です。３年間無利子、区内企業の支援を行ってまいりまして、トータルで申し上げますと５５０億円近い融資あっせんの支援を行っているところです。","id":"exchange-070"},{"speaker":"澤田委員","kind":"確認","question":"様々な取組を行っていただいていることは確認できました。国や都をはじめ、区の支援策によって救われた区内中小企業も多かったのではないか尋ねました。","respondent":"小林地域産業振興課長","answer":"３年間無利子のような融資あっせんの支援メニューをつくりましたし、上限８０万円の支援ということで、３８４件の支援ということで。","id":"exchange-071"},{"speaker":"澤田委員","kind":"質問・要望","question":"さらに、中小企業にとっては物価高騰以外にも、人材不足への対応やＤＸ化を求めるなど、新たな経営課題が様々出てきています。区としてはどのような対策を講じていくつもりなのか、説明を求めました。","respondent":"小林地域産業振興課長","answer":"令和７年度の新規施策としましては、チャレンジ支援資金という新たなメニューを設けております。ＤＸやＧＸ、金利負担をゼロにするような形で、今までよりも拡充した支援というのを考えてまいりたいと考えています。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"３０９ページ、３２９ページ、デジタル商品券発行事業の３点を伺っていきたいと思います。そうなった時点から、区が対象拡大で進めていくスピード感、どのような段取りで進めていくのかについてお伺いしたいと思います。","respondent":"若生健康課長","answer":"昨年度から実施してまいりましたが、その伸びも見込んで増額しているというところが、まず１つあります。拡充していくというところは認識しておりますので、中身を詳しく精査しながら、対応についてはしっかり検討してまいりたいと考えております。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"ここで使えるお店や、これで使えたお店といったところが１つの参考として考えられるのかと思いますけれども、いかがでしょうかというのが１点目。それから、デジタル商品券の購入者は区民に限るのか限らないのかというところについて、お伺いしたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"デジタル商品券を先行で実施している自治体の調査などをしている中で、個店、とりわけ商店街支援の側面を強くやっていたところですけれども。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"一般的なキャッシュレスとは違うものなので、ここは手数料なしで、ぜひ実施していただきたいという思いがありますけれどもということ。この辺のシステム周りのことについてお伺いしたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ですが、負担がかかるということは大変認識しておりますので、そういった観点も含めてきちんと業者選定はやっていくことを考えているところです。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"精神疾患についても、早期発見と早期治療が望ましいということは一定の定説としてあると理解しております。内科は２４１件ですので、どのようなことが見解としてあるか、最後にお聞きいたします。","respondent":"三ツ橋荏原保健センター所長","answer":"区として、区民の方に対してまずはご相談を受けるというのが、保健センターでは丁寧にご相談を受けているところです。","id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私は、２９７ページ、ＡＥＤ管理費、３０３ページ、見守り定期訪問委託、時間があれば３２７ページの雇用確保支援事業でお願いします。助成も含めてなのですけれども、そんなところをもしお伺いできればと思うのですが、いかがか尋ねました。","respondent":"若生健康課長","answer":"コンビニエンスストアへの設置については、１店につき１台ずつ設置していただいておりまして、９１店舗に設置が完了しています。今のところ予定はないところですが、各所管で設置が必要と判断された場合は、設置につなげていくというようなところで。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"提案","question":"そこで提案したいのが、通所型や入居型の介護施設への設置助成です。ぜひご検討いただきたいのですが、いかがか尋ねました。","respondent":"若生健康課長","answer":"そもそも民間の施設につきましては、そういったところは各所管で検討を進めているようなところかと認識しております。設置場所や使用方法の周知、ソフト面の対応について現状では力を入れていこうというところで、今の段階では考えているところです。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"確認","question":"他自治体の議員からも私に問合せがあるぐらい、注目を浴びている区の事業です。別の日に質疑がありましたけれども、利用者の満足度が９０％を超えていたと記憶しているのですが、その点を改めて確認させてください。","respondent":"石橋品川保健センター所長","answer":"２月に利用者のアンケートを行ったところ、事業全体の満足度が９２％という回答を頂いております。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"確認","question":"そういったアンケート調査になっていないということでよろしいですか。確認です。","respondent":"石橋品川保健センター所長","answer":"昨年度よりおよそ８％上昇しており、開始より、相談支援に対する評価が上がっていると認識はしています。相談支援も助かっている」という、相談支援を評価する声も頂いているのは、回答として認識しております。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実働９名、有資格者が１名ということで、どうしても感じてしまうところです。実施可能か尋ねました。","respondent":"石橋品川保健センター所長","answer":"なので、そこの部分、確かに、支援員の方の対応がというご意見があるということはしっかり受託者に指導してまいりたいと考えています。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"今はほぼ、無資格者の方が多くて９名ということなので、もっと手厚くしてくださいというようなことを求めていってほしいと求めました。最後にお願いします。","respondent":"石橋品川保健センター所長","answer":"その辺りにつきましては、今後検討してまいります。","id":"exchange-082"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは、３２３ページの武蔵小山創業支援センターについて、時間がありましたら３０７ページのネズミ対策事業について伺います。初めに３２３ページの武蔵小山創業支援センターについて伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"も全体の起業家からするとまだ２５％ということで、より一層の支援といったところで、今も継続してやっているところです。それから、小売やサービス業といったところが多いですので、例えば商店街と連携したテストマーケティングといったところなどをやっているところです。","id":"exchange-083"},{"speaker":"松永委員","kind":"質問","question":"先ほど、例えばより一層の支援ということでございましたけれども、具体的にどういった支援なのかお知らせください。テストマーケティングについて、どういったものなのかを改めて伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ワークショップを年に２回行っておりまして、３月１３日から行いますので、お越しください。そのＬＩＮＥの会員が２,０００名弱おりますので、それを活用して学びたい人をマッチングするカルチャースクールなども実施しています。","id":"exchange-084"},{"speaker":"松永委員","kind":"確認","question":"次に、３１３ページの環境対策費の、野鳥への餌やりについて伺います。その理由について伺いたいと思います。","respondent":"中西環境課長","answer":"餌やり防止看板の記載内容のお話です。ハトに限らず、例えばムクドリや、ほかの野鳥のご相談が来る場合もありますので、そういうところでそういった記載になっているものです。","id":"exchange-085"},{"speaker":"松永委員","kind":"意見","question":"その内容につきましては、５,０００円の罰金などとしている自治体もあります。誰もが安心して暮らせる品川区を目指して、一歩前へ進めてほしいと求めましたが、区の考えをお知らせくださいとの意見を述べました。","respondent":"中西環境課長","answer":"環境課の職員が、たまにですが、朝６時ぐらいに現場に伺ってやらせていただいたりもしています。１つ、そこに罰則をかけるといったことが、どういった形で効果が出せるかといったところはこれから研究してまいりたいと考えています。","id":"exchange-086"},{"speaker":"松永委員","kind":"提案","question":"本区では、猫の被害を受けた際、どういったご対応をされているのでしょうか。もしこうした補助が難しい場合は、被害を受けられている方への取組について併せて伺いますとの意見を述べました。","respondent":"赤木生活衛生課長","answer":"支援という部分ではありますけれども、そこに再びふん尿の被害を受けないような形で、こちらとしては助言をさせていただいているところではあります。","id":"exchange-087"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に、時間がなくなりましたが、３０７ページのそ族昆虫防除対策費について伺います。そうしたところの選定など、ネズミ被害を少しでも軽減できる対策の一つとして取り入れていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"ネズミの被害を受けられた方への助成という部分でのご質問かと思いますけれども、区としましては現在、ネズミ駆除費自体の助成というのは検討はしていないところではありますけれども、今後、他自治体の動向等も注視していきたいと思います。","id":"exchange-088"},{"speaker":"えのした委員","kind":"質問・要望","question":"東京都や品川区の支援の内容や状況について質問するとともに、商店街支援をさらに拡充していただくよう要望させていただきました。その後、令和７年度予算編成に当たり、新しい支援の方法は何か盛り込まれていますか尋ねました。","respondent":"小林地域産業振興課長","answer":"１つご紹介させていただきたいのが、商店街の活性化がテーマの一つとされ、議論が進められたところです。従来のイベント支援枠とは別に、新たに助成金を交付する支援の取組というのを、新たに追加したところです。","id":"exchange-089"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。政策評価委員会ですか、令和７年度からの新しい助成事業の内容について、ホリデー・トレーニング事業助成との比較があればお知らせください。","respondent":"小林地域産業振興課長","answer":"区の単独の支援ですけれども、助成金の上限は１イベント当たり２０万円、補助率は３分の２と設定しております。補助率を５分の４としまして、商店街の皆さん、関係する団体・企業の皆さんなどの活用をより促してまいりたいと考えております。","id":"exchange-090"},{"speaker":"えのした委員","kind":"確認","question":"同じく昨年１０月の決算特別委員会では、商店街に対する物価高騰支援についてもお伺いしました。その動向なども併せてお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"飲食店の方は今回、新紙幣対応券売機の導入よりは、厨房施設・調理機械の省エネルギー化を優先されていたかなと考えています。令和７年度の新たな予算書の中に、新紙幣対応券売機については、こちらの助成金の中で令和７年度も引き続き支援できると考えております。","id":"exchange-091"},{"speaker":"えのした委員","kind":"質問・要望","question":"当初１５０件から３８４件と倍ぐらい、件数が伸びておりますし、商店街の飲食業の厨房施設ですか、全体の５２％ということで確認が取れました。これは７件と少なかったところですけれども、補正予算や令和７年度予算が編成されていると確認が取れました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、３０１ページの地域医療連携はＡＣＰ、アドバンス・ケア・プランニングについてお伺いします。区の予防について、現在どのように取り組まれているのか説明を求めました。","respondent":"若生健康課長","answer":"区民の健康のために様々な研修等を実施しています。歯科健診、それからがん検診等を実施しておりまして、それで何かあった場合は受診につなげていくといったことが重要ではないかと考えています。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"提案","question":"７３（ナナサン）歯科健診ですか、新たに導入されて、歯の健康も含めて全体の健康を守っていこうという取組だと思います。子どものときから予防することによって、将来の医療費も削減するといった取組をしてほしいと求めましたが、いかがか尋ねました。","respondent":"若生健康課長","answer":"乳幼児歯科健診等を実施しているところではありますが、一定、理解できるところです。今後どういった形で、区が歯科の対応、特にお子様の歯科というところに関してできるかというところは考えてまいりたいと思います。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私も今日やるつもりはなかったのですけれども、１つだけ、アドバンス・ケア・プランニングについてお伺いしたいと思います。現在、品川区では、いわゆる人生会議とも言われていますが、どのようにこれまで取り組んできているのか説明を求めました。","respondent":"若生健康課長","answer":"アドバンス・ケア・プランニングにつきましては福祉部で進めている事業と認識してございまして、私どもとしては、医療と介護の連携というところで、一定、医療のほうで関わっているところはありますけれども、詳しい状況については把握しているところではございません。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問","question":"特に今は、いわゆる１人で生活をされている、身寄りのない高齢の方もどんどん増えています。これからの日本の社会においても必要な制度だと思いますが、改めてこの点について、医療連携の部分でどのように感じているのか説明を求めました。","respondent":"遠藤健康推進部次長","answer":"昨今、医療と介護の連携なども含めまして、様々な部分でいろいろと連携していかなくてはいけない部分があろうかと考えています。なかなかご答弁は難しい部分がありますけれども、そういう部分でしっかり周りの第三者も巻き込みながら進めていきたいと考えています。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問","question":"カレーライス指数というのですか。賃金アップをするための対策というのもやはり考えていかなければいけないと思いますけれども、中小企業をどのように考えているのか説明を求めました。","respondent":"小林地域産業振興課長","answer":"区で様々な中小企業支援を行っておりますけれども、あるいは賃上げをやっていくための余力をいかにつくっていくかということだと考えております。その点、引き続き中小企業支援を充実させてまいりたいと考えております。","id":"exchange-097"},{"speaker":"こんの委員","kind":"提案","question":"この課題は、我が会派の先輩議員が２００５年より提案・要望してきた悲願の政策でした。そこで、来年度はモデル実施から事業開始となるということですが、どのように健診を展開されるのか、具体的にご説明くださいとの意見を述べました。","respondent":"石橋品川保健センター所長","answer":"令和５年、「母子保健医療対策総合支援事業の実施について」というところで、５歳児健康診査の意義と目的について通知が出されました。そこから、区の手法もしっかりと考えて、次年度からモデル実施ということで進めてまいりました。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"内容的には、こちらが求める内容が網羅されていて、それを活用される区のお考えは理解いたしました。１歳半健診と３歳児健診は、乳幼児健診の記録のページがないので、これはどういうふうに取扱いをすると考えていらっしゃるか尋ねました。","respondent":"石橋品川保健センター所長","answer":"リトルベビーハンドブック、東京都が出しておりますＮＩＣＵ退院支援手帳「のびのび」についてになります。そちらに記録させていただいて、併用という形で活用していただくようにということで、こちらもご案内させていただいているところになります。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"２冊を持って使い分けるのは結構大変なことで、１冊でまとまっているということが非常に大事かなといった観点もあって要望させていただきました。そうした観点で、いま一度ご見解を頂きたいと思いますが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"委員ご指摘のとおり、２冊持っていく、持参するというのは、少しお荷物になってしまうというご指摘も理解できる部分ではあります。こちらの手帳はいいものができていると東京都からも説明を受けておりますこともありまして、実際、今後のことを研究してまいりたいと考えています。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"２冊、あっちを見てこっちを見てということのないような手帳を求めていきたいと思いますので、今後研究してほしいと求めました。自己負担がかかるという扱いのものになっていると聞いているのですが、その辺は、定期接種化されても費用がかかってしまうものなのか尋ねました。","respondent":"五十嵐保健予防課長","answer":"Ａ類疾病とＢ類疾病についてですが、Ａ類疾病は、人から人に伝染することによる発生および蔓延を予防するために行う予防接種と規定されております。やはり個人の発症の予防に重きを置いているものですので、こちらについてはお金を少し、自己負担を頂いているという状況です。","id":"exchange-101"},{"speaker":"こんの委員","kind":"確認","question":"Ａ類疾病、Ｂ類疾病、それぞれ自己負担はあると。特にＢ類だから自己負担だということではないということは確認いたしましたけれども、どれぐらいを自己負担と予定されているのか説明を求めました。","respondent":"五十嵐保健予防課長","answer":"現在、まだ幾らということまでは決定できていない状況ではありますが、今までの……。","id":"exchange-102"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこで、具体的に伺いたいのですけれども、今回、太陽光が最大２０万円に拡大されました。そのことによって、例えば太陽光発電１キロワット当たり自己負担が幾らぐらいでつくことになるのか、伺いたいと思います。","respondent":"中西環境課長","answer":"それから、大体１０万円前後の補助金という形になってありますので、残りの部分が自己負担という割合になってくるかと考えています。今後、パンフレットの中でも、そういったもののパンフレットは作成してまいりたいと考えているところです。","id":"exchange-103"},{"speaker":"鈴木委員","kind":"質問・要望","question":"例えば、気候危機、こういう支援策があることを知らないために使われないということもあるのではないかと思うのです。知らせていただきたいということと、「ここに行けばこういうのを全部教えてもらえます」というような、いかがか尋ねました。","respondent":"中西環境課長","answer":"来年度少し考えているのが、エコルとごしでのパネル展示や出張相談会みたいなものも検討してまいりたい、やってまいりたいと考えています。環境に意識がある方以外の方に届くように、どういう取組ができるかといったものに関しては積極的に検討してまいりたいと考えています。","id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は、この保健師の増員については、ずっと長い間求め続けてきたのですけれども、なかなか改善されない状況が続いていると思います。新年度の保健師の定数が何人になるのか、それから２３区で人口対比で何番目になるのか、また２３区平均まで何人足りないのか、伺いたいと思います。","respondent":"宮尾人事課長","answer":"今、手元に詳細な数字を持ち合わせていないのですが、特段、保健師だけが突出して多いなどという状況にはないと認識しています。こちらも詳しい状況はあれですけれども、保健師だけをもって、ほかと比べて突出して多いなどという特徴的な状況ではないと捉えております。","id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に、現場は大変な状況が続いているということで、お話を伺っています。こういうところも参考にしながら計画をつくっていただいて、増員というのを図っていただきたいと思うのですが、いかがか尋ねました。","respondent":"宮尾人事課長","answer":"保健師に限らず、全ての職員、全ての職種において、年度ごとにしっかりと必要性を見極めながら、必要な人材の確保に取り組んでまいりたいと思います。","id":"exchange-106"},{"speaker":"田中委員","kind":"質問","question":"私は、３０１ページの地域医療連携、また３０９ページ、感染症予防費に、まずは関連してお伺いします。感染症に対する取組は、今まで以上にしっかりと、区でまとめていただいた報告書もしっかり踏まえた上で対応すべきだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう中、品川区におきましても、新たな課として地域医療連携課が発足されていらっしゃいます。これまでの医師会からの要望や対応、あと今後の課題などが新たに分かれば、そういった成果を教えてほしいと求めました。","respondent":"遠藤健康推進部次長","answer":"４月から地域医療連携課が設立されまして、今、医師会を中心にいわゆる定例会というものをしています。要望も頂いたり、大分、医師会との本当に率直な意見交換ができていると考えているところです。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"まだこの時期ですから、まだコロナの意識は残っておりますが、これから時間の経過とともに薄れることもまた懸念されます。そういった意味の区民の意識の継続という取組について、お考えがあればお伺いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"なるべくお伝えして、感染症についても啓発させていただいているところですが、やはりなかなか継続していくのは本当に難しいと考えています。ただ、なるべく機会を捉えて、皆さんにまた周知を繰り返してやっていきたいと思っているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ引き続き支援をお願いしたいと思いますが、あえてお伝えしながらお伺いしたいのですけれども、要は様々な品川区の施策が行われます。そこはこうしてほしいなど、ぜひ課長にお願いしたいと思いますが、そこはいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"我々地域産業振興課だけではなくて、それ以外にも、例えば環境課や、あるいは観光の部門、都市環境の部門など、いろいろ関連が出てくると思います。","id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"デジタル商品券に関しても、これまで既存の商店街の振興という意味で共通商品券の活用がありました。そういった視点も配慮していただいた上で対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"西村委員","kind":"質問","question":"３１３ページ、３１５ページ、脱炭素とごみの減量に向けて伺ってまいりたいと思います。宅配ボックス設置助成が始まり、しばらくたったのですけれども、広がりや経過を伺えればと思います。","respondent":"中西環境課長","answer":"今年度９月より開始いたしました宅配ボックス設置助成です。令和７年度に関しても、建設業界を含めまして、幅広く周知を行って拡大してまいりたいと考えています。","id":"exchange-112"},{"speaker":"西村委員","kind":"質問","question":"なかなか数字を出すのは難しいと思うのですが、私も興味を持っておりますので、認知度や執行率の向上に向けてお願いしたいと思います。こちらもどのような事業か伺えればと思います。","respondent":"中西環境課長","answer":"売れ残りが出そうな食品が発生した際にアプリに出品しまして、それを、アプリに登録しております区民の皆様に購入いただくといったものです。","id":"exchange-113"},{"speaker":"西村委員","kind":"意見","question":"単にごみを減らそうと呼びかけるだけではなく、人々の行動を変える取組が必要な中で、日常に溶け込んでいる事業だと考えています。楽しさや便利さをプラスすることで、区民の皆さんが自然と参加したくなる取組をこれからもお願いしたいと思いますが、一言お願いいたしますとの意見を述べました。","respondent":"中西環境課長","answer":"食品ロスに関しましては、私どもとしましても課題であると考えています。１０月に食品ロス削減月間等もありますので、そういったところも捉えまして、大きく展開してまいりたいと考えています。","id":"exchange-114"},{"speaker":"西村委員","kind":"質問","question":"新たな課題であると思うのですが、日本のエネルギー消費量の約３割を占める建築物の分野における取組が急務となっており、伺いたいと思います。区としての考えや来年度の取組について伺えればと思います。","respondent":"中西環境課長","answer":"委員がおっしゃいますとおり、住宅、それから建築物の脱炭素化は急務です。工場・事業所をＺＥＢ化する際の設計補助といったものを開始いたしまして、住宅や建築物の脱炭素化の促進を図ってまいりたいと考えています。","id":"exchange-115"},{"speaker":"西村委員","kind":"質問","question":"次に、先日お話を伺う機会がありまして、あと何年でいっぱいになってしまうのかというような話を伺う機会がありました。実績と資源回収の状況、また実際に燃やすごみが減少しているのかどうか伺います。","respondent":"篠田品川区清掃事務所長","answer":"製品プラスチックの回収は今年度から本格実施、令和５年度にモデル実施をしたという経緯があります。三％ずつ減ってきているという状況がございまして、令和６年度におきましても、同じような形で減る見込みです。","id":"exchange-116"},{"speaker":"西村委員","kind":"意見","question":"原材料の高騰などを理由に、資源物専用ごみ袋を値上げした結果、価格が今の３倍近くになったというものでした。各自治体でこういうふうに広がっている、ごみ袋の有料化に関しまして、区はどのようにお考えか、説明を求めました。","respondent":"篠田品川区清掃事務所長","answer":"一般的には広く認識されているところではあるのですけれども、まず有料化に入る前にやるべきことがあるだろうと考えております。もまだ何らかしていかなければいけないといったときには、そういったことも考えていく必要があるのかなと捉えているところです。","id":"exchange-117"},{"speaker":"西村委員","kind":"提案","question":"やはり先ほどいろいろご提案させていただいたような、脱炭素とごみ減量への区民の皆様への理解促進がますます必要であるだろうと思います。最後に、資源化率の目標を掲げていただいていると思うのですが、こちらの現状を伺えればと思いますとの意見を述べました。","respondent":"篠田品川区清掃事務所長","answer":"私どもでは、第４次一般廃棄物処理基本計画の中で、最終的には令和１４年度を目指して、３５％という資源化率を目標値として持っているところです。おおむね、このままの推移で進めば、その数字も達成できる可能性は十分あるのではないかと捉えているところです。","id":"exchange-118"},{"speaker":"若林委員","kind":"質問","question":"スクリーニングを３００人のお子さんにされるということですけれども、このスクリーニングというのはどのようなものでしょうか。その後、６０人程度を対象に健診を受けてもらうということですが、３００人から６０人になる抽出というか、内容はどのようなものか尋ねました。","respondent":"石橋品川保健センター所長","answer":"１人でいるときに１人で遊ぶことが多い、保護者の方に答えていただくのと、スクリーニングの手法という形になります。予診を行いまして、医師に診察を行っていただいて、個別相談で心理職等の専門職をお願いしたいと考えております。","id":"exchange-119"},{"speaker":"若林委員","kind":"質問","question":"いわゆる５歳児健診のシステムが１つ、次々年度が本格実施へということで、様々検証しながらということだと思います。この５歳児健診システムを、どのようにこのシステムを活用してもらいたいのか、お考えをお聞きします。","respondent":"石橋品川保健センター所長","answer":"まだ具体的なところは決まっておりませんが、例えば教育部門でしたら、就学相談の前に実施するので就学相談につなげていく。就学までの１年前に実施する関係もありますので、その１年間、保育にどう反映させていくかというところも含めまして検討していきたいと。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"今、３部門で連携を密に取っているというところで、大変心強いお話を伺いました。この３部門の関係性をつくるに当たって、この連携体制を構築するためにさらに必要なことは、何を考えていらっしゃるかお聞きします。","respondent":"石橋品川保健センター所長","answer":"健診の対象者を６０人という形で、モデル実施のときは選定する形にはなりますが、やはり不安に感じるご家庭はあると思います。先ほども少し説明をさせていただきましたが、保健センターからどういう情報が必要なのかというところも、具体的なお話をしている最中にはなります。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"この１年間、しっかりこの５歳児健診のモデル実施を完成させて、３部門の連携のまさに強化を具体化させていただきたい。教育部門にも福祉部門にも保健部門からしっかりお伝えしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"ダブっている事業が多いので、もう少し整理できないのでしょうかという観点でお聞きしたいと思いますが、決算特別委員会のときにも質問しました。この違いは何ですかということです。","respondent":"石橋品川保健センター所長、中西環境課長、小林地域産業振興課長","answer":"本事業は、保育園に通っているからという理由で、特に見守りおむつ定期便が利用できないという形は取っておりません。… 今年度に関しましては４回、ワークショップやグループワークを行いまして、様々、環境に関する取組を深めておったところです。今後… 市場の動向・現場の実態に耳を傾けながら、円滑かつ持続可能な発注・供給が図れる方策を検討してまいります」という答弁がなされたところです。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"質問にきちんと答えてほしいと思うのですけれども、見守りおむつ定期便ですけれども、これはやはりダブっていると思うのです。契約なし」といって、それで不満がないところはないし、だから地域産業としてどうなのですかと。","respondent":"石橋品川保健センター所長","answer":"本事業は育児用品のみのお渡しということは一切考えておりません。重複というわけではありませんが、今後、別の事業として実施するべきこととして認識しております。","id":"exchange-124"},{"speaker":"せお委員","kind":"確認","question":"時間がありましたら２９９ページ、３０１ページ、ＮＩＣＵから退院して在宅になるというところの支援のところをお聞きします。令和７年度の予算書にも、令和７年度は変わらず実施していく方向でよいのか、確認だけさせてください。","respondent":"若生健康課長","answer":"国では、そういった考え方にも基づきまして委員会で議論を重ねてまいりまして、今回こういった目標値を立てたです。令和７年度に関しては実施の方向で、今、予算計上しています。","id":"exchange-125"},{"speaker":"せお委員","kind":"質問・要望","question":"ＱＯＬの維持・向上に資する施策の強化を、廃止と引換えに用意できるように、令和７年度に検討に入ってもらいたいと要望いたします。リハビリに特化した病院２か所にお話を伺ったのですけれども、予防などにも特化した事業に取り組んでいらっしゃる医療従事者の皆さんでした。","respondent":"若生健康課長","answer":"区民が適切な行動を選択できるような情報提供というのを充実していくといったことも、並行して検討していくべきだと考えております。がん相談支援センターが、マギーズ東京との連携なども図りながら、そういった支援機関につなげる取組をさらに推進してまいります。","id":"exchange-126"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけ。病院から地域への連携というか、在宅への連携のところ、今どのように取り組んでいるかだけ説明を求めました。","respondent":"福地大井保健センター所長","answer":"保健センターでは、病院から未熟児や医療的ケア児のお子さんについて、地区の担当の保健師に連絡が来ます。そうしましたら、地区の担当の保健師が、ご家族や医療機関に状況を聞きに行ってケアします。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"３２１ページのスタートアップ推進事業について伺います。どれぐらいの割合で推移しているか、お尋ねします。","respondent":"小林地域産業振興課長","answer":"産業経済費ですけれども、今年度、約３７億円の予算を計上しています。ここ５年ぐらい、平均してですけれども２％前後というのが１つの目安だと考えておりまして、比較的近隣区でもこれに近い数字だと認識しています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"その第２の円が品川区なのですが、もっと力を入れてもよいのでしょうか。いや、入れるべきではないかということで、お伺いします。","respondent":"小林地域産業振興課長","answer":"３点目としまして、商店街支援の関係ですけれども、予算の変動があるというものもあります。こういった中で、景気の変動も見ながら、予算については適切な金額を算出していくということが必要であると考えております。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"お尋ねします。それから、これらのスタートアップ支援は、区内産業全体の振興にどのようなメリットをもたらすのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"一方、例えば、まちのラーメン屋や塾といったところは、着実に持続可能な成長を目指す企業と認識しています。２点目は、金融機関など、いろいろな支援者が集まって相互に成長していくというようなところを考えているところです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"意気込みを伺ったのですが、それはいいです。意気込みがあって、こんなにすばらしい事業性がある事業なのに、なぜ予算の査定で削減したのか、お伺いします。","respondent":"加島財政課長","answer":"産業経済費に関する査定の理由・過程というところですけれども、査定の詳細につきましては明かすことができませんけれども、編成過程の公表をさせていただいている中で、主な増減理由のところに理由を記載させていただいているところになります。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、所管課はそれで納得しているのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区の予算編成につきましては、区政全体のバランスを見ての結果と捉えておりますので、結果として編成された内容の中で、来年度、少しでも成果を上げていく努力をしてまいりたいと考えているところです。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"所管課の意気込みややる気、そして、それを活かす予算編成査定が求められます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"３０５ページ、食品衛生、３２５ページ、展示会出展支援について伺います。食品衛生法施行条例第３条に根拠があるのですが、私はなかなか見つけられなくて、臨時出店の届出の法律上または条例上の根拠は何なのか伺います。","respondent":"赤木生活衛生課長","answer":"ただいま頂きました、行事等における臨時出店における法的な根拠というところのご質問ですけれども、根拠としましては、先ほど委員におっしゃっていただきました、「品川区行事における臨時営業等の取扱要綱」において規定されているものと認識しています。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"実際の対話は私も直接伺っていないので分からないのですけれども、よりよい区というふうに考えていくというのは、大事な考え方なのだろうと思います。任意のグループや、公共的目的を有する行事と判断される場合があるというふうに読めるのですが、その理解でよろしいか尋ねました。","respondent":"赤木生活衛生課長","answer":"臨時出店における個人の方や、町会・自治会等以外の方がやられたところの部分についての公共性の判断に関するご質問にお答えします。は地域の実情を踏まえて保健所で判断するというところとしていますので、こちらは個別具体の部分でご相談という形になろうかと思います。","id":"exchange-135"},{"speaker":"松本委員","kind":"質問","question":"地域の実情というのは、具体的にはどういう内容といいますか、どういうことを考慮されるのでしょうか。分かる範囲でお願いします。","respondent":"赤木生活衛生課長","answer":"地域の実情という部分をどのような形で判断するのかというご質問についてお答えします。そういった部分について個別具体に、こちらとしては事情を確認させていただいた上で、判断させていただいているです。","id":"exchange-136"},{"speaker":"松本委員","kind":"確認","question":"要綱を確認すると、印象としてばっさり切られてしまったというところは、できるだけ丁寧なご対応をお願いできればと思います。その辺りはどういうご事情なのか尋ねました。","respondent":"小林地域産業振興課長","answer":"我々としては、その会社のブランド力の向上などといったところのプラスの取組ということで支援をしています。助成制度の説明会などを通じて、こういうＰＲをやりながら、販路拡大というところの応援をしていきたいと考えています。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問","question":"この展示会の出展ですが、東京都でも類似の政策があるかと思うのですが、こことの違いはどこにあるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"あるいは公社のプロジェクトの支援というか認定を受けるということで、手続的に、やや都のほうが時間がかかるのかなと。支援のスピードというのは速いのかなということで、両方見せていきながら、販路拡大の支援をやっていきたいと考えています。","id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"ただ一方で、１点、見ていて思ったのが、これは申請の期間が、１０月１日から１０月３１日までの１か月間だけなのです。ここは、ほかの自治体を見ていると、通年でやっているところもありますので、そこは改善をお願いしたいのですが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"実際には半年前ぐらいからいろいろご相談も頂いていて、１０月の申請というときにも、春ぐらいにはいろいろお話も頂いているところです。我々は年間を通して応援していくというところは変わりませんので、今後もいろいろ考えていきたいと考えています。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"１年以内に倒産する確率の高い企業は、品川区内や東京都内では何社ぐらいあるのでしょうか。これは分かるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"２００８年頃に比べると半分以下というような形ではありますので、推移というのは、我々も引き続きしっかり見ていきたいと考えています。そういう中で、今、厳しい状況にあるのではないかと考えているところです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういう状況なら、区から国や都へ緊急支援を要請するべきだと私は思うのですが、どうなのでしょうか。そういう実情の中で、今の支援ということをどのようにお考えか尋ねました。","respondent":"小林地域産業振興課長","answer":"で今回の令和７年度の予算の中では、チャレンジ支援資金という、少しでもチャンスをつかんでいただくです。先ほどの展示出展もそうですけれども、そういったところも支援する中で、よりよい支援といいますか。","id":"exchange-141"},{"speaker":"須貝委員","kind":"意見","question":"もう待っているのではなくて、こちらから進んでいってほしいと私は思います。ご見解を説明を求めました。","respondent":"小林地域産業振興課長","answer":"まさに経済の４つの大きな要素を占めていると考えています。区の取組ですし、令和７年度にそういう取組も入れている中で、引き続き事業者の声をきちんと聞きながら対応していきたいと考えています。","id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、３０９ページのがん検診について伺いたいと思います。医療費はがん等が増えて２３区で２位ということで、大きく変化はないのかなと思うのですけれども、受診率の現状を伺いたいと思います。","respondent":"若生健康課長","answer":"がん検診の受診率の現状です。大腸がんは２０％、乳がんが３０.４％、子宮がんが３２.２％という結果になってあります。","id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問","question":"この受診率というのは、高いのか、上がっているのか。死亡を減らすために、がん対策推進計画というのも立てていると思うのですけれども、この検診率というのを区はどう見ているのか伺います。","respondent":"若生健康課長","answer":"受診率につきましては、がん種別によりますけれども、胃がん、肺がん、乳がん、子宮がんについては年々上昇しているところでございまして、大腸がんについては横ばいというところで、課題と感じております。","id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問","question":"がん検診を受診しなかった理由の５番目には、費用がかかるというのがあるのです。早期発見されることは大変大事なことだと思いますし、さらに無料にすることで早期発見につながると思いますけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"無料のがんとして実施しております、一定程度、これは検証が必要かなというところも考えております。そちらをしっかり進めていくとともに、がん検診の全体の在り方を検討する中で、今後考えてまいりたいと考えています。","id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので昨年も、４,０００万円程度の負担で無料化できると、区もお答えいただいているのです。ですので、区が行った調査を見ても、啓発と無料化で改善できると思うのですけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"そういった認識をしているというところで、区としても進めていかなければいけないということで、こちらをやはり重く受け止めているところです。指針外のがん検診を見直していくとともに、費用についての在り方というところも、総合的に検討していきたいと考えております。","id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問","question":"無料がどうか、議論があるとおっしゃっていましたけれども、改善させていくという考え、検討はあったのでしょうか。伺います。","respondent":"若生健康課長","answer":"今年度実施しているがん対策推進計画の策定委員会の中でも、無料化についての議論がございました。これは、全体として、無償化も含めまして、総合的に検討してまいります。","id":"exchange-147"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認で少し分からないところがあったので教えていただきたいのですが、買ったら買ったで全額、大手で使ってもいいのか。そういう使い方ができてしまうのかどうかというところを教えていただきたいのと、本人確認ができるようになったので、教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長、篠田品川区清掃事務所長、中西環境課長","answer":"券面を２つに分けて、例えば１対１もしくは２対１というふうに分けて、ひとつ検討しています。２点目、住所が分かるものをアップロードしていただいて… 粗大ごみの特に申込み等についての中身について、クレジット決済が、特にインターネット申込みの部分では非常に多くを占めているところです。… 区有施設部分で、どういった形で、それから波及効果のある形で導入していくといったことを引き続き検討してまいりたいと考えているところです。","id":"exchange-148"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういったところの対応があれば教えていただきたいのと、これは、こうしたデータの活用をどのように考えているのかということを教えてください。８月には申込み開始、購入の期間があって、その辺も併せて一緒にスケジュール等を教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長、篠田品川区清掃事務所長","answer":"事業者選定が、一応、今年度中にプロポーザルを実施しまして、決定を取るところを予定しています。６月中旬ぐらいに専用のホームページを立ち上げる予定ですので、８月から申込みを開始して、秋からの運用開始というような。コールセンターの受付で対応しても、そういったものについては柔軟に随時、追加していきたいと考えます。","id":"exchange-149"},{"speaker":"藤原委員","kind":"確認","question":"デジタル商品券、私も期待しているのですけれども、１点確認します。今年度中というのは、もうあと２週間ぐらいしかないのですけれども、この短い期間の中でできるのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"現在としましては、申込みをした業者に対して説明会を行って、具体的な提案書を提出していただくところの段階です。１次審査、２次審査、きっちり公平・公正に実施していくところです。","id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特に宿泊型について、具体的な課題をお示ししながら拡充を求めておりましたので、抜本的にどのように拡充されたのか確認してまいりたいと思います。１点目は、宿泊日数と分割利用について伺います。","respondent":"石橋品川保健センター所長","answer":"例えば１泊２日であれば３回利用できる、２泊３日と３泊４日など、分割して最大７日間までの利用ができるようになります。自己負担額も軽減させていただきまして、宿泊施設の利用料の１割負担という形で軽減しています。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問","question":"宿泊料についても１割負担と。そこについてある程度伺いたいのですけれども、一番高額な自己負担額、そして契約している医療機関の平均の自己負担額を説明を求めました。","respondent":"石橋品川保健センター所長","answer":"１泊２日で一番安価な料金で３,８００円、一番高額といいますか、一番利用料が高いというところで７,０００円という形になります。大体、平均値が５,０００円前後というところで認識しているところになります。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"確認","question":"宿泊型の手続の簡便化についても伺いました。しかし、昨年の決算特別委員会で確認しましたところ、電子申請をしてから。","respondent":"石橋品川保健センター所長","answer":"二週間程度の時間を頂いていましたので、すぐに申込み利用の予約ができないということがありまして、そこを課題として捉えておりました。そこに関しましては、余計なものは持っていっていただく必要がなくなるよう、母子手帳だけで管理ができるように手続を進めしています。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"確認","question":"そして、手続についても劇的に簡便化されたということを確認しました。次に訪問型産後ケアについて、区民のご意見を基に伺ってまいります。","respondent":"石橋品川保健センター所長","answer":"そこで、どうしても利用したい日にちに利用できないという声も上がってきたという現状があります。そこで、次年度より事業者を１事業者、追加することを決定して、手続を今進めしています。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"提案","question":"これは、やはり他区のように、利用者に複数の選択肢をご用意していただきたいというのが今回のご提案です。まだ始まっていない事業ですから、ぜひこれからご検討いただきたいと思うのですが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"継続して同じ方で利用できるということは、安心して利用できることにつながるということのご意見を頂いたところになります。合わせて２事業者の連携をしっかり図りつつ、どのように進めていくかということもしっかりと検討してまいりたいと考えております。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"２点目に関連するので、進んでいるのか、教えてくださいというのが１点目です。必ず首都直下地震が発生するとは言われているところで、搬送の仕組みについて、現段階でどのように考えておられるのか説明を求めました。","respondent":"遠藤健康推進部次長、羽鳥防災体制整備担当課長","answer":"こちらは、東京都の災害時の医療救護活動ガイドライン、あるいは品川区の地域防災計画に基づいて行動するような形になっているところがあります。というところで、この辺ですと東京品川病院に… 委員がおっしゃられたとおり、３,０００名の帰宅困難者を受け入れる一時滞在施設としてご協力いただくように話を進めております。具体的には、来年度の夏頃から協定締結に向けた話をするという予定です。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"防衛省の医官ですから、やはりこの周辺の災害医療計画というものをこれからしっかりと立てていく必要があるのではないかと私は考えております。ただ、実際問題、都の計画に沿ってやるということでは間に合わないと思いますので、ぜひ計画を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"まつざわ委員","kind":"質問","question":"３２３ページ、随分質問が出ましたけれども、支援についてお聞きします。そこでお伺いいたします。","respondent":"小林地域産業振興課長","answer":"チャレンジ支援資金ということで、品川産業支援交流施設で商談会というのをやりまして、企業間マッチングというのも定期的にやっているところです。","id":"exchange-158"},{"speaker":"まつざわ委員","kind":"質問","question":"融資やチャレンジ、それと商談会のマッチングですか。今年で１０年目を迎えますが、改めてＳＨＩＰや品川ビジネスクラブによるスタートアップ支援の取組や成果について説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"約２００名程度の会員がいらっしゃいまして、年間大体４０回ぐらいのセミナー、それから２回の大規模交流会などを実施しています。ＳＨＩＰは開設して１０年たっていますので、小規模企業の方もいらっしゃいますので、本当に様々なご相談を日々承って支援をしています。","id":"exchange-159"},{"speaker":"まつざわ委員","kind":"質問","question":"今、高橋しんじ委員の質問がありまして、３つの大きな目的・意義があります。この事業にどういうふうに関わっていくのか、説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今年度もエコシステムの事業を、ＳＨＩＰを含め、全８回実施しまして、１３１回の商談や３件の具体的な成果を創出しています。そういったところをビジネスクラブと連携してやっていくというふうに考えているところです。","id":"exchange-160"},{"speaker":"まつざわ委員","kind":"意見","question":"１人の起業家の成長や発展にとどまらず、地域や社会を変える起爆剤になり得ると期待しています。こうした中から、ＳＨＩＰや品川ビジネスクラブというのはどのような支援を行っているのか、説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"こちらは、起業したばかりの方、今年度につきましては２７７名からの応募がございました。そういったところを、今後は区や、いろいろなところに、事業化につなげていけるような支援をやっていくところです。","id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問","question":"引き続き積極的な取組を期待しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/552633?Template=document&Id=7009#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":129505,"voices":367}},{"id":"r07-20250313-3","meetingId":"r07-c-budget","date":"2025年3月13日","dateIso":"2025-03-13","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時２１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"様々な交通サービスの状況を踏まえて、試行運行の延長を含め検討していただきたいと要望していましたので、歓迎いたします。交通サービス圏域外とされた残りの２地区、私の一般質問でも伺い確認しましたが、一定の取り組みが進んでいると認識しております。","respondent":"櫻木地域交通政策課長","answer":"コミュニティバスの運行に伴う既存交通への影響等の課題が見えてくるなど、計画策定時とは様々状況が異なってきていると認識しております。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問・要望","question":"寄附額の１,４２３万円、会派からも要望しておりましたが、寄附してくださいました地元の企業や区民の皆様方に心より感謝を申し上げます。区のご見解をお伺いします。","respondent":"羽鳥防災体制整備担当課長","answer":"トイレトラックを通じて区の防災の取り組みについて、啓発できる機会をいただけるということは非常に有効であるというふうに考えてあります。そういった費用をなるべく区民の負担にならないように、今後、検討してまいります。","id":"exchange-002"},{"speaker":"えのした委員","kind":"提案","question":"続いて、時間があれば、防災区民組織活動助成金についてお伺いします。今回、名称が「資機材整備」から「活動支援」に変更しておりますが、どのような背景があるのでしょうか、お知らせくださいとの意見を述べました。","respondent":"平原防災課長","answer":"防災資機材整備助成金は、平成２９年から８年間行われてまいりました。今後は災害時の共助の中核となります防災区民組織が、その活動に目を向けて、より積極的に活動できるように支援の対象を拡大したところです。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"３５５ページ、３５７ページ、公衆便所費から八潮多目的広場についてお伺いいたします。浜川ポンプ場解体工事完了時期と、同じく今後の動向や跡地の所有についてお伺いいたします。","respondent":"森道路課長、大友公園課長、北原河川下水道課長","answer":"私からは、（仮称）勝島人道橋の整備時期についてお答えいたします。現時点では、令和１０年１月、令和９年度の後半に設置を完了したいというふうに考えて… 私からは、しながわ花海道および新浜川公園のスケジュールについてご説明します。令和６年度から設計に着手しているところでございまして、新浜川公園と同… 下水道局で実施している事業であるため、浜川ポンプ場解体工事につきましては令和１１年度頃の完成を目指して、工事を進めていると聞いております。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"区に具体的な桟橋の対応についてお伺いいたしましたが、何か具体的な進展がありましたら、お知らせほしいと求めました。２０１６年の決算特別委員会から重ねて、設置されている公衆便所が適地に移設されるのかということをお伺いしたいと思います。","respondent":"北原河川下水道課長、大友公園課長","answer":"令和７年度予算では、勝島運河で地域が水辺に親しむイベント等を継続できる環境を整えるという目的で、そちらの小型桟橋の補修を支援する費用を計上することといたしました。 新浜川公園のトイレの位置につきましてですが、現在のトイレは、浜川砲台の北側に位置しています。来年度実施する設計におきまして、設置する位置も含めまして、地域の声を踏まえて検討してまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"確認","question":"先ほど、勝島運河周辺で行われているそれぞれの工事の状況を確認いたしましたが、３月５日の歳入の款別質疑で。勝島運河周辺の工事と合わせた一帯の整備が必要かと思いますが、利活用に関しての検討スケジュール、関連でお伺いします。","respondent":"高梨都市計画課長、吉岡政策推進担当課長","answer":"まちづくりの方針として、花海道を生かした回遊性の確保、取り組みの方向性等を示しています。地区内の各施設等の状況は、地域の皆さんの意見を伺いながら各種施策を行ってまいりたい、このように考えているところです。 なぎさ会館の廃止を検討することとして今後進めていくところですが、検討に当たりましては、活用に向けて検討を進めてまいりたいと考えております。","id":"exchange-006"},{"speaker":"新妻委員","kind":"確認","question":"管理者は教育委員会でありますけれども、この公衆便所は公園課になるかと思いますので、お伺いいたします。災害時には、災害時も活用ができるようなトイレの整備が必要かと考えますが、区のお考えをお伺いいたします。","respondent":"大友公園課長","answer":"開設から一定年数が経過していて施設の老朽化が進んでいるというところで、大規模改修の時期も近づいているというところも認識しております。このような公園の改修時期を機に、利用状況などを踏まえて、改めて検討してまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"具体的なご答弁をいただきまして、ありがとうございました。計画を立てて改善されるように取り組みをお願いして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問","question":"３５３ページ、３６９ページ、順不同でお伺いいたします。避難支援に当たる防災区民組織に対し、個別避難計画の記載のうち、どのような部分を公開するのか、現在、検討している状況について説明を求めました。","respondent":"平原防災課長","answer":"現在検討しているのは、防災課が各地域に対しまして避難行動要支援者の名簿を提供しておりますが、その名簿の中に。具体的な項目につきましては、個別避難計画の作成がまだ進行中ですので、その状況と合わせながら検討をさらに深めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"ひがし委員","kind":"意見","question":"全部がそろってから始めるというお考えなのか、もう作成が済んだ方々からどんどんと記載をして、その点についてもお聞かせください。福祉的な対応が難しいといったようなお声が聞かれておりますが、その点について、区の進捗も説明を求めました。","respondent":"平原防災課長","answer":"ご説明ですけれども、そういったところの状況もご説明させていただきながら、丁寧にご説明させていただければと考えています。避難支援に実際に当たる方ですけれども、あるいは介助者がそもそもいない、様々な問題は我々でも認識しています。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"町会の方々にも早い段階で協力を仰いでいく必要があるかなというふうに思いますので、その点はしっかりと進めていただきたいと考えています。車椅子の階段のおろし方だったりとか、介助の仕方はこうだよという視点もすごく取り入れられていて、その点についての区の見解を説明を求めました。","respondent":"平原防災課長","answer":"避難行動要支援者の支援に当たりましては、実際に、この人たちだけというようなものでは対応が非常に難しいところがあります。現在、区でもしっかりとそのような動きを踏まえまして、福祉部局と防災所管課で連携して進めてまいりたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"ひがし委員","kind":"提案","question":"子どもたちのアイデアを活用した公園づくりについて、私は子どもたちの声をしっかりと聞いてくださいというふうに提案しておりましたので。品川区内に子どもたちのアイデアを活かした公園が幾つあるのかということを説明を求めました。","respondent":"大友公園課長","answer":"子どもたちのアイデアを活かした公園づくりといたしましては、平成２０年度よりこの取り組みが始まった以降で申しますと、平成２２年度の鮫洲運動公園から令和６年度の西五反田公園まで９公園で実施をしております。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"確認","question":"今、９公園進んでいるということで確認いたしました。子どもの声をどのように反映していくのか、また、どうやって声を聞いていくのかという点についても説明を求めました。","respondent":"大友公園課長","answer":"実施した中でお話ししますと、そちらの小学３年生を対象にワークショップを実施し、そこでいただいたアイデアを反映して設計しています。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問・要望","question":"自分たちが使う公園を自分たちで決められるということは、すごくいいのかなというふうに思っております。効果検証として、子どもがたくさんいるねとか、そういう効果検証はどのようにされているのかという点を最後に説明を求めました。","respondent":"大友公園課長","answer":"大人では考えつかないアイデアを活かした改修ができているというところで考えてあります。子どもたちのアイデアを活かした公園として整備した鮫洲運動公園やしながわ区民公園の中央ゾーンなどは、区内でも人気の公園となっているところです。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"子どもたちのアイデアを活かしたことで、大人だと発想がない部分で取り入れることができたということで確認いたしました。障害がある子どもたちだったりとかという声をというところのご要望もあったみたいですけれども、そのような公園を検討していく可能性があるのか。","respondent":"大友公園課長","answer":"インクルーシブの公園というところで、区内で申しますと、まず代表的なところでいくと大井坂下公園があるかと思います。現在も進めているところでいきますと、東大井の公園についてもインクルーシブの視点での整備というところで進めているところです。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"今、進めているところについては、障害がある方とか、お子様とか、ご家族の声を取り入れたようなインクルーシブ公園になるということで認識は合っていますか尋ねました。","respondent":"大友公園課長","answer":"そのとおりです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"令和５年度の区民要望件数が、そもそも前回の９６６件から１,２９５件と上がっているので、件数は増えているのかなというふうに思っております。この令和５年度に区民要望の件数が増えた理由を、区としてどのように分析をしていますか尋ねました。","respondent":"森道路課長","answer":"令和５年度につきましては、だんだんとコロナの行動制限が解除されてきた頃かなというふうに考えております。その分、しなみちレポートによる陳情件数は１９６件から２５２件というふうに増えておりまして、着実に広がっているというふうに考えております。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"少し直してほしいなとか、そういうご要望があったときに、一緒に登録をするというようなこともしています。ぜひ進めていただきたいなというふうに思いますし、進捗が分かるというのは、職員の方々の負担はどうなっているのかというところも伺います。","respondent":"森道路課長","answer":"７割以上の方が、休日であるとか、区の閉庁時間帯に投稿していただいております。そのときそのとき、自分の都合のいいときに情報をいただけるということは、それぞれにとってメリットかなというふうに思っているところです。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１つ心配なのが、なかなか新しくいいものがあっても伝わらないというところがネックなのかなというふうに思っております。区民要望についても、やはり１,０００件以上は電話でのご相談が来ているということなので、その点説明を求めました。","respondent":"森道路課長","answer":"様々周知についてご提案をいただきました。それぞれの所管と話をしながら、どういった周知方法が適切かということをしっかり検討していきたいというふうに考えております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"３４８ページ、都市開発費、武蔵小山駅周辺地区再開発事業、３４９ページ、五反田駅周辺地区コーディネート業務委託で伺います。これ、何の方針を定めることを目指しているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"五反田駅周辺地区コーディネートの中で東口の検討時期ですが、令和元年から進めているところです。区としましても、そういった意見から方針を取りまとめるというような予定でいたところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"事実を確認させていただきたいのですが、それぞれについて伺いたいのですけれども、今時点で本組合設立認可申請は出されたのか伺います。併せて、現在予定されている事業費と、補助金額を、両地区それぞれ伺いたいと思います。","respondent":"中道都市開発課長","answer":"まだ検討中で変更も可能性もあるということはお聞きした上で、公表しても構わないという承諾をいただきましたので、ご報告いたしたいと思います。小山三丁目第１地区の総事業費は９６３億円、三丁目第２地区の総事業費は１,０７６億円を予定しているというふうに聞いております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"確認","question":"伺いたいのですけれども、既存の２地区と比べ、なぜこれだけ補助金が上がっているのか伺います。これは事業費が上がっているということだと思うのですけれども、事業費が上がれば、税金投入も増えるということになるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"補助金の考え方、総事業費の考え方等につきましてですが、まず、パルム駅前地区ですけれども、再開発の区域が９,０００m2です。３－１、２階の部分にもデッキを造って回遊できるような形を検討しているなど、そうしたことも総事業費につきましては加味をしています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の定例会に、「私はどうしていいかわかりません品川区長森澤恭子さんに小山三丁目第一地区・第二地区再開発中止を求める陳情」を出されました。伺いたいと思います。","respondent":"中道都市開発課長","answer":"こういった再開発を含めたまちづくりというのは、非常に時間のかかる事業となっています。そうした中で、様々なご意見または不安な声、区のほうにもいただきますので、そうした声に丁寧に対応するよう指導してまいります。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"水辺利活用事業についてお伺いいたしますけれど、先ほど、非動力船のための船着場の増設をしてほしいというご要望を受けました。ぜひ非動力船のための船着場の増設、どんどん増やしていっていただきたいと思うのですけれども、その点、区としてはいかがお考えか尋ねました。","respondent":"北原河川下水道課長","answer":"東品川海上公園の船着場が非動力船用の船着場として整備されておりまして、その他については、そういった活用が難しいような状況にはなってあります。その後、委員からご指摘あったようなことについても、必要に応じて検討してまいりたいと考えております。","id":"exchange-024"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。水は１つですので、どうやってそういうふうにうまく動力船と非動力船を分けるのか、現時点のお考えを説明を求めました。","respondent":"北原河川下水道課長","answer":"どういったことで危険なのかというご質問ですけれども、委員からお話がありましたように、引き波も１つの要因です。様々取り組んでおる状況でして、お互いに理解を深めるとともに、ルールをつくっていくという方向で現在進めております。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"やはり閉じ込められたら、相当パニックというか、焦ってしまうものなのでしょうか。ぜひ区長の率直な感想を簡潔にお伺いいたしたいと思います。","respondent":"森澤区長","answer":"やはり停電したりして暗くなったりですとか、あと、狭い場所ですので、やはり初めて経験するとパニックになってしまうということは感じるところでありますので、やはり訓練をすることの重要性は感じているところであります。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"やはりあまり閉じ込められるという経験をされる方は少ないと思うのですけれども、それを受けて、具体的に区としてはどういった対策をしていくのか伺いたいと思います。","respondent":"平原防災課長","answer":"令和６年度から、まずはそういったものの配布の中から、マンション側でどういった対策が必要かといったことを考えていただく。中に何が入っていて、あるいは非常ボタンがどこにつながるのか、そういったところの検証をやっていただくことが重要かなというふうに考えてあります。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"都民ファーストの会として要望させていただいて、むしろぜひ連動していっていただきたいと思うのですけれども、その辺りはいかがお考えか尋ねました。","respondent":"平原防災課長","answer":"一番対策のとれているところの１つの成果といたしましては、「東京とどまるマンション」への登録があるのではないかというふうに考えてあります。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"地域防災計画の予防－２３で書かれていますとおり、飛行機も飛べなくなる、呼吸器の疾患のおそれもある。応急－２７７ページで、現在そうした行政機関同士のシミュレーションというか、そうした準備や訓練などはやられているのか尋ねました。","respondent":"平原防災課長","answer":"委員のご指摘のとおり、国がまず溶岩量を含めた形の検討から始まりまして、降灰対策の検討に進んでいるところです。令和５年１２月に対策方針を出して、連絡体制という意味では、今の作業体系から実際のところの発災時の連絡体制に進めていくものと認識しています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"原則が在宅避難ということになりますので、普通の地震対策とか避難訓練とは少し異なっていくものかと思いますので、この辺りをどうされるのか。区民への周知と、独自の避難訓練の実施などを検討するべきだと思うのですけれども、その点、いかがお考えか尋ねました。","respondent":"平原防災課長","answer":"今、そういう対策を進めておりますので、在宅避難をするためには何を備えていかなければならないのか。しっかりと備蓄の考え方、各町会で説明させていただきましたが、そういったところも含めて検討してまいりたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、区民の方が自分でやるということは大変なケースもあるかと思いますので、降った後の対応ということもぜひお考えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"せらく委員","kind":"確認","question":"先ほども出ておりましたが、子供の森公園は、かつて品川区で初めて子どもたちの意見を取り入れた公園であることを確認しております。園庭代わりや散歩で利用する近隣の保育施設の数も分かれば説明を求めました。","respondent":"大友公園課長","answer":"公園利用者へのヒアリング調査、品川学園の小学３年生を対象にしたワークショップを実施して、これらにいただいた意見を反映して設計をしています。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"近隣の保育園は２園程度あるということで、試合だとか、そういうところで家族連れでいらっしゃる方も多いのではないかと感じています。続いてお聞きしていくのですけれども、あと楽しいものにしてほしいなどお話を聞いたりするのですけれども、ご意見は把握していますか尋ねました。","respondent":"大友公園課長","answer":"遊具の選定の考えですけれども、公園近隣にお住まいの方や利用者へのアンケート調査などを実施し、意見を聴取しております。遊具につきましては、このアンケート調査などに基づきまして、利用状況や対象年齢を考慮した上で選定しています。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"区として、公園のリスクとベネフィットのバランスはどう考えていらっしゃいますでしょうか。子どもたちにとって、公園はどのような場所であると、心身の発達や成長に有益なものになると考えていますか。","respondent":"大友公園課長","answer":"保護者など、地域の理解を踏まえた上で選定するということで、合意形成にはなかなかハードルがあるという認識です。設置を検討しているところはあるかと思いますけれども、設置につきましては、なかなか難しいところと考えているところです。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"ただ、バランスが難しいかと思いますが、子どもたちの挑戦を応援できるような公園にしていただきたいというふうに思っております。ほかの管理人のいない公園と比べると、そういったところのお考えを説明を求めました。","respondent":"大友公園課長","answer":"今の動きの中で、プレイワーカーというのですか、そういうものを配置するというところで整備をしているという公園も見受けられます。様々そういうような状況等々を注視して情報収集したいと考えています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"次に、公園遊具の定期点検についてお聞きしたいのですけれども、頻度や、どのような業者が行うか教えてください。リスクを低減しつつ、子どもにとってのベネフィットを最大限に活かす対策をしてほしいと求めましたが、教えてほしいと求めました。","respondent":"大友公園課長","answer":"それに伴って評価をさせていただきまして、その安全状況等を確認しています。その中には、老朽化であったり、現状の規格に合っているなど、様々な点検項目を設けて点検しています。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"点検は専門業者が行っているのでしょうか。その点も説明を求めました。","respondent":"大友公園課長","answer":"遊具の点検につきましては、公園遊具等の知識のある専門業者で点検をしています。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"引き続き、安全面の確保と、子どもたちにとって有益になるような公園の整備に向けて、区としても取り組んでほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"１点目に、防災関係組織経費についてお伺いいたします。ケアが必要な方々のご家族や避難支援等関係者が、個別避難計画について、現状どのくらい把握されていると区はお考えか尋ねました。","respondent":"平原防災課長","answer":"個別避難計画ですけれども、これにつきましては、ご本人やご家族など介助に当たる方のご理解のもとに作成が進められているものと認識しています。","id":"exchange-039"},{"speaker":"横山委員","kind":"確認","question":"やさしいまちづくり整備費についてお伺いいたします。目黒駅の工事の進捗状況について確認させてください。","respondent":"平原防災課長、櫻木地域交通政策課長、高梨都市計画課長","answer":"しながわ防災学校の１つのコースといたしまして、子育て中にどのようなリスクがあるのか、こちらは毎年実施しています。それに対しての備えみたいなところ… ＪＲ目黒駅のエレベーターですが、令和６年度から工事着手しておりまして、今年の秋頃の完成を見込んでいるとＪＲからは報告を受けております。令和５年３月より、東急新横浜線との相互直通運転を実施するなど、利便性が向上している状況かと考えています。","id":"exchange-040"},{"speaker":"横山委員","kind":"確認","question":"下水道管改修事業についてお伺いいたします。２０１７年の予算特別委員会でも確認させていただいたのですけれども、区が把握している最新の進捗状況を説明を求めました。","respondent":"高梨都市計画課長、北原河川下水道課長","answer":"行政と鉄道事業者との連携や情報共有が今後求められるアクションとしてまとめられているというふうに区としては理解をしています。区内各鉄道事業者との共有を引き続き密に行っていくとともに… 再構築を行う幹線として位置づけられておる全長約１０kmの幹線でございまして、令和５年度末現在では、約９００ｍが完了しているというふうに聞いております。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"１０kmのうち９００ｍが完成ということで、暗渠ですから、引き続き都への働きかけをよろしくお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"３５３ページ、公園・児童遊園設備費、３５７ページ、おもてなしトイレ整備でお伺いいたします。令和７年度、いよいよ工事が始まりますけれども、改修後にも子供の森公園での水遊び施設は設置されるのか尋ねました。","respondent":"大友公園課長","answer":"改修後におきましても、ミスト広場のような水を感じ遊べるような、また、涼を感じることができるような設備を整えたいと考えているところです。改修後においても、子どもからご高齢の方まで、多くの方から愛される公園となるよう努めてまいる所存です。","id":"exchange-043"},{"speaker":"澤田委員","kind":"意見","question":"そしてまた、愛される公園づくりということで、本当に幅広い年齢の方に親しんでいただけるものを引き続きつくっていただけるといいなと考えています。ほかの公園の水遊び施設も含めて、稼働状況と、その方法について説明を求めました。","respondent":"大友公園課長","answer":"この稼働状況ですけれども、公園施設によって異なりますが、７月から９月を中心に稼働させております。その方法につきましては、管理スタッフにより、稼動の開始時にシステムを設定しています。","id":"exchange-044"},{"speaker":"澤田委員","kind":"質問・要望","question":"７月以外でも、６月とか１０月でも３０度を超える暑い日が多々ありますので、水遊び施設の稼働時間の延長を望む声もお聞きしています。気候変動に合わせて、水遊び施設の稼働時期の柔軟な対応を要望いたしますが、区のご見解を説明を求めました。","respondent":"大友公園課長","answer":"水遊び施設の稼働時期ですけれども、梅雨時期や子どもの夏休みなどを考慮して決めているところです。５月でも３０度を超えるような日が観測されていることも踏まえ、来年度の稼働時期については検討してまいりたいと考えているところです。","id":"exchange-045"},{"speaker":"澤田委員","kind":"質問・要望","question":"こちらは要望として次に移ります。現在、区として、公園内のトイレの洋便器化を進めてくださっていますが、現在の状況を、示すよう求めました。","respondent":"大友公園課長","answer":"区が設置している公園・児童遊園トイレ、計１２９か所について、令和９年度の完了を目指して、年間１０か所程度、洋便器化を進めているところです。現在、１０５か所の洋便器化が完了しております。","id":"exchange-046"},{"speaker":"澤田委員","kind":"質問・要望","question":"区内の公園において、そのような幼児用補助便座を設置している公園はあるのでしょうか。子供の森公園のように改修する公園があれば、幼児用補助便座の設置もご検討いただきたいと考えますが、区のお考えを説明を求めました。","respondent":"大友公園課長","answer":"公園・児童遊園のトイレに幼児用の補助便座を設置している箇所におきましては、区民公園等でも設置しているところがありますが。トイレの利用者の利便性向上に向け、幼児用補助便座の設置については、今後も検討してまいりたいと考えているところです。","id":"exchange-047"},{"speaker":"澤田委員","kind":"質問","question":"小学校、未就学のお子さん向けのような小さなものに変わってしまい残念だというお声も、子どもたちや保護者の皆さんからお聞きすることがあります。区として、遊具についてどのようにお考えなのか、考え方や基準などがありましたら説明を求めました。","respondent":"大友公園課長","answer":"リニューアルに伴う交換の際には、同じ敷地であっても、取り替え前と同じ大きさの遊具が設置できないという場合が多くなっておりまして。そのような制限の中でも、子どもたちにより楽しんでもらえる遊具を工夫して整備してまいりたいと考えているところです。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"３５３ページ、３５９ページ、私道整備事業について伺っていきます。そこも少し当日も伺ったところではあったわけですけれども、そこはしっかりと先ほどの質疑のとおりかなというふうに私も思いました。","respondent":"羽鳥防災体制整備担当課長","answer":"今ご提案いただきました動画での使い方の説明など、その中で、どういったやり方が効果的か検討してまいりたいというふうに考えてあります。処理の方法も、ぜひ啓発したいですが、こちらも様々な訓練の場も含めて、今後、検討してまいりたいというふうに考えてあります。","id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"職員の提案で、いろいろあろうかと思いますけれども、この辺をやったらどうかなというふうに思っています。もう１つは、ぜひこのトイレトラックのトミカなどもいいのではないのかなと思うのですけれども、少しその辺のお考えを説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"白紙バージョンに関しましては、小さいお子様が自由に絵を書いていただけるような、そういった形で２枚セットという形でお配りさせていただきました。","id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"平和の名前を冠した公園をつくったらどうですかと提案したところ、６つというふうに言っていたのですが、５区なのです。もう１つは、それぞれの意義を確認したら、恒久平和を求める区民の願いを込めてとの意見を述べました。","respondent":"大友公園課長","answer":"公園名称につきましては、一度決めたら、未来永劫変更できるというところではございません。公園の新設や改修の際を機に、どのような公園にするのか、いただいた意見も踏まえて検討してまいりたいと考えているところです。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"屋外用のマイボトル給水機としては、２３区で見ると、新宿御苑に何か所か置かれているのです。屋外用のマイボトル給水機とか、この辺のことについて、公園課としての考え方を説明を求めました。","respondent":"大友公園課長","answer":"設置を進めているところのマイボトル用給水機については、屋外型のマイボトル用給水機の視点を新たに加えまして検討をさせていただければと思います。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"そういうことをやっていただいても、なかなか外でというのは、近年の夏は過ごしづらい部分があるわけであります。公園に行くと、そういった形で、そこでしっかりと涼を確保できるということの展開をぜひ公園課としても積極的に検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"最初に、羽田空港アクセス線新駅可能性地域まちづくり検討経費についてお伺いします。２０３１年度の開業を目指してＪＲ東日本が建設中ですが、品川区内の新駅の検討も含め、今どこまで進んでいるのかお聞きします。","respondent":"高梨都市計画課長","answer":"今、委員からご説明あったとおり、ＪＲ東日本によりアクセス線の工事が令和５年度より着手して進められているところです。候補地となり得る場所について、新駅が設置された場合におけるまちづくりの方向性や将来像などを検討したい、このように考えているところです。","id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区としては、特に駅を要望しているわけではないということでよろしいでしょうか。八潮の都市整備計画にも関わってくると思うのですが、決定権は国土交通省とＪＲ東日本にあると思いますが、品川区の希望等があれば説明を求めました。","respondent":"高梨都市計画課長","answer":"区で検討する中で、いろいろとＪＲ等々のお話を伺う機会もございました。沿線でどういったまちづくりが進められるかといったところを総合的に勘案して検討しながら、検討もしっかりと区として進めてまいりたい。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問・要望","question":"もし新駅ができるようになったとしますと、また区民の要望とか懸念なども出てくると思いますので、そういったことを取りまとめて。昨年７月より、一部の区営駐輪場を２時間無料にするという試行を行っておりますが、この実施により少し減ったのか尋ねました。","respondent":"山下交通安全担当課長","answer":"昨年７月から実施した短時間無料の試験試行実施に関しまして、若干でありますけれども減少の傾向にありました。なお、５駅８施設で実施したところなのですけれども、その周辺におきましては、全体で２４台の減少が見られました。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"場所によっては、そもそも自転車の駐輪場が足りていないのではないかなと思いますが、いかがでしょうか。見解をお聞きします。","respondent":"山下交通安全担当課長","answer":"こちらは北のほうにありますサイクルパークという駐輪場、民営になりますが、こちらのほうはまだまだ空きがある状況です。そういった対策等も行って利便性の向上に努めているところですので、その辺、よろしくお願いいたします。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"意見","question":"品川区内では共働き世帯が７１.２％となっており、朝、通勤や通学で駅に向かわれると思います。この自転車の問題以外にも、朝の通勤などの解消として、今検討されていることがあれば説明を求めました。","respondent":"山下交通安全担当課長、櫻木地域交通政策課長","answer":"特に時間差について検討ということはございませんが、夕方以降であったり、自転車の駐車場はまだまだ空いている時間等があります。この４月から、当日利用できる駐輪場に展開していく予定なのですけれども… 働き方の多様化ということで、通勤手段ということで、区では、シェアサイクルという形で、シェアリングエコノミーの一環として多様な交通手段も提供を進めているところです。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"通勤手段、自転車が今は結構多いのかなと考えていますが、シェアサイクルを含め、いろいろなものを検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"３５１ページ、そして３６５ページの区営住宅管理費に関わって、借上型区営住宅の実施について伺います。立ち退かされる地権者も、区から一度も説明を受けていないと言っているもとで進めるべきではないと、中止を求めますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"事業認可取得後の説明会の開催前でも対応できるよう準備を進めていくため、今回、予算を計上させていただいているところです。もう１点、説明会等でもいろいろなご意見をいただいたところですが、これからもしっかりと説明してまいりたいと考えているところです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"特に風の問題を伺いたいのですけれども、１９番地が建ったことによって風がとても強くなったということで、その道を通れない。この超高層によって住環境が悪化しているということを区は認識をしているのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"このような状況を踏まえまして、区では、再開発組合に対しまして、対応策の検討の実施について、今、話をしています。再開発組合からは、モニタリング調査や専門家のヒアリング等によりまして対応策を検討すると聞いているところです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"建った今は、ほかにも様々な問題がある中で、日程どおりに説明会を開催して計画を進めていくということはするべきではないと思います。５月頃ですか、進めるべきではないと思いますが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"都市計画手続の中でいただいたご意見につきましては、地域住民の声の一部であるということは区も認識しています。区といたしましては、その声に引き続き耳を傾けるとともに、１件１件真摯に対応してまいりたいと考えているところです。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"真摯に対応するということでしたら、これ、中止をするべきだと私は思いますけれども、まずは少なくとも一度立ち止まって、住民の皆さんと話し合いをする場を設けるべきだと思いますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"まちの将来像等につきまして検討事項をまとめた提案書が区へ提出され、計画を照らし合わせ、行政手続を進めているところです。説明会等では、地域住民に対し、引き続き丁寧に説明するよう指導してまいりたいと考えているところです。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"このように高い建物は戸越公園の町には必要ないという思いですので、中止をしていただきたいというふうに求めておきたいと思います。借上型公営住宅を実施していただきたいと思うのですけれども、実施に向けての課題や、区の予算がどれくらい必要なのか伺います。","respondent":"川原住宅課長","answer":"賃借人が末永くお住まいいただくための施策というところではすごく難しいのかなと思われます。実際に計上はしてございませんので申し上げることはできませんが、様々な使用料の徴収など債権管理業務なども発生するかと思います。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ有効期限はないようにしてほしいと求めましたが、切れた場合は、家賃補助で対応するなどしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"吉田委員","kind":"提案","question":"この目黒川の水をどうにかしてほしいというご意見があって、区民に対しても生活改善のいい提案になると思いますし、やはり表現が難しいのです。でも、東京都の下水道局のチラシも一緒にお渡ししていただけるといいと思うのですけれども、その点については今どうなっているか尋ねました。","respondent":"北原河川下水道課長","answer":"そういったものを見てもらうことで啓発につながるということで、私ども河川下水道課の前に置いて、取ってもらえるように掲示している状況にはなっています。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"これ合流改善事業であるとともに、環境問題の解決につながるので、なぜ河川下水道課だけに置いてあるのかなということが大変疑問です。それから戸籍住民課にも行かれると思いますので、そのようなところに置き場所を広げるということは考えられないのか伺いたいと思います。","respondent":"北原河川下水道課長","answer":"例えばホームページに東京都のリンクを貼ったり、ポスターも掲示したり、いろいろな取組はやってまいりました。確かに委員のご指摘のとおり、そのようなところもありますので、どこに置いたら適切かというところも今後検討してまいりたいと思います。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問","question":"エコルとごしに置くということは、これ本当に環境の活動につながると思うのです。その視点でエコルとごしに置いていただくということや、それから環境系のイベントなどに置いていただくことはいかがか尋ねました。","respondent":"中西環境課長","answer":"河川下水道課と連携をして、実際のものを置いて、エコルとごしに来所される方々にＰＲをするといったことはやってきているところです。どういった形でそういったものが周知できるかといったものは、河川下水道課と連携しながら前向きに検討してまいりたいと考えています。","id":"exchange-068"},{"speaker":"吉田委員","kind":"提案","question":"例えば、エコルとごしなどでは、そのような講座を区としてやるなど、そのようなことは難しいのでしょうか。展示の中では今までも私たちの提案を受け入れていただいて、１行か２行だったかもしれないですけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"説明した後に実際船で川を通ってもらって、下水道が出てくるか等を確認できるような、そのような河川環境学習というものを実施しております。今後もどういった形で啓発を図っていくことが効果的かということは、環境課とも連携して検討してまいりたいと思います。","id":"exchange-069"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、浄水器と併せて使えばなおいいかなと思います。そのように考えると、一緒に簡易浄水器のアピールもしてはどうかと思うのですけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"委員のご指摘のとおり、災害時の生活用水を含めた水の確保というものは非常に重要ですので、河川下水道課としっかり連携いたしまして、どのようにするか検討させていただければと思います。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つ安心にもつながりますし、そのようなことも１つのアピールになるかなと思いますので、ぜひご検討ほしいと求めました。ぜひ一緒にセットがいいかなと思うのですけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"現在のあっ旋というところでは、簡易浄水器というものは入ってございませんけれども、そういったところ、仮に河川下水道課とセットでやるときには、どのようなものが水の確保の際必要なのかといったところも、きちんと併せてお示ししていきたいと考えています。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"次に、しなみちレポートについて伺います。ただ問題なことは、これ視覚障害者はどうやって活用するのか伺いたいと思います。","respondent":"森道路課長","answer":"視覚障害者の方にしなみちレポートを使っていただくときに、今は視覚障害者の方がスムーズに使えるようなシステムにはなっていないというところは、１つ課題として認識しております。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"再三、点字ブロックが途切れているのだけれどもどうにかならないかというようなご意見を私たちも伺いますし。この制度が視覚障害者の方も使えるような形にしていっていただきたいと思うのですけれども、現状と今後の方針について伺いたいと思います。","respondent":"森道路課長","answer":"視覚障害者の方のための施設を整備していくに当たっては、障害者支援課をはじめとした福祉部門との連携が欠かせないと考えております。日頃からそういったブロックについては、しっかりと障害者支援課と連携して情報共有を図っておりますので、引き続き努めていきたいと思います。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは最後要望にとどめますけれども、ぜひ皆さんその視点で、先ほどの公園のことも一々障害者のためのなどと考えなくてもいいかなと。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"抗議行動について中止を求めたり、住民を公道から排除したりしたとの事実はあるのか伺います。一般歩行者の通行の妨げにならない公道上の抗議活動について、品川区は表現の自由を守る立場に立つべきだと思いますが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"東京都に確認をいたしましたけれども、そういったことは把握していないと聞いております。反対する自由というものもあると思いますので、そういったものを排除するという意識は、私どもは持っていないと言わせていただきます。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"声をかけている警備員や職員のほうが一般歩行者の邪魔になっている、公道の中央にいると思いますが、いかがでしょうか。表現の自由を守る立場に立つべきだと、そこに言及してほしいと求めましたが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"歩行するように促すような行動はあったやもしれぬという回答は受けておりますけれども、排除するというような行動は取っていないと聞いてあります。委員の２番目の質問ですけれども、品川区といたしましても、表現の自由に対して侵害するというような意識は持っておりません。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"この食事の質の確保へ、思い切った対策強化を求めますが、いかがでしょうか。具体的に、何をどのように具体化していくのかも伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"その事業と連携いたしまして、災害時協力協定を締結する予定です。そういった形で、避難所で温かい食事を提供できるような体制を強化してまいりたいと考えています。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"これら一つひとつをどのように具体化していくのか、また、どのように具体化に向けた検討を進めていくのか、ここを伺いたいと思います。さらには様々な形での防災訓練の実施で、計画の実践度を高めていく必要があると思いますが、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"全てを区として即時に対応するということは、可能な限り対応できるところから実施するということで、まずは協定事業者との提携を始めたところです。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、学校給食の活用についてさらに伺いたいと思います。災害時での食事の質の確保に向けて具体化を進めてほしいと求めましたが、現状と今後の改善、充実点などを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"学校給食の活用についてですが、こちらは他自治体の動向等も観察しながら、様々研究してまいりたいと考えています。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ他の自治体で見て研究はしてほしいと求めましたけれども、国の指針にも学校給食室の活用と位置づけられておりますので、早急に進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今回、まず初めに、密集法についてお伺いをさせてほしいと求めました。今回都内初となります、この密集法についてお伺いをさせてほしいと求めました。","respondent":"小川木密整備推進課長","answer":"土地の取得、そういったものの業務を適正かつ確実に行うことができる一般財団法人の申請を受けまして、区市町村が指定する機構となっております。","id":"exchange-081"},{"speaker":"高橋（伸）委員","kind":"確認","question":"共同住宅が２棟あると書いておりますけれども、これ確認であります。これ４９戸で正しいのかどうかということを、まず確認させてください。","respondent":"小川木密整備推進課長","answer":"長屋４９戸が正しい数字です。","id":"exchange-082"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"様々な諸問題、課題ありますが、特にこの当該町会や近隣の町会には丁寧な説明をしていただきたいと考えています。今後恐らく丁寧に説明していただくと思うのですが、この先どのように取り組んでいくのかということをお尋ねさせてください。","respondent":"小川木密整備推進課長","answer":"そういった、こちらの地区の防災街区整備事業の取組についてはお話をさせていただいて、共有を図らせていただいているところです。引き続きそういったような場面を捉えながら、しっかりと取組についても周知のほうは行ってまいりたいと考えています。","id":"exchange-083"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、３４１ページ、雨水利用タンク設置助成、グリーンインフラについてお尋ねをします。建築用語だと「うすい」と私は認識しているのですけれども、これどちらでもよろしいのか尋ねました。","respondent":"北原河川下水道課長","answer":"一般的には「うすい」という形で呼んではおるのですけれども、ただ「うすい」という言葉が、言葉だけ聞くと少し伝わりづらいということもありまして、状況に応じて「あまみず」という表現をすることもあります。","id":"exchange-084"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私も建築に携わっているものですから、「あまみず」と先ほどおっしゃったときに少し違和感があったので確認をさせてもらいました。理由はいろいろあるかと思うのですけれども、実際理由はどういった点で伸びないのかということをお知らせほしいと求めました。","respondent":"北原河川下水道課長","answer":"今年度の助成事業の利用の見込みですけれども、委員がご指摘のように、私たちが目指している量よりはちょっと少ないのかなという考えです。そういったものもきちんと示しながら、設置する側にとってもメリットがあるということをきちんと示していくことが重要かと考えています。","id":"exchange-085"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"雨水浸透施設整備という制度があって、１時間当たり１０mmの雨水流出を抑制するために、宅地内雨水浸透施設の普及に努めるとなっております。来場者の声がどのようにあったのかということのお尋ねと、もう１点が、どのような連絡会なのかということをお知らせほしいと求めました。","respondent":"北原河川下水道課長","answer":"エコルとごしで展示をやった際の声ということですけれども、例えば雨水タンクにつきましては、雨水をためておくといざというときに役に立つという意見や、雨水タンクを実際にもう設置をしている方などが、夏の水まきに実際に使っているというような意見がございました。","id":"exchange-086"},{"speaker":"高橋（伸）委員","kind":"提案","question":"これは提案なのですけれども、役員会を通して周知をしていくということは、すごくここは相当効果があるのかなと考えています。何というのですか、私は今後ぜひ提案をしていただきたいと考えていますけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"事業者、我々のほうもそう考えておりまして、今年度はそういった業界の方にも情報提供を差し上げているところです。我々としても少しでも普及が進むように、どういったやり方がいいか、今後も引き続き検討してまいりたいと思います。","id":"exchange-087"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認をして取り付けてもらう、ぜひ含めて、区政協力委員会を含めてよろしくお願いをいたします。何かあれば。","respondent":"北原河川下水道課長","answer":"私もこの２年間、この議会の場で様々な意見をいただきました。２年間という期間では解決できないこともありますので、きちんと引き継いで、１歩ずつ進むようにしてまいりたいと思います。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"今、事業者等と協議中というところで建設委員会等でも報告いただいていますけれども、現時点での進捗状況というものをまずお聞きしたいと思います。見守りというものについて、見守りというものはどのようなことをイメージ、想定をしているのかお聞きいたします。","respondent":"川原住宅課長","answer":"１点目の居住支援法人の協議の進捗状況についてのお尋ねからご回答をします。令和７年度で予算計上させていただいている部分で申し上げますと、令和７年１０月に創設を予定しています居住サポート住宅についてです。","id":"exchange-089"},{"speaker":"塚本委員","kind":"確認","question":"これは自治体が認定するものということで、区は居住サポート住宅というものの認定基準等策定しているかと思います。国からの指針が少し遅れているのだという話をお聞きしておりますけれども、その点についても確認したいと思いますが、。","respondent":"川原住宅課長","answer":"今後国はパブコメを実施して、また、そういった内容を待っているところです。耐震化の基準とか、こちらが協力させていただいている不動産団体への周知などに努め、引き続き関係各課との協議も進めてまいりたいと考えています。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"まだこれからそういった認定に向けてのいろいろな努力が必要だというところは伺いましたけれども、３戸、進めていただきたいと考えています。都のマスタープランでうたわれているところについて、区の管理計画というものがどのようになっていくのか、そこについてお伺いをいたします。","respondent":"羽鳥防災体制整備担当課長","answer":"委員がおっしゃられましたとおり、現在都のほうでこの２月に素案が公表されて、同様に、各区市町村で作成する計画のひな形というものも出されました。２０人に１基というところは、その対応策というところまで考えてまいりたいと、今まとめているところです。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問・要望","question":"非常に大事な計画でありますし、都と区と、そのような中での、今後は都のほうからきっといろいろな補助金などもつくのであろうというような予測がされますので、そういったこともしっかりと受け止めながらというか、認識しながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問","question":"昨年、しながわ水族館の目指すべき方向性に非常にマッチしているかなというように感じました。質問ですが、区として、アトアですけれども、調査されたり、現在されていますか尋ねました。","respondent":"大友公園課長","answer":"アトアという水族館についてですけれども、神戸市にある民間の水族館と認識しています。こちらにつきましては、昨年私どもも都市型水族館の参考といたしまして、視察をさせていただいているところです。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"であれば、ぜひその感想などがあればお聞かせいただきたいのですが、いかがか尋ねました。","respondent":"大友公園課長","answer":"アトア、こちらのほう、アートとアクアリウムが融合した新しい形の水族館であったと認識しております。この演出はほかに来館していた子どもたちからも人気で、喜ばれる展示手法だなと感じたところです。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私もほぼ同意見で、非常にいい展示というか、本当に都市型の水族館だなというように感じました。アトアは大体５,６００m2ということ、少し大きいぐらいなのですけれども、大体どれぐらいになるかという目安がもしあれば説明を求めました。","respondent":"大友公園課長","answer":"現在の想定ですけれども、中規模、延べ床面積５,０００m2程度の水族館とすることが示されているところです。今後この方向性に沿って、リニューアルの検討を進めてまいりたいと考えております。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"アクアパークが２万点、現在のしながわ水族館は１万点ということで、アトアは３,０００点しか実は展示がないのです。ぜひ積極的に研究して、取り入れていただきたいと思うのですが、最後に何かあれば一言お願いします。","respondent":"大友公園課長","answer":"視察をした感想とも、また少し重複するところはあるのですけれども、アトアは非常に参考になる水族館であったかと思います。その見せ方で勝負するというところでほかの水族館との差別化を図っているところで、非常に参考になるものであると認識しています。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"提案","question":"続いて提案したいことが、ＭＲ技術を活用した展示です。昨今ＶＲとか、ＭＲとか、ＡＲとか、様々あるのですけれども、ちなみにＭＲという技術についてはご存じでいらっしゃいますか尋ねました。","respondent":"大友公園課長","answer":"バーチャル体験の１種というところで認識していますが、現実とバーチャルの融合体験を含みで、ＭＲという形でそうしているのかなと考えております。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えばＶＲというものは仮想現実ということで、結構ごついゴーグルをつけて、言ってみたら、何ですか、全てが仮想空間ということです。現在、こういったＭＲの技術を採用している水族館、もし把握していれば説明を求めました。","respondent":"大友公園課長","answer":"様々なデジタルの手法というところが最近の水族館で取り入れられているというところは認識しているところ、また調査しているところではありますけれども、ＭＲというものを前面に打ち出して導入している水族館は把握をしているところはございません。","id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問","question":"このＭＲ技術を提供している会社がティフォン株式会社なのですけれども、ご存じでしょうか。ぜひ、もし研究といいますか、してほしいなと思うのですが、いかがか尋ねました。","respondent":"大友公園課長","answer":"リニューアルにつきましては、さらなる民間活力導入を検討したいというところで考えているところです。委員からの提案の内容も含めまして、先ほどご提案いただいた内容の活用等々も調査、検討してまいりたいと考えているところです。","id":"exchange-099"},{"speaker":"松永委員","kind":"質問・要望","question":"こうした地域の方が参加できる自転車安全教室の開催を要望しますが、いかがでしょうか。今後について伺います。","respondent":"山下交通安全担当課長","answer":"警察との連携も必要になってまいりますので、その辺はこちらからも働きかけながら実施してまいりたいと思います。この２年間におきまして、また終了について検討したところですが、終了という形に持っていかせていただいたところです。","id":"exchange-100"},{"speaker":"松永委員","kind":"質問・要望","question":"その現状について把握されておりますでしょうか。その対策について、警察署との連携について併せて伺います。","respondent":"山下交通安全担当課長、森道路課長","answer":"これは国のほうが今後の推移を見ながら定めていくものかなというように認識していますが、こちらのほうは啓発していきたいと考えているところです。私のほうで認識はしていないところなのですけれども、渋滞の解消… その工事に当たって、そこ１１m2ほど区のほうで借り上げを行っておりまして、東京都の敷地を道路として一部使わせていただいているという状況です。","id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"それに伴って損傷箇所などの改修工事を行われると伺っておりますが、バリアフリーについてはどうなのでしょうか。そうしたところも含めまして、バリアフリー化を進めて、内容がちょっと分からないので、そういったところもバリアフリーになっているのか伺います。","respondent":"大友公園課長","answer":"令和８年度に工事を進めていくところなのですけれども、バリアフリーの視点というところでは不足しているところが多々あるかと思います。その視点についても、この設計の中で含んで検討してまいりたいと考えているところです。","id":"exchange-102"},{"speaker":"松永委員","kind":"提案","question":"以前もちょっとご提案させていただきましたけれども、１５０周年にふさわしいイベントにしてほしいと求めましたが、いかがでしょうか。伺いますとの意見を述べました。","respondent":"大友公園課長","answer":"１５０周年である令和９年度、どのような形で迎えるかにつきましては、関係部署との連携をしまして、検討してまいりたいと考えているところです。基本的にはイベント等々、何かしらの形で実施するものと捉えております。","id":"exchange-103"},{"speaker":"松永委員","kind":"質問・要望","question":"どういった形で行っていかれるのかなということで、例えばモース博士につながりのある方を来賓として呼んでみてはいかがでしょうか。近隣の大田区との連携についてどのように考えておられるのか、品川区としての考えをお知らせください。","respondent":"大友公園課長","answer":"関係部署との連携をして、どのような形でのイベントが適切かというところは検討してまいりたいと考えているところです。大田区との関係等々につきましても、このイベントを機に、どのような形というところも改めて検討する形になるかと思います。","id":"exchange-104"},{"speaker":"松永委員","kind":"確認","question":"次に、３５５ページの新浜川公園のことについて伺います。確認です。","respondent":"大友公園課長","answer":"来年度に予定しております新浜川公園の改修の設計ですけれども、便所の改修等々のみではなく、公園全体の改修ということで検討しているものです。","id":"exchange-105"},{"speaker":"松永委員","kind":"質問・要望","question":"以前この質問をさせていただいたときに、実際やってみたのだけれども、日光、日当たりがよくて藻が多く発生して難しいと伺った記憶があります。カップルで遊べる観点からも、誰もが楽しめる環境になると思いますが、区の考えを最後に伺いたいと思います。","respondent":"大友公園課長","answer":"公園と水族館の相乗効果を促しまして、公園全体のさらなる魅力向上を目指してまいりたいと考えているところです。ちょっとなかなか断念したというところがあると認識しているところなのですけれども、幅広に検討はさせていただきたいと考えているところです。","id":"exchange-106"},{"speaker":"こしば委員","kind":"提案","question":"提案のほう、コミュニティバス試行運行の延長を求めたこと、意識調査をすべきという提案がございました。ですから、その評価項目の１つ、高齢者の居住状況も、コミュニティバスの導入に向けては欠かせない項目であったと思いますとの意見を述べました。","respondent":"櫻木地域交通政策課長","answer":"コミュニティバス運行に際して、シルバーパスを導入した経緯です。今回そのタイミングで新たに試行するに当たって、利用状況が読めないということであったことから一定の判断を下したと、そのような認識です。","id":"exchange-107"},{"speaker":"こしば委員","kind":"質問","question":"高齢者への一定の配慮が必要であったということと、利用状況はなかなか予測できなかったという答弁をいただきました。その中で、高齢者の中でシルバーパスの割合というものは、大体全体の中で何割ぐらいなのか教えていただけばと思います。","respondent":"櫻木地域交通政策課長","answer":"シルバーパスの収支割合ですが、おおむね４３.５％がシルバーパスの利用により無料でご利用いただいているという形になります。","id":"exchange-108"},{"speaker":"こしば委員","kind":"質問","question":"本来ならば得られるはずの運賃収入が得られないというわけですから、これ事業評価はマイナス、大きなマイナスになってしまうと思います。高齢者が交通の利便性を通じて移動の自由を享受できるベーシックサービスと私は考えますが、区のお考えを教えてほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"ベーシックサービスという観点からは、まずは区民の皆様に一定の選択のオプションを提示できるということが重要であると考えております。その中で、シルバーパスの適用有無等については、様々な住民合意の中で考えていくものだと考えております。","id":"exchange-109"},{"speaker":"こしば委員","kind":"質問・要望","question":"警察との協議では、この本通りにバスの待機場所を設置できるかどうかという検討も、実際協議の中であったという話を伺っております。この１３地域の中で最も交通の利便性が求められてきたものが西大井のエリアでありましたので、その辺り、最後に見解をお伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"委員からご指摘いただきましたとおり、いわゆる西大井の循環ルートにつきましては、現在運行ができていないという状況です。引き続き課題は残っているということは認識しておりまして、委員からご指摘いただきましたとおり、考えてまいりたいと考えています。","id":"exchange-110"},{"speaker":"こしば委員","kind":"質問・要望","question":"地域住民から移動の自由を求める声も届いておりますので、ぜひその辺りも勘案してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これ答弁求めません。今自動運転だ何だと、どんどん進歩しているのに、今さら、これもう何年検討するのか尋ねました。","respondent":"北原河川下水道課長、大友公園課長","answer":"こちらの事業につきましては、文化観光戦略課、大崎エリアマネジメントが中心になって実施している事業です。様々な部署でいろいろな取組がなされているということで… 公園利用、一定なかなか難しいという状況が発生しています。具体的に示せるところはございませんけれども、引き続き庁内としての検討課題というところで捉えていきたいと考えているところです。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"こういった意味では、死亡事故があった交差点や通学路などは優先をするべきだということで求めました。特に通学路、ここに関しては積極的に普及を進めていってほしいと求めましたが、その辺の考え方を説明を求めました。","respondent":"山下交通安全担当課長","answer":"ただいま委員からお話がありました歩車分離の改正につきましては、私も認識しています。必要性を、我々のほうでも様々考えながら、そういった歩車分離式信号機が浸透していくようなことを進めていきたいと考えているところです。","id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろん信号機は警察の管轄ですからあれですけれども、また通学路だと教育委員会とも連携をしながら、ぜひ進めていっていただきたいなと思います。これはもう時間がないので要望ですが、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"こんの委員","kind":"質問","question":"３４９ページ、３６５ページ、順不同でお聞きしてまいりたいと思います。どこでどのような社会実験を実施されようと考えているのか、簡潔に、具体的な事業内容をお願いしたいと思います。","respondent":"中道都市開発課長","answer":"社会実験の場所ですが、大井町のどんたく通りで、実施するというような予定をしています。はにぎわいのイベントできる場など、そうした中でにぎわいや、また回遊性を生んでいきたいと考えています。","id":"exchange-115"},{"speaker":"こんの委員","kind":"確認","question":"そこでお聞きするのですが、この入居促進事業を、これそれぞれの所管でやってくださっているのですか。そこを確認させてください。","respondent":"川原住宅課長","answer":"入居の支援、いわゆる居住支援事業というところでは、各課の支援についても。いわゆる要配慮者、それぞれの要配慮者に応じて各課が支援をしていますところについては、居住支援においては各課で予算を取っているような形ですが。","id":"exchange-116"},{"speaker":"こんの委員","kind":"質問","question":"初回の保証委託料は、単身者も世帯も同額５万円を補助したり、あるいはひとり親世帯については、初回の保証委託料上限１０万円、これだけです。情報収集しながらそこを整理していくということも住宅課ではないかなと思われるのですけれども、その辺はどのようにお考えか尋ねました。","respondent":"川原住宅課長","answer":"区のみならず、今後の居住支援協議会などでも有識者の意見を諮りながら、どういった支援が必要かというところを検討してまいりたいと思います。今支援の事業として持ってありますので、その継続の必要性支援の在り方というところから、まずは検討する必要があると考えています。","id":"exchange-117"},{"speaker":"こんの委員","kind":"提案","question":"１つ提案なのですけれども、２年ごとに更新が、契約の更新が行われます。ですから、こうしたこともぜひ検討の課題として上げていただきながら、進めていただきたいなと思いますとの意見を述べました。","respondent":"川原住宅課長","answer":"現在実施している、先ほど……。","id":"exchange-118"},{"speaker":"鈴木委員","kind":"提案","question":"都市計画道路整備事業について伺いたいと思いますが、１１月には債務負担行為で補正予算も組まれました。第５次に向けて優先整備路線の、何というのですか、その提案というものはいつ頃になるのかということについて説明を求めました。","respondent":"高梨都市計画課長","answer":"委員からもご案内がありました東京都と５１区市町による検討を、昨年の１０月から、東京都が事務局となって我々も一緒に検討をスタートしています。","id":"exchange-119"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も地域の方と一緒に地域に入って様々ご意見を伺い、もう本当に１０年前を思い出すのですが、もう本当に軒並み反対の声が出されたのです。地域の方の声を聴いていただきたい、そのような場面をつくっていただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"この次期整備方針につきましては、この議会をはじめ、検討の中ではそれを活かしていきたいなと考えているところです。広域に見て、今まさしく都と一緒に鋭意行っている必要性の検討の中で活かしてまいりたい、このように考えているところです。","id":"exchange-120"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２７号線は、優先整備路線の中には入れないようにしていただきたいということで要望もさせてほしいと求めました。水が使える限りはトイレが使えるというようなことで考えていいのかということが１点、それからあと、その点と２点伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長、北原河川下水道課長","answer":"避難所までの下水管のほうは、耐震化１００％済んでいるところです。基本的に水が使えればトイレも使えるという状況です。 そういった意味では、下水道管の耐震化がなされていれば、基本的にはトイレも利用できるという状況になります。一般の住宅につきましては、優先順位をつけて進めているところで、そういった計画は今のところございません。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問","question":"３３１ページ、３４３ページ、下水道管改修事業についてお伺いします。ですから、１０年前と今とで、まずお伺いします。","respondent":"平原防災課長","answer":"１０年前は２万４,０００棟ぐらいが想定されていたところ、令和４年想定では９,０００棟といったところで、大幅に減少しています。それに伴いまして、死者数等々の人的被害も減少しているものというように認識しています。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問","question":"届きましたでしょうか。全く１円たりともその変化のない特別会計を、新年度もまた予算計上して議決をしてしまっていいのか、ここをお伺いしたいと思います。","respondent":"平原防災課長","answer":"ただ、そういったところを勘案して、検討していますけれども、一方で能登半島地震を受けまして、全般的に政策を見直しています。何らかの形でこれの変更であるとか、そういったことも考えていくことになるかなと思いますけれども、現状で出させていただいているところです。","id":"exchange-123"},{"speaker":"田中委員","kind":"質問","question":"今年は阪神・淡路３０年目ですなど、要は現状を見直して、早期にしっかりとした対応をするための思いも込めてご挨拶されていらっしゃると思います。その意識が本当にここにどこまで伝わっているのかという思いをしてならないのですけれども、改めてお伺いしたいと思います。","respondent":"平原防災課長","answer":"１０年前の被害想定と大幅に変わったところがございまして、１０年前とは大幅に対応するところも変わったところもあります。現状予算額で変更といったところまではいかなかったといったところですが、今後はちょっとそういったところもまた勘案してまいりたいと考えています。","id":"exchange-124"},{"speaker":"田中委員","kind":"質問・要望","question":"ここはもうどうしても東京都に委ねなければいけませんし、オイルボールもなくなりますし、長寿命化につながると思います。このようなところこそ都と連携して、河川下水道課としても住民にアピールをしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"東京都下水道局のホームページのリンクを河川下水道課で貼っておりまして、ポスターも河川下水道課の前に掲出しております。今後も連携を図ってまいりたいと考えています。","id":"exchange-125"},{"speaker":"せお委員","kind":"質問","question":"３３１ページ、交通安全啓発事業、３３５ページ、しなみちレポートについてお伺いします。どれが効果があったのか、あるのか、その辺どう感じておられるか説明を求めました。","respondent":"山下交通安全担当課長","answer":"は学校、それぞれの関係機関等に配布しながら、事故防止対策に取り組んでいるところです。交通安全教育費で賄っているかといったことも、それと含めて交通事故防止対策費というところでも、併せて予算を組んでいるところです。","id":"exchange-126"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、そもそも子どもが飛び出すことができないだったり、子どもが線引きしやすいところで仕組み、道路をつくることが必要だと考えています。教えていただきたいということと、今後も積極的にこういった飛び出せない工夫のところ取り入れていく方針なのか、方向性なのか説明を求めました。","respondent":"山下交通安全担当課長","answer":"今後やるかやらないかですけれども、こういったことは必要であれば継続していくことも大切だと考えています。必要に応じて必要なことを、できることを一つひとつ対策、対応してまいりたいと考えています。","id":"exchange-127"},{"speaker":"せお委員","kind":"提案","question":"合わせても９００万円前後で、もう本当にここは子育て支援と思って、さらなる充実を要望いたします。こちらも会派のまつざわ委員が提案しています周知と、あと利便性の向上のために、こちらも検討状況を説明を求めました。","respondent":"森道路課長、大友公園課長","answer":"メールでお問合せがあった際には、それの返信としてしなみちレポートのＵＲＬをつけてお知らせする等の、こうした周知を行ってまいりました。町会への働きかけということもご提案いただきましたので… 現在の周知方法といたしましては、チラシ配布等々、工事案内等々について登録アプリの形態であったり、様々な手法で登録しています。引き続き公園の看板についても検討してまいりたいと考えているところです。","id":"exchange-128"},{"speaker":"若林委員","kind":"質問","question":"３６６ページの防災費について伺います。こういった考え方について、品川区の見解を伺いたいと思います。","respondent":"平原防災課長","answer":"そういったところを、地区防災計画というものを地域防災計画の１計画として、地域の方々にお考えいただくというような取組を進めております。品川区強靱化計画でも併せて実施しているものですので、今後そういったところを総合的に評価していく必要があるものと認識しています。","id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"加えて、三木小学校、大崎中学校と２つの区民の避難所があります。両避難所と周辺の環境について、当局はどのように捉えているかお聞きします。","respondent":"小川木密整備推進課長","answer":"平成２９年度より密集住宅市街地整備促進事業を導入しまして、防災生活道路から避難所をつなぐ道路重点整備細街路として位置づけているところです。","id":"exchange-130"},{"speaker":"若林委員","kind":"質問","question":"今の２つの学校については、改築困難という難題を今抱えているところです。どのような形で進めれば、一段とこの脆弱な地域の防災強化がなされるのか、その進め方について現在のお考えをお聞きしたいと思います。","respondent":"小川木密整備推進課長","answer":"まちづくり協議会等を行いながら、地域の皆様の声を聞きながら、防災まちづくりへの取組を行ってあります。そういう面的なところの取組についてのご意見等もいただきながら、総合的な防災まちづくりに取り組んでまいりたいというふうに考えてあります。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問","question":"学校についての言及は、今のご答弁の中ではございませんけれども、また、それについては、別途取り上げたいと存じております。水辺利活用に向けた基礎データ調査委託が８４０万円ほど計上されておりますけれども、これについてのご説明を、最後にお聞きしたいと思います。","respondent":"北原河川下水道課長","answer":"その評価に当たっては、ＥＢＰＭ、エビデンスに基づく政策立案が重要と考えています。滞留時間など、人の流れをカメラを使って収集し、分析を行うような委託になってあります。","id":"exchange-132"},{"speaker":"西本委員","kind":"質問・要望","question":"これからどう考えられているのかということと、これは試行ですから、いつ結論を出すのですか。一番先にコミュニティバスの運用を始めたわけですから、そこをまず考えてほしいと求めましたが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長、羽鳥防災体制整備担当課長、櫻木地域交通政策課長","answer":"もう一度検討させていただければと存じます。令和６年の９月から１１月に、各地区で実施した防災訓練においても… プッシュ型の支援物資が届きますが、アレルギー対応食品ですとか、１週間はそういったものを中心に備蓄していただければというふうに思います。今… 区としましては、引き続き課題が残っているという認識がありますが、新たな交通サービス状況等を注視して、考えてまいりたいと考えています。","id":"exchange-133"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の中で気軽に備蓄ができる、そういうことも考えていただきたいなというふうにお願いしたいと思います。これはいつまでに結論を出すのかなというところでは、やっぱり西大井四丁目周辺は一番交通の便が悪いので、ぜひ検討を早急にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"西村委員","kind":"質問","question":"３６６ページ、防災費全般について、国民保護訓練について、および区における自衛隊と防災力の強化について伺ってまいります。その概要や成果について伺います。","respondent":"伊藤災害対策担当課長","answer":"国民保護訓練の戸越銀座商店街、戸越駅の訓練について説明をいたします。今回の訓練は戸越地域での限られた地域での訓練でしたので、この成果を何らかの形で区内に広めていければと考えています。","id":"exchange-135"},{"speaker":"西村委員","kind":"質問・要望","question":"訓練の中止を求めるのではなく、むしろその充実を図り、地域住民が安心して暮らせる環境を構築することこそが政治の責任だと考えます。平和宣言に反するものではないと考えますが、国民保護共同訓練における区の考えを伺います。","respondent":"伊藤災害対策担当課長","answer":"国民保護共同訓練における区の考え方ですが、実施主体であります東京都からの依頼を受けて実施したという前提があります。一方で地震、風水害などの対応と同様に、区民の安心と安全を守るため必要な訓練であると考えています。","id":"exchange-136"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば、水族館内で防災クイズや避難訓練を組み合わせたり、より体験型のイベントとなれば、さらに効果的ではないでしょうか。今後も様々な取組をきっかけに、自衛隊の役割や仕事を知る機会が必要だと考えますが、区のお考えを伺います。","respondent":"伊藤災害対策担当課長","answer":"先ほども答弁申し上げましたが、自衛隊の募集広報につきましては、区の法定受託事務ということで実施をしている内容です。関係法令に基づいて実施をしています。","id":"exchange-137"},{"speaker":"西村委員","kind":"質問・要望","question":"東日本大震災を自ら経験され、南海トラフの防災計画改定や広島の土砂災害、数々の台風被害にも直接携われたと伺っております。区には現在４名の元自衛官の方がいらっしゃると伺っております。","respondent":"滝澤災害対策担当部長","answer":"そういう意味では、各部での訓練も実施するような体制に変わったということで、１つ変化があったと思います。四十数年ぶりの東京都との総合防災訓練が実施できたこと、国民保護訓練が実施できたことは、安全のための一助となれたかなと考えています。","id":"exchange-138"},{"speaker":"西村委員","kind":"意見","question":"全自治体でこれが広がれば、全国的に広がればいいのにというふうに思っておりますので、ぜひ引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういう形で、子育て支援という視点をさらに都市環境、防災、まちづくりが持って、常に考えながら事業を進めていってほしいと求めました。社会全体で子育てを支えるということは、区の所管全体で支えるということにもつながると思いますが、そこの辺りいかがか尋ねました。","respondent":"溝口防災まちづくり部長","answer":"私のほうからは、ふだん区民の方が多く利用している道路、公園、そういったものを管理している観点から、少しお話をさせていただければと思います。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"都市公園の維持管理費は約２億円、整備費は約３億円が削減されています。子育ての公園だけではないかもしれませんけれども、ここら辺の２億円、３億円の削減というのはどういうような状況なのか尋ねました。","respondent":"大友公園課長","answer":"こちらの予算と所管からの要求との差分というところのご質問かと思われます。その結果、これは翌年度がより効果的ではないかなどを踏まえて、調整が働いたものと理解しております。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"３５５ページの勝島人道橋整備工事などについてお尋ねします。完成した令和１０年には２,３００人になるというような形で、これは令和６年度に進んでいると思うのですが、お願いします。","respondent":"大友公園課長","answer":"新浜川公園の改修を実施していくというところにおいて、また、安全に通行できるのかというところを含めて検討しています。今のところ、護岸の形状等々の変更というのはなかなか難しいというところがありますので、今年度取りまとめているという状況です。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ちょっと大きな話で、長いレンジの話になりますけれども、どのように考えになっていらっしゃるか尋ねました。","respondent":"大友公園課長","answer":"そこについては、なぎさ会館の今後の活用等も含まれているところですけれども、多角的な視点から検討すべきものというところで考えてあります。委員からのご提案の区民公園からしながわ花海道の連続性等につきましても、多角的な視点の一つと認識しています。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３３５ページのほうは、令和６年にはあったのですが、令和７年の予算書からは消えてしまいました。非常にメリットがあって、温かみ、景観があるのですが、そこら辺の事情をお願いします。","respondent":"森道路課長","answer":"令和５年、令和６年と整備をさせていただきました。課題がいろいろあるのかなというふうに考えておりまして、今後増やしていくかどうか確認をしていきたいというふうに思っております。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問","question":"既存の整備で、区内で実際に自転車の交通事故が減ったというふうなデータはあるのか伺いたいと思います。車道の左端から１ｍの位置を走行する自転車の増加、既存の整備の結果、減ったというふうなデータがあるか伺えればと思います。","respondent":"山下交通安全担当課長","answer":"昨年発生は４３８件、令和５年と比べますと、マイナス２４件となっておりまして、減少傾向にあるのかなと。警視庁からの情報によりますと、歩道の自転車の通行も減っているということで伺っているところです。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"今のご答弁の中で、通行帯を整備した結果、減ったかどうかというのは多分データがないというふうなところなのかなというふうに解釈いたしました。どうしても車道側で交差点の赤信号を待つので、ナビライン、例えば交通事故が発生してしまったというふうな事例はあるのか尋ねました。","respondent":"山下交通安全担当課長","answer":"警察の取締り、そういったもろもろの、全ての結果として減少していると認識しています。衝突してしまうと、死亡事故にもつながる危険なものですので、そういったものは排除していかなければいけないのかなというふうには認識しております。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問","question":"で、例えば交差点のところで、車道側に自転車の巻き込みを防止するためのソフトポールを立てるというふうな対策もあるやに伺っております。先ほどの左折の巻き込み事故を防止する観点で、こういうふうなことをナビライン、ナビマークと併せてやっていくというふうな計画はあるのか尋ねました。","respondent":"森道路課長","answer":"今おっしゃられましたタワーポールの設置であるとか、ストップマークを設置するとか、そういったものについては進めてまいりました。今回、当然そういう交差点のところで歩行者や車との接触というのは出てくるのではないかというおそれが検討の中で出てくると思いますので。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"どう啓発していくのかというのがあるのですけれども、ナビラインの中で、右側通行禁止ですというのをはっきりと目に見える形で示していく。なので、自分たちの目線に合うところで、禁止なのだということが分かるように示していただくという手法があると思いますが、いかがか尋ねました。","respondent":"森道路課長","answer":"どこでもそういう形でやられているので、区内だけそういったところをやるとすると、逆に混乱するところもあるのかなというふうには思います。逆走が禁止されている、交通安全担当としっかり情報共有しながら、いろいろなところで周知・啓発をしていければなというふうに思います。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問","question":"最後に防災関係組織経費について伺います。これはどういう事業なのか伺えればと思います。","respondent":"平原防災課長","answer":"今年度行いましたタウンミーティングでも、防災に関心がありながらも、何をしていいか分からないという方が結構多くございました。女性の参加率が低いとかというのは、防災学校とかでそういうコースをつくっていくなど、複合的に積み重ねたような事業を行っていく予定です。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問・要望","question":"要望というところで、防災関係はどうしても町内会、ぜひうまくやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"藤原委員","kind":"質問・要望","question":"どうしても令和１２年度まで延長してほしいと、東京都に要望してほしいと言ってきましたが、今どういう状況にあるか教えてください。ですから、補助２９号線のときに、ぜひ東京都に要望していただきたい。","respondent":"小川木密整備推進課長、高梨都市計画課長、大友公園課長、中道都市開発課長、川原住宅課長、森建築課長、森道路課長","answer":"不燃化特区支援制度がしっかりと継続できるように継続させていただいて、建物の不燃化促進というものに努めてまいりたいというふうに考えてあります。私からは、ニコン本社開業と補助２９号線と横須賀線の交差部のことについてお答えをします。補助２９号線と横須賀線の交差部… その中で壁泉、またはそれに代わる水系施設を整備するのか、引き続き検討しています。駐輪場を一定確保する形で設計を進めているです。","id":"exchange-151"},{"speaker":"藤原委員","kind":"質問","question":"そして花壇を移しますと、課長、どういうことですか。そうしたら、お花だらけにすればいいではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは３５１ページの品川駅南地域周辺まちづくり事業から、品川浦周辺地区再開発について伺いたいと思います。今日は、質問は、この間は地権者数を聞いてきましたけれども、計画地域に住んでいる住民数を地区別に教えてほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、区では令和５年度に「まちづくりニュース」というものを委託で発行しておりまして、地区内の全戸に配布しています。その数が約２,８００世帯となっていますので、ちょっと参考値にはなってしまうのですけれども、今このような状況となっています。","id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現にある都営住宅４棟、６６５戸は地区内に残すようにと私たちは求めていますし、そのことを区として東京都に求めてくださいと言っていますけれども。安心して住み続けているという声ですので、この都営住宅を残すようにぜひ都に求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"準備組合のほうでは、品川浦の歴史や水辺、地域経済の発展のためにまちづくりの検討を行っているものです。都営住宅をなくすような検討しているとは、区は認識してございません。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ東京都に残すように求めていただきたいと強く要望したいと思います。伺いたいのですけれども、どこに何を見ることを目的に行くのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"土地利用の方針であったり、具体的にどれということではないのですけれども、こういったものに準備組合と一緒に出席しているのが主になります。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なおさら都営住宅を残すように求めてほしいと求めましたし、都営住宅に限らず、高齢者もたくさんいる地域です。住み続けたい人が住み続けられるまちづくりに転換すべきだと思いますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"まちづくりは地域住民が主体となって現在検討を進めてあります。今後もまちづくりに関する地域住民の様々な声に耳を傾けてまいりたいと考えているところです。","id":"exchange-156"},{"speaker":"大倉委員","kind":"質問・要望","question":"現金ではなくキャッシュレスということでぜひ進めていっていただきたいということで以前要望したのですが、現在どのようになっていますでしょうか。前回聞いたときは２３団体ということで、さらに進めていってほしいと求めましたが、ご所見を伺います。","respondent":"平原防災課長、山下交通安全担当課長、川崎土木管理課長","answer":"区ではＳＮＳ、具体的にはラインを使った避難所の受付といったところで、まずはそこの効率化を図ってまいりたいと思います。なお、その後… 来年度の１０月以降に、新たな業者の選定を行いまして、クラウド型のシステムを使うこととしております。申し訳ありません、回答できかねますが… 令和６年度に電子申請サービスを導入し、若い方も含めて幅広く、ボランティアに協力してくださるようにということで、取組を進めてまいりました。","id":"exchange-157"},{"speaker":"大倉委員","kind":"質問","question":"避難所の情報発信と情報収集についてもＤＸ化できないかということも聞いたので、伺えればと思います。そういった団体の交流を進めていく中で、また新たな広がりがあったりするのかなということもありますので、併せて伺えればと思います。","respondent":"平原防災課長、川崎土木管理課長","answer":"これまでもデジタル化は随分推進してきているところでございまして、様々な媒体、これについては今後とも拡大していこうと思っているところです。これまでは基本的に区民からの通報等により対応してきたところ、例えばＸなどの発信を… これは区としても真剣に取り組んで、私どもとしても、何か効果的な方法があるかどうかも含めて考えていきたいと思います。ご意見ありがとうございました。","id":"exchange-158"},{"speaker":"大倉委員","kind":"質問","question":"結構大変で、なかなか地道な活動なので、いろいろな人と交流していくというところがいいかなと。いかがでしょうかということと、マンパワーの不足という課題があるかなと思っておりまして、現状を説明を求めました。","respondent":"川崎土木管理課長、平原防災課長","answer":"しなみちレポート等の活用の検討ということで、そちらも含めての検討にはなりますが、２３区でもいろいろ懸念しているところはあります。肌感覚ではあるのですけれども… いわゆる１.５次避難所としての福祉避難所の活用は、補完避難所を活用して福祉部とともに進めているところです。","id":"exchange-159"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは３６９ページ、品川消防団長からぜひ議会で取り上げてほしいという要望がありましたので、質問していきます。分団格納庫、格納庫はあるのですけれども、積載車が入るようなものを設置していただきたいというのが切なる要望ということでした。","respondent":"伊藤災害対策担当課長","answer":"特に第三分団につきましては、可搬ポンプ積載車が入ることができない施設を持っているということで認識しています。区内でも情報共有をしておりまして、適地について今、検討しているような状況です。","id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問","question":"後々分かったのですけれども、下神明にある神明児童遊園ですか、たこ公園。怪獣のコンセプトを継承し、かいじゅう公園として再整備、これは区立子供の森公園の名称をかいじゅう公園に変更するということか尋ねました。","respondent":"大友公園課長","answer":"子供の森公園の名称を変更するかというご質問なのですけれども、子供の森公園の名称はそのまま「こどものもりこうえん」となりますが、今回都市計画公園という形にするに当たり、「子供」の「供」をひらがなに変更させていただいてあります。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特に天王洲地域でそれができるようになれば一石二鳥なので、ぜひお願いしたいという要望でした。天王洲都営団地の自治会長からも同様の要望もいただいておりまして、様々な場でお願いをしてまいりましたが、この点のご検討はいかがか尋ねました。","respondent":"大友公園課長","answer":"ご不便を軽減するために、野球場とその他の場所に分けて工事をすることで、公園が使えない期間をなるべく短くするよう検討しております。委員からもお話がありましたような代替等も含め、引き続き工事期間のご不便を少なくするための手法を検討しています。","id":"exchange-162"},{"speaker":"あくつ委員","kind":"確認","question":"それ以外のこともできることはまた引き続き考えていただくということで確認させていただきました。３６３ページ、マンション管理支援事業から伺ってまいります。","respondent":"川原住宅課長","answer":"マンション管理支援事業のうち、建替・修繕事業の内訳に対するご説明をします。マンション建替・修繕の相談会の実施、こちらの派遣料の助成を区が行っているといった内容です。","id":"exchange-163"},{"speaker":"あくつ委員","kind":"質問","question":"以前の一般質問への答弁では、少し古いデータですけれども、区内にはこのような築４０年以上の区分所有マンションが約４７０棟あるということでした。この２つの老いに対する対策として、区内で建て替えを行ったマンションがあるのか、あるとするならばそれは何棟なのかお知らせください。","respondent":"川原住宅課長","answer":"平成３０年に書類を受理してから、これが令和４年の最後の認可まで、約５年の期間を要したという建て替え事業が１件ございました。こちらについて、区が間接的に関与することで、区分所有者からの信頼等も得られやすかったのだと考えられます。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと建て替えの管理組合の意向調査も含めて、先立つ準備をいろいろ行っていく必要があるのではないでしょうかという質問です。２つお聞きします。","respondent":"川原住宅課長","answer":"こういった先生からの意見を伺いながら、ほかの管理組合様が共有できるような事例という形でも今後検討していきたいと思います。必要性についての区の認識ですが、これまでの計画が終了し、次年度の計画を更新するまでの間に考えていきたいと思います。","id":"exchange-165"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"私からは、予算書３６７ページ、防災普及教育費、３６９ページ、消防団運営費についてお聞きします。把握が難しいのかもしれないですけれども、防災学校を受講した人数は、数字を取っているものなのか説明を求めました。","respondent":"平原防災課長","answer":"令和７年度予算で新たに防災士資格の取得支援を行うこととなった理由ですけれども、品川区では、しながわ防災学校の防災区民組織コース。なお、品川区内の防災士認証登録者については、６４４人ということで聞いているところです。","id":"exchange-166"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ここが難しいのは、同じものをどう引き込んでいくのかなというのは少し課題があると思いますけれども、そこはしっかりやってほしいと求めました。防災区民組織をしっかりとつなぐ組織というのは、まず品川区でやるべきではないかなと思いますけれども、ご見解をお願いします。","respondent":"平原防災課長","answer":"さらにはそういう方々を防災区民組織とつなげていくといったところが、区がハブとなってやっていく役割かなというふうに思ってあります。そういう中から地域防災の担い手を拡大していこうといったところを今考えているところです。","id":"exchange-167"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"でもこれは所管が違うので、今日は要望します。要配慮者の勉強についてご見解を説明を求めました。","respondent":"平原防災課長","answer":"実際に災害が発生したときに、地域にいらっしゃる方をどのようにご支援いただくかといったところも、お話合いしていただいたところです。災害発生時に要配慮者を支援する体制というものを強化していく必要がまだまだありますので。","id":"exchange-168"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、そこに住む人がいないのですけれども、公助につながるまでにはどうしても時間があるのですよね。例えば、品川区から３消防団にお願いというのはできるのか、できるならどういうふうにやっていくのか、まずそれを説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"ただいま消防団から区のほうに何らかの依頼があった場合に対応できるかということで、地域から要請があった場合に出てきていただいております。区が主催するイベント等で、必要であれば区のほうから、要請できると考えております。","id":"exchange-169"},{"speaker":"まつざわ委員","kind":"確認","question":"それは確認しました。イベント消防団というのですか、夏は総合訓練とか週３回、になってしまうという声も聞いています。","respondent":"伊藤災害対策担当課長","answer":"東京医療保健大学と連携してございまして、昨年ですと２０名程度の方が品川消防団に入団されたというような話も聞いております。で、そういったものが団員の増加につながるのではないかと思いますので、区内の消防団のほうにも情報共有させていただければと考えています。","id":"exchange-170"},{"speaker":"まつざわ委員","kind":"質問","question":"それはちゃんと対面でいいですよと言ってくれるのですから、そういう関係性を生み出していくべきだと思っていますね。どうかそういった部分にもしっかりと踏み込んで、話を聞いていただける機会を設けてほしいと求めましたけれども、ご見解を。","respondent":"伊藤災害対策担当課長","answer":"どうしても参集ということで、消防団本部、分団本部に行かなければならないというような状況もあります。平素からのつながりという面で考えたときに、消防団の方々、情報共有を図るといった方策もあるのではないかと考えております。","id":"exchange-171"},{"speaker":"まつざわ委員","kind":"意見","question":"最後ですけれども、伊藤課長も品川区に来られて２年ですね。この２年間を振り返って品川区、また、消防団に対する思いというのを最後にぜひ聞かせてくださいとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"荏原消防団におかれましても、全国大会にて準優勝されたということで、こういう限られた制約のある中で非常に頑張っている存在だと認識しております。この２年間現時点で学んだことは私の今後の消防人生においても非常に役に立ったと感じてあります。","id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/552633?Template=document&Id=7011#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":132743,"voices":405}}]);
